# Active theme for the app. Change this string to switch themes app-wide.
# ----------------------------------------------------------------------------
# Semantic/status colors. These carry meaning (error, success, warning, info)
# and stay the same regardless of which visual theme is active - you don't
# want "failed" to stop being red just because you switched themes. They're
# still centrally named here so nothing is a mystery hex code.
# ----------------------------------------------------------------------------
STATIC_COLORS = {
    "status_danger":        "#dc2626",   # error / failed text
    "status_danger_bg":     "#fecaca",   # error background
    "status_warning":       "#d97706",   # warning text
    "status_warning_light": "#f59e0b",   # warning icon/border
    "status_info_bg":       "#dbeafe",   # info background
    "status_info_bg_alt":   "#f0f5ff",   # info background (lighter)
    "status_success":       "#10b981",   # success/passed
    "status_success_alt":   "#16a34a",   # success (alt shade)
    "status_success_bg":    "#f0fdf4",   # success toast background
    "status_success_text":  "#065f46",   # success toast text
    "status_danger_hover":  "#d32f2f",   # danger hover state (buttons)
    "status_info":          "#1d4ed8",   # info/link text
    # Step-chip validate vs. normal color coding (utility step widget)
    "chip_validate_text":        "#806000",
    "chip_normal_text":          "#15803d",
    "chip_validate_eye_hover":   "#f0e68c",
    "chip_normal_eye_hover":     "#bef264",
    "chip_validate_close_hover": "#fff9e6",
    "chip_normal_close_hover":   "#ffebee",
}

CURRENT_THEME = "DXC Theme 2"
_ACTIVE_THEME = CURRENT_THEME


def get_active_theme():
    """Returns the name of the currently active theme (used by dialogs)."""
    return _ACTIVE_THEME


def set_active_theme(name):
    """Sets the app-wide active theme. Main window / dialogs read this
    when they build their stylesheets."""
    global _ACTIVE_THEME
    if name in THEMES:
        _ACTIVE_THEME = name


def get_theme(name=None):
    """Returns the palette dict for the given theme name (or the active theme),
    merged with the fixed semantic/status colors (STATIC_COLORS)."""
    palette = dict(THEMES.get(name or CURRENT_THEME, THEMES["DXC Theme 2"]))
    palette.update(STATIC_COLORS)
    return palette


def render_qss(template_str, theme_name=None):
    """Fills a QSS template (using $token placeholders) with a theme's colors."""
    return Template(template_str).safe_substitute(get_theme(theme_name))


def theme_color(role, theme_name=None):
    """Returns the hex string for a single theme role. For use in QColor(...)
    and other places outside QSS strings, e.g. QColor(theme_color('primary_color'))."""
    return get_theme(theme_name).get(role, "#000000")


