    def _apply_log_panel_visibility(self):
        """Show or hide the log toggle button based on the setting."""
        cfg = getattr(self.main_window, 'execution_config', {}) or {}
        enabled = bool(cfg.get('show_execution_log', False))
        self._log_toggle_btn.setVisible(enabled)
        if not enabled:
            self._log_view.setVisible(False)
            self._log_toggle_btn.setChecked(False)

    def _toggle_log_panel(self, checked):
        """Expand or collapse the log panel."""
        self._log_view.setVisible(checked)
        self._log_toggle_btn.setText(
            "▼  Execution Log" if checked else "▶  Execution Log"
        )

    def _log_append(self, text):
        """Append a colour-coded line to the embedded log panel."""
        line = text.rstrip('\n')
        if not line:
            return
        if any(x in line for x in ('✅', 'passed', 'complete', 'Found', 'Passed')):
            color = '#4ec9b0'
        elif any(x in line for x in ('❌', 'failed', 'Failed', 'error', 'Error', 'not found')):
            color = '#f48771'
        elif any(x in line for x in ('⚠️', 'Skipped', 'disabled', 'stopped', 'Stopped')):
            color = '#dcdcaa'
        elif line.startswith('Step '):
            color = '#9cdcfe'
        elif line.startswith('  ') or line.startswith('\t'):
            color = '#ce9178'
        else:
            color = '#d4d4d4'
        self._log_view.appendHtml(
            f'<span style="color:{color}; white-space:pre;">'
            f'{self._html_mod.escape(line)}</span>'
        )
        sb = self._log_view.verticalScrollBar()
        sb.setValue(sb.maximum())

    def _log_start_run(self, test_case_name):
        """Print a separator header for each test case run."""
        from datetime import datetime
        ts = datetime.now().strftime('%H:%M:%S')
        sep = '─' * 55
        self._log_view.appendHtml(
            f'<span style="color:#569cd6;">{sep}<br>'
            f'▶&nbsp;&nbsp;{self._html_mod.escape(test_case_name)}&nbsp;&nbsp;[{ts}]<br>'
            f'{sep}</span>'
        )
        sb = self._log_view.verticalScrollBar()
        sb.setValue(sb.maximum())

    def add_project(self):
        """Opens a dialog to add a new project."""
        from PyQt6.QtWidgets import QInputDialog
        
        project_name, ok = QInputDialog.getText(
            self,
            "Add Project",
            "Enter project name:"
        )
        
        if ok and project_name.strip():
            project_name = project_name.strip()
            
            # Check if project already exists
            if project_name in self.projects:
                QMessageBox.warning(self, "Duplicate Project", 
                                  f"Project '{project_name}' already exists.")
                return
            
            # Create new project
            self.projects[project_name] = {
                'test_cases': {},
                'expanded': True
            }
            
            # Add project header to list
            self.add_project_header(project_name)
            self.save_execution_data()
            
            QMessageBox.information(self, "Success", 
                                  f"Project '{project_name}' created successfully.")



