    def _make_glyph_icon(self, glyph, color_hex, size=16):
        """Renders a single unicode character as a QIcon in a fixed color.
        Used for header glyphs (like the little arrows next to Row/Col/Len)
        that need to stay a constant color regardless of the header text's
        own themed color, since QSS can't color-split one label string."""
        pixmap = QPixmap(size, size)
        pixmap.fill(Qt.GlobalColor.transparent)
        from PyQt6.QtGui import QPainter
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setPen(QColor(color_hex))
        font = painter.font()
        font.setPointSize(int(size * 0.65))
        painter.setFont(font)
        painter.drawText(pixmap.rect(), Qt.AlignmentFlag.AlignCenter, glyph)
        painter.end()
        return QIcon(pixmap)

    def _make_dot_icon(self, color_hex, size=14):
        """Renders a perfectly round, solid-color dot as a QIcon.

        Unlike drawing a "●"/"🔴" glyph with drawText (whose shape depends
        on the font and is never a true circle), this paints an actual
        QPainter ellipse inside a square pixmap with equal width/height and
        no pen outline, guaranteeing a perfectly round dot at any size.
        """
        pixmap = QPixmap(size, size)
        pixmap.fill(Qt.GlobalColor.transparent)
        from PyQt6.QtGui import QPainter
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(color_hex))
        # Inset by 1px on each side so anti-aliasing doesn't clip the edge.
        painter.drawEllipse(1, 1, size - 2, size - 2)
        painter.end()
        return QIcon(pixmap)

    def _style_details_table_field_value_headers(self):
        """Applies the white, left-aligned icon + left-aligned text treatment
        to the 'Field Name' / 'Value' column headers of self.details_table
        (the Module & Properties panel). Call this right after any
        setHorizontalHeaderLabels(["Field Name", "Value"]) so the header
        icons/alignment stay correct no matter which step type populated
        the table."""
        if self.details_table.columnCount() < 2:
            return
        field_name_hdr = self.details_table.horizontalHeaderItem(0)
        if field_name_hdr is not None and field_name_hdr.text() == "Field Name":
            field_name_hdr.setIcon(self._make_glyph_icon("🏷", "#ffffff"))
            field_name_hdr.setTextAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        value_hdr = self.details_table.horizontalHeaderItem(1)
        if value_hdr is not None and value_hdr.text() == "Value":
            value_hdr.setIcon(self._make_glyph_icon("✎", "#ffffff"))
            value_hdr.setTextAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)

    def _calculate_module_versions(self):
        """
        Calculates a version hash for each module based on its field structure.
        This helps detect when a module has been modified.
        """
        import hashlib
        import json
        
        versions = {}
        for module_name, module_data in self.modules.items():
            if not isinstance(module_data, dict):
                continue
            # Create a hash based on field names and positions
            labels = module_data.get('labels', [])
            field_signature = json.dumps([
                {
                    'name': label.get('name') or label.get('label') or label.get('text', ''),
                    'row': label.get('row'),
                    'col': label.get('column')
                }
                for label in labels
            ], sort_keys=True)
            
            version_hash = hashlib.md5(field_signature.encode()).hexdigest()[:8]
            versions[module_name] = version_hash
        
        return versions

    def _resolve_step_module(self, step_data):
        """
        Resolves the CURRENT module name + data that a step points to.
        Prefers module_sys_id (survives renames); falls back to the
        cached module_name for steps that predate the sys_id feature.
        Returns (current_name, module_data) or (None, None) if the module
        no longer exists at all.
        """
        sys_id = step_data.get('module_sys_id')
        if sys_id:
            name, module_data = self.main_window.get_module_by_sys_id(sys_id)
            if name:
                return name, module_data

        module_name = step_data.get('module_name')
        if module_name and module_name in self.modules:
            return module_name, self.modules[module_name]

        return None, None

    def _last_imported_module_before(self, step_index, inclusive=False):
        """
        Walks self.added_steps backwards from step_index looking for the
        most recent 'module_import' step, and returns the CURRENT name of
        the module it points to (sys_id-resolved, so renames are handled).

        If inclusive=True, step_index itself is checked first (used for
        utility steps, whose parent main step may itself be the import).
        If inclusive=False, the search starts at step_index - 1 (used for
        main steps, which shouldn't count themselves).

        Returns the module name, or None if no module has been imported
        yet at that point in the test case.
        """
        end = step_index if inclusive else step_index - 1
        for i in range(end, -1, -1):
            if i < 0 or i >= len(self.added_steps):
                continue
            s = self.added_steps[i]
            if s.get('type') == 'module_import':
                name, module_data = self._resolve_step_module(s)
                if name and isinstance(module_data, dict):
                    return name
        return None

    def _check_step_module_version(self, step_data):
        """
        Checks whether a step's module is out of sync with the module's
        current definition in the Modules Library, so the "Refresh" option
        can be shown or hidden accordingly.

        Match is sys_id-based (so a rename alone never triggers this), and
        the outdated/mismatch decision itself is based on the module's
        'version' and 'date' fields: if BOTH still match what was stamped
        on the step at import/refresh time (imported_version/imported_date),
        the module is considered current. If either differs, it's outdated.

        A step with no imported_version/imported_date at all (very old data,
        predating even the version/date chip feature) is treated as
        outdated, since there's nothing to compare against.

        Returns True if outdated (show Refresh), False if current.
        """
        if step_data.get('type') != 'module_import':
            return False

        current_name, module_data = self._resolve_step_module(step_data)
        if not current_name or not isinstance(module_data, dict):
            # Module was deleted entirely - nothing to refresh against.
            return False

        step_imported_version = step_data.get('imported_version')
        step_imported_date = step_data.get('imported_date')

        if not step_imported_version and not step_imported_date:
            return True

        current_version = module_data.get('version', '')
        current_date = module_data.get('date', '')

        return (step_imported_version or '') != (current_version or '') \
            or (step_imported_date or '') != (current_date or '')

    def _check_step_fields_mismatch(self, step_data):
        """
        Secondary, independent signal: detects when the module's FIELD
        STRUCTURE (label name/row/column) has actually drifted from what
        this step captured - regardless of whether 'version'/'date' were
        ever bumped to reflect it. Based on the structural hash from
        self.module_versions (see _calculate_module_versions), matched via
        sys_id so a rename alone doesn't trigger it.

        This exists as a safety net alongside _check_step_module_version:
        version/date mismatches rely on you remembering to bump them when
        you edit a module; this catches it even if you forget.

        Returns True if the field structure has changed.
        """
        if step_data.get('type') != 'module_import':
            return False

        current_name, module_data = self._resolve_step_module(step_data)
        if not current_name or not isinstance(module_data, dict):
            return False

        step_hash = step_data.get('module_version')
        current_hash = self.module_versions.get(current_name)

        if step_hash is None:
            return True

        return step_hash != current_hash

    def _add_module_warning_buttons(self, item_layout, step_data, on_refresh, button_size=24):
        """
        Shared button-builder used by every step-list row (main steps,
        utility steps in the details panel, utility steps in the standalone
        list) so the two warning types always look and behave identically.

        Adds up to two independent, distinctly-styled buttons:
          - Amber "🔄": version/date mismatch (_check_step_module_version)
          - Purple "🧩": field-structure mismatch (_check_step_fields_mismatch)
        A step can show either, both, or neither - they're independent
        signals. Both buttons trigger the SAME refresh action (on_refresh),
        since refreshing resolves either kind of drift.

        Returns (version_mismatch, fields_mismatch) so the caller can also
        adjust the step's name label (e.g. append a warning icon).
        """
        version_mismatch = self._check_step_module_version(step_data)
        fields_mismatch = self._check_step_fields_mismatch(step_data)

        if version_mismatch:
            version_button = QPushButton("🔄")
            version_button.setFixedSize(button_size, button_size)
            version_button.setStyleSheet(render_qss("""
                QPushButton {
                    background-color: #fbbf24;
                    color: white;
                    border: none;
                    border-radius: 4px;
                    font-size: 14px;
                    font-weight: bold;
                    padding: 0px;
                }
                QPushButton:hover {
                    background-color: $status_warning_light;
                }
                QPushButton:pressed {
                    background-color: $status_warning;
                }
            """, get_active_theme()))
            version_button.setToolTip("Version/date changed in the Modules Library — click to refresh")
            version_button.clicked.connect(lambda checked=False: on_refresh())
            item_layout.addWidget(version_button)

        if fields_mismatch:
            fields_button = QPushButton("🧩")
            fields_button.setFixedSize(button_size, button_size)
            fields_button.setStyleSheet("""
                QPushButton {
                    background-color: #a855f7;
                    color: white;
                    border: none;
                    border-radius: 4px;
                    font-size: 13px;
                    font-weight: bold;
                    padding: 0px;
                }
                QPushButton:hover {
                    background-color: #c084fc;
                }
                QPushButton:pressed {
                    background-color: #9333ea;
                }
            """)
            fields_button.setToolTip("Fields were added/removed/moved in the Modules Library — click to refresh")
            fields_button.clicked.connect(lambda checked=False: on_refresh())
            item_layout.addWidget(fields_button)

        return version_mismatch, fields_mismatch

    def _show_module_diff_dialog(self, module_name, old_fields, new_labels):
        """
        Shows a before/after comparison of module fields before refreshing.
        Returns True if user confirms, False if cancelled.
        """
        old_names = [f.get('field_name', '') for f in old_fields]
        new_names = [
            lbl.get('label') or lbl.get('text') or lbl.get('name', 'N/A')
            for lbl in new_labels
        ]

        added   = [n for n in new_names if n not in old_names]
        removed = [n for n in old_names if n not in new_names]
        kept    = [n for n in old_names if n in new_names]

        lines = [f"Module:  {module_name}\n"]

        if not added and not removed:
            lines.append("No fields were added or removed.")
            lines.append(f"Field order or positions may have changed ({len(kept)} field(s) preserved).")
        else:
            if added:
                lines.append(f"NEW fields ({len(added)}) — will be added with empty values:")
                for n in added:
                    lines.append(f"    + {n}")
                lines.append("")
            if removed:
                lines.append(f"REMOVED fields ({len(removed)}) — existing values will be lost:")
                for n in removed:
                    lines.append(f"    - {n}")
                lines.append("")
            if kept:
                lines.append(f"PRESERVED fields ({len(kept)}) — existing values kept:")
                for n in kept:
                    lines.append(f"    ✓ {n}")

        # --- Custom resizable dialog instead of QMessageBox ---
        dialog = QDialog(self)
        dialog.setWindowTitle("Review Module Changes Before Refreshing")
        dialog.setWindowFlags(dialog.windowFlags() & ~Qt.WindowType.WindowContextHelpButtonHint)
        dialog.setMinimumWidth(480)
        dialog.setMinimumHeight(200)
        dialog.resize(520, 300)

        outer_layout = QVBoxLayout(dialog)
        outer_layout.setSpacing(10)
        outer_layout.setContentsMargins(16, 16, 16, 12)

        # Header label
        header = QLabel(
            f"<b>Step uses an outdated version of '{module_name}'.</b><br>"
            "Review the changes below, then confirm to refresh."
        )
        header.setWordWrap(True)
        outer_layout.addWidget(header)

        # Resizable details text area — user can drag the bottom edge of the dialog
        # or resize the splitter to see more content
        details_edit = QTextEdit()
        details_edit.setReadOnly(True)
        details_edit.setPlainText("\n".join(lines))
        details_edit.setMinimumHeight(80)
        details_edit.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        details_edit.setStyleSheet("""
            QTextEdit {
                font-family: Consolas, 'Courier New', monospace;
                font-size: 12px;
                background-color: #f5f5f5;
                border: 1px solid #ccc;
                padding: 6px;
            }
        """)
        outer_layout.addWidget(details_edit, stretch=1)

        # Buttons
        button_box = QDialogButtonBox()
        refresh_btn         = button_box.addButton("Refresh",            QDialogButtonBox.ButtonRole.AcceptRole)
        refresh_all_btn     = button_box.addButton("Refresh All",        QDialogButtonBox.ButtonRole.ActionRole)
        refresh_all_mods_btn = button_box.addButton("Refresh All Modules", QDialogButtonBox.ButtonRole.ActionRole)
        cancel_btn          = button_box.addButton("Cancel",             QDialogButtonBox.ButtonRole.RejectRole)
        refresh_btn.setToolTip("Refresh only this single step.")
        refresh_all_btn.setToolTip(f"Refresh every step in this test case that uses the '{module_name}' module.")
        refresh_all_mods_btn.setToolTip("Refresh every outdated module_import step in this test case (across all modules).")
        refresh_btn.setDefault(False)
        cancel_btn.setDefault(True)
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)

        # Track which action was clicked
        dialog._refresh_all_clicked = False
        dialog._refresh_all_modules_clicked = False
        refresh_all_btn.clicked.connect(
            lambda: (setattr(dialog, '_refresh_all_clicked', True), dialog.accept())
        )
        refresh_all_mods_btn.clicked.connect(
            lambda: (setattr(dialog, '_refresh_all_modules_clicked', True), dialog.accept())
        )

        outer_layout.addWidget(button_box)

        # Match the theme-aware button style used elsewhere in the app
        # (golden background / black text on "DXC Theme 1", blue on
        # "DXC Theme 2") instead of the default OK-button look.
        dialog.setStyleSheet(get_button_qss().replace("QPushButton", "QDialogButtonBox QPushButton"))

        result = dialog.exec()
        if result == QDialog.DialogCode.Accepted and dialog._refresh_all_modules_clicked:
            return "refresh_all_modules"
        if result == QDialog.DialogCode.Accepted and dialog._refresh_all_clicked:
            return "refresh_all"
        elif result == QDialog.DialogCode.Accepted:
            return "refresh"
        else:
            return "cancel"

    def refresh_step_module(self, step_index, show_message=True, skip_dialog=False):
        """
        Refreshes a step's fields to match the current module definition.
        Preserves existing values for fields with matching names.
        
        Args:
            step_index: Index of the step to refresh
            show_message: Whether to show success message
            skip_dialog: If True, skip the confirmation dialog (used for bulk refresh)
        """
        if step_index < 0 or step_index >= len(self.added_steps):
            return
        
        step_data = self.added_steps[step_index]
        
        if step_data.get('type') != 'module_import':
            QMessageBox.warning(self, "Invalid Step", "This step is not a module import step.")
            return
        
        module_name, module_data = self._resolve_step_module(step_data)
        if not module_name or not isinstance(module_data, dict):
            fallback_name = step_data.get('module_name', '')
            QMessageBox.warning(self, "Module Not Found", f"Module '{fallback_name}' not found.")
            return
        
        # Get current module definition
        new_labels = module_data.get('labels', [])

        # Show diff dialog and let user confirm before proceeding
        old_fields = step_data.get('fields', [])
        if not skip_dialog:
            dialog_result = self._show_module_diff_dialog(module_name, old_fields, new_labels)
            if dialog_result == "refresh_all_modules":
                self.refresh_all_outdated_modules_in_test_case()
                return
            if dialog_result == "refresh_all":
                self.refresh_all_steps_with_module(module_name)
                return
            if dialog_result == "cancel":
                return

        # Build a map of existing field values by field name
        existing_values = {}
        existing_field_data = {}
        for field in step_data.get('fields', []):
            field_name = field.get('field_name')
            if field_name:
                existing_values[field_name] = field.get('value', '')
                existing_field_data[field_name] = field
        
        # Get action type from existing fields
        action_type = 'Input'
        if step_data.get('fields'):
            action_type = step_data['fields'][0].get('action_type', 'Input')
        
        # Create new fields list based on current module definition
        import time
        import random
        
        new_fields = []
        step_number = step_index + 1
        
        for idx, label_data in enumerate(new_labels):
            field_name = label_data.get('label') or label_data.get('text') or label_data.get('name', 'N/A')
            
            # Generate unique ID
            unique_timestamp = int(time.time() * 1000000)
            random_suffix = random.randint(100000, 999999)
            unique_field_id = f"{field_name}_{module_name}_M{step_number}_REFRESH_{unique_timestamp}_{random_suffix}_{idx}"
            
            # Preserve existing value if field name matches
            preserved_value = existing_values.get(field_name, '')
            old_field = existing_field_data.get(field_name)
            
            new_field = {
                "field_name": field_name,
                "internal_field_id": unique_field_id,
                "action_type": action_type,
                "value": preserved_value,
            }
            # ✅ FIX: A refresh only updates a step's field list to match the
            # current module definition (names/order/count) — it should not
            # discard per-field settings the user configured, like an IF
            # condition (field_cond) or "Clear before input". Carry those
            # over whenever the field name still matches after the refresh.
            if old_field:
                if old_field.get('field_cond'):
                    new_field['field_cond'] = old_field['field_cond']
                if old_field.get('clear_before_input'):
                    new_field['clear_before_input'] = old_field['clear_before_input']
            new_fields.append(new_field)
        
        # Update step data
        step_data['fields'] = new_fields
        step_data['module_name'] = module_name
        if module_data.get('sys_id'):
            step_data['module_sys_id'] = module_data['sys_id']
        step_data['module_version'] = self.module_versions.get(module_name)
        step_data['imported_version'] = module_data.get('version', '')
        step_data['imported_date'] = module_data.get('date', '')
        
        # Refresh UI
        self.update_steps_list()
        
        # Re-select the refreshed step
        if step_index < self.steps_list_widget.count():
            self.steps_list_widget.setCurrentRow(step_index)
        
        if show_message:
            preserved_count = sum(1 for v in existing_values.values() if v)
            new_count = len(new_fields)
            
            self.show_toast(f"Step {step_index + 1} refreshed to latest module definition.")

    def refresh_utility_step_module(self, main_step_index, utility_step_index, show_message=True, skip_dialog=False):
        """
        Refreshes a utility step's fields to match the current module definition.
        Similar to refresh_step_module but for utility steps.
        """
        if main_step_index < 0 or main_step_index >= len(self.added_steps):
            return
        
        main_step = self.added_steps[main_step_index]
        utility_steps = main_step.get('utility_steps', [])
        
        if utility_step_index < 0 or utility_step_index >= len(utility_steps):
            return
        
        utility_step = utility_steps[utility_step_index]
        
        if utility_step.get('type') != 'module_import':
            QMessageBox.warning(self, "Invalid Step", "This utility step is not a module import step.")
            return
        
        module_name, module_data = self._resolve_step_module(utility_step)
        if not module_name or not isinstance(module_data, dict):
            fallback_name = utility_step.get('module_name', '')
            QMessageBox.warning(self, "Module Not Found", f"Module '{fallback_name}' not found.")
            return
        
        # Get current module definition
        new_labels = module_data.get('labels', [])

        # Show diff dialog and let user confirm before proceeding
        old_fields = utility_step.get('fields', [])
        if not skip_dialog:
            dialog_result = self._show_module_diff_dialog(module_name, old_fields, new_labels)
            if dialog_result == "refresh_all_modules":
                self.refresh_all_outdated_modules_in_test_case()
                return
            if dialog_result == "refresh_all":
                self.refresh_all_steps_with_module(module_name)
                return
            if dialog_result == "cancel":
                return

        # Build a map of existing field values
        existing_values = {}
        existing_field_data = {}
        for field in utility_step.get('fields', []):
            field_name = field.get('field_name')
            if field_name:
                existing_values[field_name] = field.get('value', '')
                existing_field_data[field_name] = field
        
        # Get action type
        action_type = 'Input'
        if utility_step.get('fields'):
            action_type = utility_step['fields'][0].get('action_type', 'Input')
        
        # Create new fields
        import time
        import random
        
        new_fields = []
        step_number = main_step_index + 1
        utility_number = utility_step_index + 1
        
        for idx, label_data in enumerate(new_labels):
            field_name = label_data.get('label') or label_data.get('text') or label_data.get('name', 'N/A')
            
            unique_timestamp = int(time.time() * 1000000)
            random_suffix = random.randint(100000, 999999)
            unique_field_id = f"{field_name}_U{step_number}_{utility_number}_REFRESH_{unique_timestamp}_{random_suffix}_{idx}"
            
            preserved_value = existing_values.get(field_name, '')
            old_field = existing_field_data.get(field_name)
            
            new_field = {
                "field_name": field_name,
                "internal_field_id": unique_field_id,
                "action_type": action_type,
                "value": preserved_value,
            }
            # ✅ FIX: preserve per-field IF condition / clear-before-input
            # settings across a refresh, same as for main steps above.
            if old_field:
                if old_field.get('field_cond'):
                    new_field['field_cond'] = old_field['field_cond']
                if old_field.get('clear_before_input'):
                    new_field['clear_before_input'] = old_field['clear_before_input']
            new_fields.append(new_field)
        
        # Update utility step
        utility_step['fields'] = new_fields
        utility_step['module_name'] = module_name
        if module_data.get('sys_id'):
            utility_step['module_sys_id'] = module_data['sys_id']
        utility_step['module_version'] = self.module_versions.get(module_name)
        utility_step['imported_version'] = module_data.get('version', '')
        utility_step['imported_date'] = module_data.get('date', '')
        
        # Refresh utility steps list
        # Refresh utility steps list while preserving selection
        self.refresh_utility_steps_for_main_step(main_step_index)

        # Re-select the refreshed utility step to trigger display update
        if utility_step_index < self.utility_steps_list_widget.count():
            self.utility_steps_list_widget.setCurrentRow(utility_step_index)

        if show_message:
            preserved_count = sum(1 for v in existing_values.values() if v)
            self.show_toast(f"Utility step {step_number}.{utility_number} refreshed.")

    def refresh_all_steps_with_module(self, module_name):
        """
        Refreshes all main steps and utility steps that use a specific module.
        Matches by the module's sys_id (resolved from module_name here),
        so it still finds every step even if some of them carry a stale
        cached module_name from before a rename.
        """
        if not module_name or module_name not in self.modules:
            return

        target_sys_id = self.modules[module_name].get('sys_id')

        def _points_at_target(step):
            if step.get('type') != 'module_import':
                return False
            current_name, module_data = self._resolve_step_module(step)
            if target_sys_id and isinstance(module_data, dict):
                return module_data.get('sys_id') == target_sys_id
            return current_name == module_name

        refreshed_count = 0

        # Refresh main steps
        for step_index, step_data in enumerate(self.added_steps):
            if _points_at_target(step_data):
                self.refresh_step_module(step_index, show_message=False, skip_dialog=True)
                refreshed_count += 1

            # Refresh utility steps
            for utility_idx, utility_step in enumerate(step_data.get('utility_steps', [])):
                if _points_at_target(utility_step):
                    self.refresh_utility_step_module(step_index, utility_idx, show_message=False, skip_dialog=True)
                    refreshed_count += 1

        if refreshed_count > 0:
            QMessageBox.information(
                self,
                "Bulk Refresh Complete",
                f"Refreshed {refreshed_count} step(s) using module '{module_name}'."
            )
        else:
            QMessageBox.information(
                self,
                "No Steps Found",
                f"No steps found using module '{module_name}'."
            )

    def refresh_all_outdated_modules_in_test_case(self):
        """
        Walks every main step and utility step in the current test case,
        refreshing each module_import step that shows EITHER warning type -
        a version/date mismatch or a field-structure mismatch - against the
        current module definition. Covers all modules at once, not just the
        one whose diff dialog is open.
        """
        refreshed_count = 0
        modules_touched = set()

        # Iterate by index (main steps) and by sub-index (utility steps).
        # NOTE: refreshing a step does not change the indices of either list,
        # so it is safe to iterate while refreshing.
        for step_index, step_data in enumerate(self.added_steps):
            # Main step
            if step_data.get('type') == 'module_import':
                if self._check_step_module_version(step_data) or self._check_step_fields_mismatch(step_data):
                    current_name, _ = self._resolve_step_module(step_data)
                    self.refresh_step_module(step_index, show_message=False, skip_dialog=True)
                    refreshed_count += 1
                    modules_touched.add(current_name or step_data.get('module_name', ''))

            # Utility steps under this main step
            for utility_idx, utility_step in enumerate(step_data.get('utility_steps', [])):
                if utility_step.get('type') == 'module_import':
                    if self._check_step_module_version(utility_step) or self._check_step_fields_mismatch(utility_step):
                        current_name, _ = self._resolve_step_module(utility_step)
                        self.refresh_utility_step_module(
                            step_index, utility_idx,
                            show_message=False, skip_dialog=True
                        )
                        refreshed_count += 1
                        modules_touched.add(current_name or utility_step.get('module_name', ''))

        if refreshed_count > 0:
            module_list = ", ".join(sorted(modules_touched)) if modules_touched else ""
            QMessageBox.information(
                self,
                "All Modules Refreshed",
                f"Refreshed {refreshed_count} step(s) across {len(modules_touched)} module(s) "
                f"in this test case.\n\nModules updated: {module_list}"
            )
        else:
            QMessageBox.information(
                self,
                "Nothing to Refresh",
                "No outdated module_import steps were found in this test case."
            )

         
    def clear_current_fields(self):
        """
        Clears all field values in the currently displayed table.
        Works for both main steps and utility steps.
        """
        # Check if there's anything to clear
        if self.details_table.rowCount() == 0:
            themed_warning(self, "Nothing to Clear", "No fields are currently displayed.", QMessageBox.Icon.Information)
            return
        
        # Confirm with user
        reply = QMessageBox.question(
            self,
            "Clear Fields",
            "Are you sure you want to clear all field values and IF conditions?\n\nThis will not save automatically - you need to click 'Save Step Fields' to save the changes.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        
        if reply != QMessageBox.StandardButton.Yes:
            return
        
        # Clear all editable fields in the table
        cleared_count = 0
        
        for row in range(self.details_table.rowCount()):
            # Check column 1 for value widgets (QLineEdit, QTextEdit, or ConditionableFieldWidget)
            value_widget = self.details_table.cellWidget(row, 1)
            
            if value_widget:
                if isinstance(value_widget, ConditionableFieldWidget):
                    value_widget.set_value('')
                    value_widget.set_condition(None)
                    cleared_count += 1
                elif isinstance(value_widget, QLineEdit):
                    value_widget.clear()
                    cleared_count += 1
                elif isinstance(value_widget, QTextEdit):
                    value_widget.clear()
                    cleared_count += 1
            
            # Check column 2 for highlight checkboxes (for screenshot steps)
            checkbox_widget = self.details_table.cellWidget(row, 2)
            if checkbox_widget:
                checkbox = checkbox_widget.findChild(QCheckBox)
                if checkbox:
                    checkbox.setChecked(False)
                    cleared_count += 1
        
        if cleared_count > 0:
            self.statusBar().showMessage(
                f"Cleared {cleared_count} field(s). Click 'Save Step Fields' to save changes.",
                5000
            )
        else:
            QMessageBox.information(self, "Nothing Cleared", "No editable fields found to clear.")         
         
    def on_main_step_force_refresh(self, item):
        """
        Forces refresh of main step details when clicked, even if already selected.
        This handles the case where user clicks on main step after viewing its utility step.
        """
        if not item:
            return
        
        # Check if we were previously editing a utility step
        was_editing_utility = hasattr(self, 'current_utility_step') and self.current_utility_step is not None
        
        if was_editing_utility:
            # Clear the utility step reference
            self.current_utility_step = None
            
            # Clear utility list selection to avoid confusion
            self.utility_steps_list_widget.clearSelection()
            
            # Force refresh by calling display_module_details
            # Pass the same item as both current and previous to force full refresh
            self.display_module_details(item, item)
            
            # Show notification
            QMessageBox.information(
                self,
                "Main Step Selected",
                "Now showing main step fields."
            )
         
    def _show_header_json_menu(self, position, widget):
        """
        Single-item context menu ("Show JSON") shown when right-clicking
        anywhere in the header area - the Test Case Name field, the
        Description field, the Prerequisites row, or the header
        background itself.
        """
        menu = QMenu(self)
        show_json_action = QAction("🧾 Show JSON", self)
        show_json_action.triggered.connect(self._show_current_test_case_json)
        menu.addAction(show_json_action)
        menu.exec(widget.mapToGlobal(position))

    def _show_current_test_case_json(self):
        """
        Shows this test case's JSON exactly as it stands right now in the
        editor - including any unsaved changes - i.e. what would be
        written to disk if Save were clicked next. Mirrors the same
        assembly logic as save_test_case().
        """
        current_name = self.test_case_name_input.text().strip() or self.original_test_case_name

        test_case_data = {
            'name': current_name,
            'description': self.test_case_description_input.text().strip(),
            'assumptions': self.test_case_assumptions_input.toHtml(),
            'prerequisites': self.get_prerequisites(),
            'steps': self.added_steps,
            'additional_info_fields': self.additional_info_fields,
            'additional_info_values': self.additional_info_values,
            'folder': self.main_window.test_cases.get(self.original_test_case_name, {}).get('folder', ''),
        }

        try:
            json_text = json.dumps(test_case_data, indent=4, ensure_ascii=False)
        except TypeError:
            json_text = json.dumps(test_case_data, indent=4, ensure_ascii=False, default=str)

        display_name = current_name or "Untitled Test Case"
        self.main_window._show_json_dialog(
            f"Test Case (unsaved edits included): {display_name}", json_text
        )

    def save_test_case(self):
        """
        Saves the test case without closing the dialog.
        Updates the test case structure and metadata, but NOT individual field values.
        ✅ FIXED: Only saves test case structure, not field values from Module Details table.
        """
        # Get the current test case name (might have been changed)
        new_test_case_name = self.test_case_name_input.text().strip()
        
        if not new_test_case_name:
            themed_warning(self, "Missing Name", "Please enter a test case name.")
            return
        
        # Check if the name was changed and if the new name already exists
        if new_test_case_name != self.original_test_case_name:
            if new_test_case_name in self.main_window.test_cases:
                QMessageBox.warning(
                    self, 
                    "Duplicate Name", 
                    f"A test case named '{new_test_case_name}' already exists.\n"
                    "Please choose a different name or keep the original name."
                )
                return
        
        # ✅ NO AUTO-SAVE OF STEP FIELDS - just save the structure as-is
        
        # Build the complete test case data
        test_case_data = {
            'name': new_test_case_name,
            'description': self.test_case_description_input.text().strip(),
            'assumptions': self.test_case_assumptions_input.toHtml(),
            'prerequisites': self.get_prerequisites(),
            'steps': self.added_steps,
            'additional_info_fields': self.additional_info_fields,    # ✅ ADD THIS
            'additional_info_values': self.additional_info_values,     # ✅ ADD THIS
            'folder': self.main_window.test_cases.get(self.original_test_case_name, {}).get('folder', ''),  # ← ADD THIS
        }
        
        # If name changed, remove old entry
        if new_test_case_name != self.original_test_case_name:
            if self.original_test_case_name in self.main_window.test_cases:
                del self.main_window.test_cases[self.original_test_case_name]
        
        # Update or add the test case
        self.main_window.test_cases[new_test_case_name] = test_case_data
        
        # Save to file
        self.main_window.save_test_cases_to_file()
        self._dirty = False
        
        # Update the original name for future saves
        self.original_test_case_name = new_test_case_name
        
        # Update the window title
        self.setWindowTitle(f"Edit Test Case: {new_test_case_name}")
        
        # Update step combo options after save
        self.update_step_combo_options()
        
        # Show success message
        self.show_toast(f"Test case '{new_test_case_name}' saved.")
        
        # Refresh the main window's test case list if it exists
        if hasattr(self.main_window, 'populate_test_cases_list'):
            self.main_window.populate_test_cases_list()

    def closeEvent(self, event):
        """If the user closes the dialog without saving, mark main window as having unsaved changes."""
        if self._dirty:
            self.main_window.mark_unsaved_changes()
        event.accept()

    def open_additional_info_dialog(self):
        """Opens dialog to configure and enter additional info for this test case."""
        
        # ✅ NEW: If no fields configured yet, offer to load defaults
        if not self.additional_info_fields and hasattr(self.main_window, 'load_default_additional_info_fields'):
            default_fields = self.main_window.load_default_additional_info_fields()
            if default_fields:
                reply = QMessageBox.question(
                    self,
                    "Load Default Fields",
                    f"No additional fields configured for this test case.\n\n"
                    f"Load default template ({len(default_fields)} field(s))?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                )
                
                if reply == QMessageBox.StandardButton.Yes:
                    self.additional_info_fields = copy.deepcopy(default_fields)
        
        # First, let user configure fields if needed
        config_dialog = AdditionalInfoConfigDialog(self, self.additional_info_fields)
        
        if config_dialog.exec() == QDialog.DialogCode.Accepted:
            self.additional_info_fields = config_dialog.get_fields()
            
            # Now let user enter values for these fields
            if self.additional_info_fields:
                values_dialog = AdditionalInfoValuesDialog(
                    self, 
                    self.additional_info_fields, 
                    self.additional_info_values
                )
                
                if values_dialog.exec() == QDialog.DialogCode.Accepted:
                    self.additional_info_values = values_dialog.get_values()
                    self.show_toast("Additional information saved.")
            else:
                themed_warning(
                    self,
                    "No Fields Configured",
                    "No additional fields have been configured yet.\n\n"
                    "You can add fields like:\n"
                    "• Radio buttons (e.g., Environment Type: Online/Batch)\n"
                    "• Text fields (e.g., Test Environment)\n\n"
                    "Click 'Additional Info' again to configure fields.",
                    QMessageBox.Icon.Information
                )

    def accept(self):
        """
        Override accept to save test case before closing.
        Does the same job as 'Save' button + closes the window.
        ✅ Does NOT auto-save field values from Module Details table.
        """
        # Get the current test case name
        new_test_case_name = self.test_case_name_input.text().strip()
        
        if not new_test_case_name:
            themed_warning(self, "Missing Name", "Please enter a test case name before closing.")
            return
        
        # Check if the name was changed and if the new name already exists
        if new_test_case_name != self.original_test_case_name:
            # Check if new name conflicts with an existing test case (other than the current one being edited)
            if new_test_case_name in self.main_window.test_cases:
                QMessageBox.warning(
                    self, 
                    "Duplicate Name", 
                    f"A test case named '{new_test_case_name}' already exists.\n"
                    "Please choose a different name or keep the original name."
                )
                return
        
        # ✅ NO AUTO-SAVE OF STEP FIELDS - just save the structure
        
        # Build the complete test case data (same as save_test_case)
        test_case_data = {
            'name': new_test_case_name,
            'description': self.test_case_description_input.text().strip(),
            'assumptions': self.test_case_assumptions_input.toHtml(),
            'prerequisites': self.get_prerequisites(),
            'steps': self.added_steps,
            'additional_info_fields': self.additional_info_fields,
            'additional_info_values': self.additional_info_values,
            'folder': self.main_window.test_cases.get(self.original_test_case_name, {}).get('folder', ''),  # ← ADD THIS
        }
        
        # If name changed, remove old entry
        if new_test_case_name != self.original_test_case_name:
            if self.original_test_case_name in self.main_window.test_cases:
                del self.main_window.test_cases[self.original_test_case_name]

        # Update or add the test case
        self.main_window.test_cases[new_test_case_name] = test_case_data

        # Save to file
        self.main_window.save_test_cases_to_file()

        # Now close the dialog
        super().accept()

    def reject(self):
        """
        Override reject (Escape key or window X button) to also save,
        since added_steps may have been modified in memory during this session.
        """
        new_test_case_name = self.test_case_name_input.text().strip()
        if new_test_case_name:
            test_case_data = {
                'name': new_test_case_name,
                'description': self.test_case_description_input.text().strip(),
                'assumptions': self.test_case_assumptions_input.toHtml(),
                'prerequisites': self.get_prerequisites(),
                'steps': self.added_steps,
                'additional_info_fields': self.additional_info_fields,
                'additional_info_values': self.additional_info_values,
                'folder': self.main_window.test_cases.get(self.original_test_case_name, {}).get('folder', ''),  # ← ADD THIS
            }
            if new_test_case_name != self.original_test_case_name:
                if self.original_test_case_name in self.main_window.test_cases:
                    del self.main_window.test_cases[self.original_test_case_name]
            self.main_window.test_cases[new_test_case_name] = test_case_data
            self.main_window.save_test_cases_to_file()
        super().reject()

    def evaluate_conditional_value(self, value, test_case_name):
        """
        Evaluates conditional values like '123 if {found_row} == 4'.
        Returns (should_send, actual_value).
        """
        import re
        substituted = self.substitute_execution_variables(value, test_case_name)
        match = re.match(r'^(.+?)\s+if\s+(.+)$', substituted.strip())
        if match:
            actual_value = match.group(1).strip()
            condition = match.group(2).strip()
            try:
                should_send = bool(eval(condition))
            except Exception as e:
                print(f"Condition eval error: {condition} -> {e}")
                should_send = False
            return should_send, actual_value
        return True, substituted

    def evaluate_field_condition(self, field, test_case_name):
        """
        Evaluates field condition. Returns True (process field) or False (skip field).
        Handles both new structured field_cond and legacy inline 'CHG if {found_row} == 10'.
        """
        import re as _re
        value = str(field.get('value', '')).strip()
        field_cond = field.get('field_cond')

        # ── New structured condition ──────────────────────────────────────────
        if field_cond:
            cond_var = field_cond.get('variable', '{found_row}')
            cond_op  = field_cond.get('operator', '==')
            cond_val = str(field_cond.get('value', '')).strip()
            var_key  = cond_var.strip('{}')
            variables = {
                'found_row':    str(getattr(self, '_found_row', '')),
                'found_col':    str(getattr(self, '_found_col', '')),
                'found_length': str(getattr(self, '_found_length', '')),
            }
            variables.update(getattr(self, '_copy_text_variables', {}))
            live_value = variables.get(var_key, '').strip()
            try:
                l, r = float(live_value), float(cond_val)
                result = {'==': l==r, '!=': l!=r, '>': l>r, '<': l<r, '>=': l>=r, '<=': l<=r}.get(cond_op, False)
                print(f"[FIELD COND] field={field.get('field_name')} var={var_key} live={live_value} op={cond_op} cond={cond_val} result={result}")
                return result
            except ValueError:
                result = {'==': live_value==cond_val, '!=': live_value!=cond_val}.get(cond_op, False)
                print(f"[FIELD COND str] field={field.get('field_name')} var={var_key} live={live_value} op={cond_op} cond={cond_val} result={result}")
                return result

        # ── Legacy inline syntax: "CHG if {found_row} == 10" ─────────────────
        substituted = self.substitute_execution_variables(value, test_case_name)
        m = _re.match(r'^(.+?)\s+if\s+(.+)$', substituted.strip())
        if m:
            try:
                return bool(eval(m.group(2).strip()))
            except Exception as e:
                print(f"Legacy condition eval error: {m.group(2)} -> {e}")
                return False

        # ── No condition → always process ────────────────────────────────────
        return True

    def substitute_execution_variables(self, text, test_case_name):
        """
        Substitutes variables during preview execution.
        Uses current form values for test description.
        """
        from datetime import datetime
        
        if not text:
            return text
        
        now = datetime.now()
        
        variables = {
            'date': now.strftime('%Y.%m.%d'),
            'time': now.strftime('%H:%M:%S'),
            'datetime': now.strftime('%Y-%m-%d %H:%M:%S'),
            'test_case_id': test_case_name,
            'test_description': self.test_case_description_input.text(),
            'space': ' ',
            'found_row': str(getattr(self, '_found_row', '')),
            'found_col': str(getattr(self, '_found_col', '')),
            'found_length': str(getattr(self, '_found_length', '')),
        }
        
        copy_text_vars = getattr(self, '_copy_text_variables', {})
        variables.update(copy_text_vars)        
        
        result = text
        for var_name, var_value in variables.items():
            placeholder = '{' + var_name + '}'
            result = result.replace(placeholder, var_value)
        stripped = result.strip()
        if stripped in copy_text_vars:
            result = copy_text_vars[stripped]        
        return result

    # Matches an optional comparison operator (>=, <=, ==, !=, >, <) followed
    # by a numeric value, e.g. '>400', '>=  12.5', '!=0', '==100'.
    # Group 1 = operator, Group 2 = number.
    _COMPARISON_RE = re.compile(r'^\s*(>=|<=|==|!=|>|<)\s*(-?\d+(?:[.,]\d+)?)\s*$')

    def validate_field_value(self, actual_value, expected_value):
        """
        Validates a field value, with special handling for {blank} validation
        and for numeric comparison-operator validation (e.g. '>400', '<=10').
        """
        actual_stripped = actual_value.strip()
        expected_stripped = expected_value.strip()
        
        if expected_stripped.lower() == '{blank}':
            return actual_stripped == '' or actual_stripped.isspace() or len(actual_stripped) == 0
        
        if expected_stripped.lower() == '<> {blank}':
            return not (actual_stripped == '' or actual_stripped.isspace() or len(actual_stripped) == 0)

        # Comparison-operator validation, e.g. '>400', '>=400', '<400',
        # '<=400', '==400', '!=400'
        comparison_match = self._COMPARISON_RE.match(expected_stripped)
        if comparison_match:
            operator, number_str = comparison_match.groups()
            try:
                # Support ',' as a decimal separator in the actual value too
                # (e.g. '400,75'), by normalizing it to '.' before parsing.
                actual_number = float(actual_stripped.replace(',', '.'))
            except ValueError:
                # Actual value isn't numeric, so it can't satisfy a numeric
                # comparison
                return False

            # Support ',' as a decimal separator in the expected value
            # (e.g. '>400,5' means '>400.5')
            expected_number = float(number_str.replace(',', '.'))

            if operator == '>':
                return actual_number > expected_number
            elif operator == '<':
                return actual_number < expected_number
            elif operator == '>=':
                return actual_number >= expected_number
            elif operator == '<=':
                return actual_number <= expected_number
            elif operator == '==':
                return actual_number == expected_number
            elif operator == '!=':
                return actual_number != expected_number

        return actual_stripped == expected_stripped

    def _on_utility_step_selection_changed(self, current, previous):
        """Update HoverItemWidget selected state for utility steps."""
        if previous is not None:
            w = self.utility_steps_list_widget.itemWidget(previous)
            if isinstance(w, HoverItemWidget):
                w.set_selected(False)
        if current is not None:
            w = self.utility_steps_list_widget.itemWidget(current)
            if isinstance(w, HoverItemWidget):
                w.set_selected(True)

    def _on_main_step_selection_changed(self, current, previous):
        """Update HoverItemWidget selected state to suppress alternate blue on selected row."""
        # Deselect previous
        if previous is not None:
            w = self.steps_list_widget.itemWidget(previous)
            if isinstance(w, HoverItemWidget):
                w.set_selected(False)
        # Select current
        if current is not None:
            w = self.steps_list_widget.itemWidget(current)
            if isinstance(w, HoverItemWidget):
                w.set_selected(True)

    def on_main_step_clicked(self, item):
        """When a main step is clicked, populate utility steps list with numbered sub-steps."""
        if not item:
            self._show_utility_placeholder()
            # Hide quick utility buttons
            self.utility_input_button.hide()
            self.utility_validate_button.hide()
            self.utility_enter_icon.hide()  # ✅ NEW
            self.utility_clear_icon.hide()  # ✅ NEW
            self.utility_pf3_icon.hide()
            return
        
        current_step_index = self.steps_list_widget.row(item)
        if current_step_index < 0 or current_step_index >= len(self.added_steps):
            self._show_utility_placeholder()
            self.utility_input_button.hide()
            self.utility_validate_button.hide()
            self.utility_enter_icon.hide()  # ✅ NEW
            self.utility_clear_icon.hide()  # ✅ NEW
            self.utility_pf3_icon.hide()
            return
        
        step_data = self.added_steps[current_step_index]
        
        # Show Input/Validate only for module_import; Enter/Clear/Screenshot for all step types
        if step_data.get('type') == 'module_import':
            self.utility_input_button.show()
            self.utility_validate_button.show()
        else:
            self.utility_input_button.hide()
            self.utility_validate_button.hide()
        self.utility_enter_icon.show()
        self.utility_clear_icon.show()
        self.utility_pf3_icon.show()
        self.utility_screenshot_icon.show()
        
        utility_steps = step_data.get('utility_steps', [])
        
        # Populate utility steps list with sub-step numbering
        self.utility_steps_list_widget.clear()
        if not utility_steps:
            self._show_utility_placeholder()
            return  # nothing more to render
        main_step_num = current_step_index + 1
        
        needs_save = False
        for sub_idx, utility_step in enumerate(utility_steps, 1):
            step_name = utility_step.get('name', 'Utility')
            # Migrate old step names to current naming conventions
            new_name = step_name
            if step_name.startswith("Import Module:"):
                new_name = step_name.replace("Import Module:", "Use Screen Module:", 1)
            elif step_name.startswith("Special Key:"):
                new_name = step_name.replace("Special Key:", "Send Keystroke:", 1)
            elif step_name.startswith("Find Text:"):
                new_name = step_name.replace("Find Text:", "Screen Text Lookup:", 1)
            elif step_name.startswith("Copy Text:"):
                new_name = step_name.replace("Copy Text:", "Extract Text at Position:", 1)
            elif step_name in ("Capture Screen", "Capture Screenshot"):
                new_name = "Capture Screenshot (DOCX)"
            # If name changed, update the actual data so it persists
            if new_name != step_name:
                utility_step['name'] = new_name
                needs_save = True
            step_name = new_name
            
            # Add sub-step number prefix (e.g., "Step 1.1: ...")
            numbered_name = f"Step {main_step_num}.{sub_idx}: {step_name}"

            # ✅ Check disabled state for this utility step
            is_util_disabled = utility_step.get('disabled', False)
            if is_util_disabled:
                numbered_name += "  [Disabled]"

            # ✅ Check if this is a validate utility step AND if module has drifted
            is_validate_utility = False
            is_outdated = False
            
            if utility_step.get('type') == 'module_import':
                fields = utility_step.get('fields', [])
                if fields and fields[0].get('action_type') == 'Validate':
                    is_validate_utility = True
                
                # Check version/date mismatch and field-structure mismatch independently
                if self._check_step_module_version(utility_step):
                    numbered_name += " ⚠️"
                    is_outdated = True
                if self._check_step_fields_mismatch(utility_step):
                    numbered_name += " 🧩"
                    is_outdated = True

            # ✅ Parent/child hierarchy: skip rendering child steps whose
            # parent group is currently collapsed.
            if self._utility_parent_collapsed(utility_steps, sub_idx - 1):
                continue

            # Create custom widget with delete button
            list_item = QListWidgetItem()
            item_widget = HoverItemWidget()
            item_layout = QHBoxLayout(item_widget)
            item_layout.setContentsMargins(4, 2, 4, 2)
            item_layout.setSpacing(5)

            # Expand/collapse chevron (parent rows) or blank spacer (leaf
            # rows), plus extra indent for child rows — shifts every step
            # slightly right, the same way Test Case Library folders do.
            self._add_utility_hierarchy_widgets(item_layout, utility_steps, sub_idx - 1, current_step_index)

            # Step name label
            name_label = QLabel(numbered_name)
            name_label.setMinimumWidth(200)
            name_label.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
            name_label.setWordWrap(False)
            if is_util_disabled:
                name_label.setStyleSheet(render_qss("color: $disabled_text; font-style: italic;", get_active_theme()))
            item_layout.addWidget(name_label, 1)

            # ✅ FIX: Show pass/fail badge for utility steps
            utility_key = (current_step_index, sub_idx - 1)
            utility_result = getattr(self, '_utility_step_results', {}).get(utility_key)
            if utility_result == 'passed':
                badge = QLabel("✓")
                badge.setObjectName("utility_step_badge")
                badge.setStyleSheet(render_qss("color: white; background-color: $status_success; border-radius: 9px; padding: 0px 5px; font-weight: bold; font-size: 10pt;", get_active_theme()))
                badge.setFixedSize(22, 22)
                badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
                badge.setToolTip("Passed")
                item_layout.addWidget(badge)
            elif utility_result == 'failed':
                badge = QLabel("✗")
                badge.setObjectName("utility_step_badge")
                badge.setStyleSheet("color: white; background-color: #ef4444; border-radius: 9px; padding: 0px 5px; font-weight: bold; font-size: 10pt;")
                badge.setFixedSize(22, 22)
                badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
                badge.setToolTip("Failed")
                item_layout.addWidget(badge)
            
            item_layout.addStretch()

            # Version/date mismatch (amber) and field-structure mismatch (purple) buttons
            if is_outdated:
                self._add_module_warning_buttons(
                    item_layout, utility_step,
                    on_refresh=lambda ms=current_step_index, us=sub_idx-1: self.refresh_utility_step_module(ms, us)
                )

            # Delete button
            delete_button = QPushButton()

            # Load the bin.png icon
            bin_icon = QIcon(resource_path("bin.png"))
            delete_button.setIcon(bin_icon)
            delete_button.setIconSize(QSize(14, 14))  # Icon size slightly smaller than button

            delete_button.setFixedSize(18, 18)

            delete_button.setCursor(Qt.CursorShape.PointingHandCursor)
            delete_button.setToolTip(f"Delete utility step {main_step_num}.{sub_idx}")
            delete_button.clicked.connect(
                lambda checked, ms=current_step_index, us=sub_idx-1: self.delete_utility_step(ms, us)
            )
            item_layout.addWidget(delete_button)
            
            # ✅ NEW: Apply yellow background for validate utility steps
            if is_validate_utility:
                item_widget.set_validate(True)

            # ✅ Grey out entire row when disabled
            if is_util_disabled:
                item_widget.set_disabled_style(True)

            list_item.setData(Qt.ItemDataRole.UserRole, {
                'main_step_index': current_step_index,
                'utility_step': utility_step,
                'sub_index': sub_idx
            })
            
            item_widget.set_alternate((sub_idx - 1) % 2 == 1)
            self.utility_steps_list_widget.addItem(list_item)
            self.utility_steps_list_widget.setItemWidget(list_item, item_widget)
            size_hint = list_item.sizeHint()
            size_hint.setHeight(max(32, size_hint.height()))
            list_item.setSizeHint(size_hint)

        # Persist any migrated step names back to the test case data
        if needs_save:
            self.main_window.save_test_cases_to_file()

    # ── Utility step parent/child hierarchy helpers ─────────────────────
    # A utility step becomes a "child" of the nearest preceding step that is
    # itself NOT a child (found via "Make Child" from the right-click menu).
    # This gives a single level of nesting: parent steps can be expanded /
    # collapsed (like Test Case Library folders), and their child steps are
    # indented and hidden/shown together.
    def _utility_find_parent_index(self, utility_steps, idx):
        """Returns the index of idx's parent (nearest preceding non-child
        step), or None if idx is not a child or has no parent."""
        if idx < 0 or idx >= len(utility_steps):
            return None
        if not utility_steps[idx].get('is_child', False):
            return None
        p = idx - 1
        while p >= 0 and utility_steps[p].get('is_child', False):
            p -= 1
        return p if p >= 0 else None

    def _utility_step_has_children(self, utility_steps, idx):
        """Returns True if the (non-child) step at idx is immediately
        followed by one or more child steps."""
        if idx < 0 or idx >= len(utility_steps):
            return False
        if utility_steps[idx].get('is_child', False):
            return False
        return (idx + 1) < len(utility_steps) and utility_steps[idx + 1].get('is_child', False)

    def _utility_parent_collapsed(self, utility_steps, idx):
        """Returns True if idx is a child step whose parent group is
        currently collapsed (i.e. this row should not be rendered)."""
        parent_idx = self._utility_find_parent_index(utility_steps, idx)
        if parent_idx is None:
            return False
        return not utility_steps[parent_idx].get('children_expanded', True)

    def _toggle_utility_step_expand(self, main_row, utility_row):
        """Expands/collapses the child steps under a parent utility step."""
        if main_row < 0 or main_row >= len(self.added_steps):
            return
        utility_steps = self.added_steps[main_row].get('utility_steps', [])
        if utility_row < 0 or utility_row >= len(utility_steps):
            return
        ustep = utility_steps[utility_row]
        ustep['children_expanded'] = not ustep.get('children_expanded', True)
        self.refresh_utility_steps_for_main_step(main_row)
        self.main_window.save_test_cases_to_file()

    def _make_utility_step_child(self, main_row, utility_row):
        """Makes the utility step at utility_row a child of its nearest
        preceding non-child (parent) step, ignoring any child steps above it."""
        if main_row < 0 or main_row >= len(self.added_steps):
            return
        utility_steps = self.added_steps[main_row].get('utility_steps', [])
        if utility_row <= 0 or utility_row >= len(utility_steps):
            return  # the first utility step can never become a child
        utility_steps[utility_row]['is_child'] = True
        # A child step can't itself hold an expand/collapse state.
        utility_steps[utility_row].pop('children_expanded', None)
        parent_idx = self._utility_find_parent_index(utility_steps, utility_row)
        self.refresh_utility_steps_for_main_step(main_row)
        self.main_window.save_test_cases_to_file()
        parent_label = f"{main_row + 1}.{parent_idx + 1}" if parent_idx is not None else f"{main_row + 1}"
        self.statusBar().showMessage(
            f"Step {main_row + 1}.{utility_row + 1} is now a child of Step {parent_label}.", 3000
        )

    def _make_utility_step_top_level(self, main_row, utility_row):
        """Removes the child flag from a utility step, restoring it to the
        top level."""
        if main_row < 0 or main_row >= len(self.added_steps):
            return
        utility_steps = self.added_steps[main_row].get('utility_steps', [])
        if utility_row < 0 or utility_row >= len(utility_steps):
            return
        utility_steps[utility_row]['is_child'] = False
        self.refresh_utility_steps_for_main_step(main_row)
        self.main_window.save_test_cases_to_file()
        self.statusBar().showMessage(
            f"Step {main_row + 1}.{utility_row + 1} is no longer a child step.", 3000
        )

    def _add_utility_hierarchy_widgets(self, item_layout, utility_steps, idx, main_row):
        """Adds the leading expand/collapse chevron (for parent steps) or a
        blank spacer of the same width (for leaf steps), plus an extra
        indent spacer for child steps. This shifts every utility step's
        content slightly right, reserving space for the chevron column,
        exactly like the Test Case Library folder rows."""
        CHEVRON_W = 20
        CHILD_INDENT_W = 18

        is_child = utility_steps[idx].get('is_child', False)

        if is_child:
            child_spacer = QFrame()
            child_spacer.setFixedWidth(CHILD_INDENT_W)
            child_spacer.setStyleSheet("border: none; background: transparent;")
            item_layout.addWidget(child_spacer)

        if self._utility_step_has_children(utility_steps, idx):
            is_expanded = utility_steps[idx].get('children_expanded', True)
            chevron_btn = QPushButton()
            chevron_btn.setFixedSize(CHEVRON_W, 20)
            chevron_btn.setText("▾" if is_expanded else "▸")
            chevron_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            chevron_btn.setToolTip("Collapse child steps" if is_expanded else "Expand child steps")
            chevron_btn.setStyleSheet(render_qss("""
                QPushButton {
                    border: none; background: transparent;
                    color: $primary_color; font-size: 11px; font-weight: bold; padding: 0;
                }
                QPushButton:hover {
                    background: rgba($primary_color_rgb, 0.1);
                    border-radius: 4px;
                }
            """, get_active_theme()))
            chevron_btn.clicked.connect(
                lambda checked, ms=main_row, us=idx: self._toggle_utility_step_expand(ms, us)
            )
            item_layout.addWidget(chevron_btn)
        else:
            chevron_spacer = QFrame()
            chevron_spacer.setFixedWidth(CHEVRON_W)
            chevron_spacer.setStyleSheet("border: none; background: transparent;")
            item_layout.addWidget(chevron_spacer)

    def _show_utility_placeholder(self):
        """Shows a hint message when the utility steps list is empty."""
        self.utility_steps_list_widget.clear()
        placeholder = QListWidgetItem("Select a main step, then add utility sub-steps here\n(e.g. Enter Key after screen input)")
        placeholder.setFlags(Qt.ItemFlag.NoItemFlags)  # not selectable/clickable
        placeholder.setForeground(QColor(theme_color('disabled_text', get_active_theme())))
        font = placeholder.font()
        font.setItalic(True)
        placeholder.setFont(font)
        placeholder.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
        self.utility_steps_list_widget.addItem(placeholder)

    def display_utility_step_details(self, current_item, previous_item):
        """Displays utility step details in the Module Details table."""
        self.current_utility_step = None
        
        if not current_item:
            return
        
        item_data = current_item.data(Qt.ItemDataRole.UserRole)
        if not item_data:
            return
        
        # ✅ CRITICAL FIX: Get the actual utility step from added_steps, not from item_data
        main_step_index = item_data['main_step_index']
        sub_index = item_data.get('sub_index', 1)  # 1-based sub_index
        
        if main_step_index >= len(self.added_steps):
            return
        
        main_step = self.added_steps[main_step_index]
        utility_steps = main_step.get('utility_steps', [])
        
        # Convert sub_index (1-based) to 0-based array index
        utility_step_index = sub_index - 1
        
        if utility_step_index < 0 or utility_step_index >= len(utility_steps):
            return
        
        # ✅ Get the actual utility step reference (not a copy)
        utility_step = utility_steps[utility_step_index]
        self.current_utility_step = utility_step
        utility_type = utility_step.get('type')
        
        if utility_type == 'module_import':
            fields = utility_step.get('fields', [])
            action_type = fields[0].get('action_type', 'Input') if fields else 'Input'
            self.input_radio.blockSignals(True)
            self.validate_radio.blockSignals(True)
            if action_type == 'Validate':
                self.validate_radio.setChecked(True)
            else:
                self.input_radio.setChecked(True)
            self.input_radio.blockSignals(False)
            self.validate_radio.blockSignals(False)
        else:
            # Non-module utility steps — reset radio to Input silently
            self.input_radio.blockSignals(True)
            self.validate_radio.blockSignals(True)
            self.input_radio.setChecked(True)
            self.input_radio.blockSignals(False)
            self.validate_radio.blockSignals(False)        
        
        # Clear the table
        self.details_table.setRowCount(0)
        self.details_table.verticalHeader().setDefaultSectionSize(38)
        self.details_table.verticalHeader().setMinimumSectionSize(38)

        # Hide the screenshot caption widget by default; shown only for capture_screenshot steps
        if hasattr(self, 'screenshot_caption_container'):
            self.screenshot_caption_container.setVisible(False)

        # ✅ NEW: Handle random_input utility step
        if utility_type == 'random_input':
            self.details_table.setColumnCount(2)
            self.details_table.setHorizontalHeaderLabels(["Property", "Value"])
            self.details_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.details_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            
            is_special_key = utility_step.get('is_special_key', False)
            current_value = utility_step.get('value', '')
            is_end_key = is_special_key and current_value.lower() in ['end key', 'eraseeof']
            
            row_count = 5 if is_end_key else 4
            self.details_table.setRowCount(row_count)
            
            # Row
            row_property = QTableWidgetItem("Row")
            row_property.setFlags(row_property.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(0, 0, row_property)
            row_value = QLineEdit()
            row_value.setText(str(utility_step.get('row', '')))
            row_value.setValidator(QIntValidator(1, 999))
            self.details_table.setCellWidget(0, 1, row_value)
            
            # Column
            col_property = QTableWidgetItem("Column")
            col_property.setFlags(col_property.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(1, 0, col_property)
            col_value = QLineEdit()
            col_value.setText(str(utility_step.get('column', '')))
            col_value.setValidator(QIntValidator(1, 999))
            self.details_table.setCellWidget(1, 1, col_value)
            
            # Input Type
            type_property = QTableWidgetItem("Input Type")
            type_property.setFlags(type_property.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(2, 0, type_property)
            type_combo = QComboBox()
            type_combo.addItem("Text")
            type_combo.addItem("Special Key")
            type_combo.setCurrentText("Special Key" if is_special_key else "Text")
            self.details_table.setCellWidget(2, 1, type_combo)
            
            # Value
            value_property = QTableWidgetItem("Value")
            value_property.setFlags(value_property.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(3, 0, value_property)
            
            
            value_stack = QStackedWidget()
            text_input = QLineEdit()
            text_input.setText(utility_step.get('value', '') if not is_special_key else '')
            text_input.setPlaceholderText("Enter text value...")
            value_stack.addWidget(text_input)
            special_key_combo = QComboBox()
            special_key_combo.addItems(["End Key"])
            if is_special_key:
                index = special_key_combo.findText(current_value)
                if index >= 0:
                    special_key_combo.setCurrentIndex(index)
            value_stack.addWidget(special_key_combo)
            value_stack.setCurrentIndex(1 if is_special_key else 0)
            
            # ✅ NEW: Show/hide Remarks row dynamically
            def update_remarks_visibility():
                sel_is_special = (type_combo.currentText() == "Special Key")
                sel_value = special_key_combo.currentText() if sel_is_special else text_input.text()
                show_remarks = sel_is_special and sel_value.lower() in ['end key', 'eraseeof']
                self.details_table.setRowHidden(4, not show_remarks)

            type_combo.currentTextChanged.connect(lambda text: value_stack.setCurrentIndex(1 if text == "Special Key" else 0))
            type_combo.currentTextChanged.connect(lambda _: update_remarks_visibility())
            special_key_combo.currentTextChanged.connect(lambda _: update_remarks_visibility())
            
            self.details_table.setCellWidget(3, 1, value_stack)
            
            # ✅ NEW: Remarks row
            remarks_property = QTableWidgetItem("Remarks")
            remarks_property.setFlags(remarks_property.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(4, 0, remarks_property)
            remarks_value = QLineEdit()
            remarks_value.setText(utility_step.get('remarks', ''))
            remarks_value.setPlaceholderText("Enter remarks...")
            self.details_table.setCellWidget(4, 1, remarks_value)
            
            # Hide remarks row initially if not End Key
            self.details_table.setRowHidden(4, not is_end_key)
            
            return
        
        if utility_type == 'capture_screenshot':
            # Find reference module
            reference_module_name = None
            
            for i in range(main_step_index, -1, -1):
                check_step = self.added_steps[i]
                if check_step.get('type') == 'module_import':
                    reference_module_name = check_step.get('module_name')
                    break
            
            if reference_module_name:
                utility_step['reference_module'] = reference_module_name
                self.display_utility_screenshot_details(utility_step, reference_module_name)

        # AFTER:
        elif utility_type == 'find_text':
            self.details_table.setColumnCount(2)
            self.details_table.setHorizontalHeaderLabels(["Property", "Value"])
            self.details_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.details_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            self.details_table.setRowCount(10)        # rows: 0..3 fields, 4 vars, 5 retry, 6 exact, 7 expectation, 8 OFS, 9 sub-searches

            # Row 0 — Search Text (shortened) + Highlight? checkbox inline
            search_prop = QTableWidgetItem("Search Text")
            search_prop.setFlags(search_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(0, 0, search_prop)

            search_row_widget_u = QWidget()
            search_row_layout_u = QHBoxLayout(search_row_widget_u)
            search_row_layout_u.setContentsMargins(2, 1, 2, 1)
            search_row_layout_u.setSpacing(6)

            search_input = QLineEdit()
            search_input.setText(str(utility_step.get('search_text', '')))
            search_input.setPlaceholderText("Text to search for...")
            search_input.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            search_input.textChanged.connect(lambda val: utility_step.update({'search_text': val, 'name': f"Screen Text Lookup: '{val}'"}))
            search_row_layout_u.addWidget(search_input)

            # AFTER:
            highlight_chk_u = QCheckBox("Highlight?")
            highlight_chk_u.setChecked(bool(utility_step.get('highlight_found', False)))
            highlight_chk_u.setToolTip(
                "When checked, the found text will be highlighted in the next Capture Screenshot step\n"
                "using found_row, found_column and found_length."
            )
            def _on_highlight_chk_u_toggled(checked, _us=utility_step):
                _us['highlight_found'] = bool(checked)
                if checked:
                    QMessageBox.information(
                        self,
                        "Capture Screenshot Required",
                        "Please make sure you add a 'Capture Screenshot' test step\n"
                        "after this Screen Text Lookup step for the highlight to\n"
                        "take effect."
                    )
            highlight_chk_u.toggled.connect(_on_highlight_chk_u_toggled)
            search_row_layout_u.addWidget(highlight_chk_u)

            # Start Row
            start_prop = QTableWidgetItem("Start Row")
            start_prop.setFlags(start_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(1, 0, start_prop)
            start_input = QLineEdit()
            start_input.setText(str(utility_step.get('start_row', '')))
            start_input.setPlaceholderText("Default: 1")
            start_input.setValidator(QIntValidator(1, 999))
            start_input.textChanged.connect(lambda val: utility_step.update({'start_row': int(val) if val.isdigit() else 1}))
            self.details_table.setCellWidget(1, 1, start_input)

            # End Row
            end_prop = QTableWidgetItem("End Row")
            end_prop.setFlags(end_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(2, 0, end_prop)
            end_input = QLineEdit()
            end_input.setText(str(utility_step.get('end_row', '')))
            end_input.setPlaceholderText("Default: 24")
            end_input.setValidator(QIntValidator(1, 999))
            end_input.textChanged.connect(lambda val: utility_step.update({'end_row': int(val) if val.isdigit() else 24}))
            self.details_table.setCellWidget(2, 1, end_input)

            # Start Column
            col_prop = QTableWidgetItem("Start Column")
            col_prop.setFlags(col_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(3, 0, col_prop)
            col_input = QLineEdit()
            col_input.setText(str(utility_step.get('start_col', '1')))
            col_input.setValidator(QIntValidator(1, 999))
            col_input.textChanged.connect(lambda val: utility_step.update({'start_col': int(val) if val.isdigit() else 1}))
            self.details_table.setCellWidget(3, 1, col_input)

            # Area picker — lets the user pick a named region (defined on a
            # module via 'Manage Areas') instead of typing Start Row / End
            # Row / Start Column by hand. The list is automatically scoped to
            # whichever module was most recently imported by a 'Use Screen
            # Module' step at or before this utility step's parent main step
            # (no manual module selection needed). Selecting an Area
            # auto-fills the three fields above (via their existing
            # textChanged bindings); they stay editable for fine-tuning.
            _area_source_module_u = self._last_imported_module_before(main_step_index, inclusive=True)

            area_combo_u = QComboBox()
            area_label_u = QLabel("Area:")
            if _area_source_module_u:
                area_combo_u.setToolTip(
                    f"Pick a named Area from '{_area_source_module_u}' (the most recently\n"
                    "imported screen module) to auto-fill Start Row / End Row / Start\n"
                    "Column. You can still edit those fields afterwards."
                )
            else:
                area_combo_u.setEnabled(False)
                area_combo_u.setToolTip(
                    "No 'Use Screen Module' step exists at or before this step yet,\n"
                    "so there's no module to pick a named Area from."
                )
            area_combo_u.addItem("(Custom coordinates)", None)
            for area_def_u in get_module_areas(self.modules.get(_area_source_module_u, {})):
                area_combo_u.addItem(area_def_u['name'], (_area_source_module_u, area_def_u['name']))
            if utility_step.get('area_module') == _area_source_module_u and utility_step.get('area_name'):
                _area_idx_u = area_combo_u.findData((_area_source_module_u, utility_step.get('area_name')))
                area_combo_u.setCurrentIndex(_area_idx_u if _area_idx_u >= 0 else 0)
            else:
                area_combo_u.setCurrentIndex(0)

            def _on_area_combo_u_changed(i, _combo=area_combo_u, _us=utility_step, _sr=start_input, _er=end_input, _sc=col_input):
                data = _combo.itemData(i)
                if data is None:
                    _us.pop('area_module', None)
                    _us.pop('area_name', None)
                    return
                area_mod_name_i, area_name_i = data
                area_i = get_area_by_name(self.modules.get(area_mod_name_i, {}), area_name_i)
                if area_i:
                    _us['area_module'] = area_mod_name_i
                    _us['area_name'] = area_name_i
                    _sr.setText(str(area_i['start_row']))
                    _er.setText(str(area_i['end_row']))
                    _sc.setText(str(area_i['start_col']))
            area_combo_u.currentIndexChanged.connect(_on_area_combo_u_changed)

            search_row_layout_u.addWidget(area_label_u)
            search_row_layout_u.addWidget(area_combo_u)
            self.details_table.setCellWidget(0, 1, search_row_widget_u)

            # AFTER:
            # Variables (editable — defaults preserve backward compat)
            var_prop = QTableWidgetItem("Output Variables")
            var_prop.setFlags(var_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            var_prop.setToolTip("Names of the variables that will store the lookup result.\nDefaults: found_row, found_col, found_length")
            self.details_table.setItem(4, 0, var_prop)

            var_widget = QWidget()
            var_layout = QHBoxLayout(var_widget)
            var_layout.setContentsMargins(2, 1, 2, 1)
            var_layout.setSpacing(4)

            _var_row_edit   = QLineEdit()
            _var_col_edit   = QLineEdit()
            _var_len_edit   = QLineEdit()
            _var_row_edit.setText(str(utility_step.get('var_row_name',   'found_row')))
            _var_col_edit.setText(str(utility_step.get('var_col_name',   'found_col')))
            _var_len_edit.setText(str(utility_step.get('var_len_name',   'found_length')))
            _var_row_edit.setPlaceholderText("found_row")
            _var_col_edit.setPlaceholderText("found_col")
            _var_len_edit.setPlaceholderText("found_length")
            _var_row_edit.setToolTip("Variable name for the matched row number")
            _var_col_edit.setToolTip("Variable name for the matched column number")
            _var_len_edit.setToolTip("Variable name for the matched text length")

            def _on_var_row(val, _us=utility_step):
                _us['var_row_name'] = val.strip() or 'found_row'
            def _on_var_col(val, _us=utility_step):
                _us['var_col_name'] = val.strip() or 'found_col'
            def _on_var_len(val, _us=utility_step):
                _us['var_len_name'] = val.strip() or 'found_length'

            _var_row_edit.textChanged.connect(_on_var_row)
            _var_col_edit.textChanged.connect(_on_var_col)
            _var_len_edit.textChanged.connect(_on_var_len)

            for _lbl_txt, _edit in [("Row:", _var_row_edit), ("Col:", _var_col_edit), ("Len:", _var_len_edit)]:
                _lbl = QLabel(_lbl_txt)
                _lbl.setStyleSheet("color: #555; font-size: 10px;")
                var_layout.addWidget(_lbl)
                var_layout.addWidget(_edit)

            self.details_table.setCellWidget(4, 1, var_widget)

            # --- NEW: Retry Count ---
            retry_prop = QTableWidgetItem("Retry Count")
            retry_prop.setFlags(retry_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(5, 0, retry_prop)
            retry_spin = QSpinBox()
            retry_spin.setMinimum(0)
            retry_spin.setMaximum(20)
            retry_spin.setValue(int(utility_step.get('retry_count', 0) or 0))
            retry_spin.setToolTip("How many times to retry if text is not found (0 = no retry)")
            retry_spin.valueChanged.connect(lambda val: utility_step.update({'retry_count': val}))
            self.details_table.setCellWidget(5, 1, retry_spin)

            # --- NEW: Exact Match? ---
            exact_prop = QTableWidgetItem("Exact Match?")
            exact_prop.setFlags(exact_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(6, 0, exact_prop)
            exact_checkbox = QCheckBox("Match only when surrounded by spaces (no pre/post letters)")
            exact_checkbox.setChecked(bool(utility_step.get('exact_match', False)))
            exact_checkbox.setToolTip(
                "When checked, the search text must be surrounded by whitespace (or line edges).\n"
                "Example: searching '150.00' will NOT match '150.00-' because '-' follows the value."
            )
            exact_checkbox.toggled.connect(lambda val: utility_step.update({'exact_match': bool(val)}))
            self.details_table.setCellWidget(6, 1, exact_checkbox)

            # --- NEW: Lookup Expectation ---
            expectation_prop = QTableWidgetItem("Lookup Expectation")
            expectation_prop.setFlags(expectation_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(7, 0, expectation_prop)

            expectation_widget = QWidget()
            expectation_layout = QHBoxLayout(expectation_widget)
            expectation_layout.setContentsMargins(4, 2, 4, 2)
            expectation_layout.setSpacing(12)

            yes_radio_u = QRadioButton("Yes (text must be present)")
            no_radio_u  = QRadioButton("No (text must be absent)")
            _exp_group_u = QButtonGroup(expectation_widget)
            _exp_group_u.addButton(yes_radio_u)
            _exp_group_u.addButton(no_radio_u)
            current_expectation_u = str(utility_step.get('lookup_expectation', 'yes')).lower()
            yes_radio_u.setChecked(current_expectation_u != 'no')
            no_radio_u.setChecked(current_expectation_u == 'no')
            yes_radio_u.setToolTip("Default. Step fails if the search text is NOT found on screen.")
            no_radio_u.setToolTip("Inverted. Step fails if the search text IS found on screen.")

            def _on_yes_u(checked, _us=utility_step):
                if checked:
                    _us['lookup_expectation'] = 'yes'
                    _st = _us.get('search_text', '')
                    _us['name'] = f"Screen Text Lookup: '{_st}'"
                    _rc = int(_us.get('retry_count', 0) or 0)
                    if _rc > 0:
                        _us['name'] += f" (retry×{_rc})"
            def _on_no_u(checked, _us=utility_step):
                if checked:
                    _us['lookup_expectation'] = 'no'
                    _st = _us.get('search_text', '')
                    _us['name'] = f"Screen Text Lookup (NOT): '{_st}'"
                    _rc = int(_us.get('retry_count', 0) or 0)
                    if _rc > 0:
                        _us['name'] += f" (retry×{_rc})"
            yes_radio_u.toggled.connect(_on_yes_u)
            no_radio_u.toggled.connect(_on_no_u)

            expectation_layout.addWidget(yes_radio_u)
            expectation_layout.addWidget(no_radio_u)
            expectation_layout.addStretch()
            self.details_table.setCellWidget(7, 1, expectation_widget)

            # --- On Failure Sub-steps ---
            ofs_prop = QTableWidgetItem("On Failure Steps")
            ofs_prop.setFlags(ofs_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(8, 0, ofs_prop)

            ofs_widget = QWidget()
            ofs_layout = QVBoxLayout(ofs_widget)
            ofs_layout.setContentsMargins(4, 2, 4, 2)
            ofs_layout.setSpacing(3)

            # Mode toggle
            mode_row = QHBoxLayout()
            mode_row.setSpacing(8)
            same_radio = QRadioButton("Same steps for all retries")
            per_radio  = QRadioButton("Different steps per retry")
            current_ofs_mode = utility_step.get('ofs_mode', 'same')
            same_radio.setChecked(current_ofs_mode == 'same')
            per_radio.setChecked(current_ofs_mode == 'per_retry')
            mode_row.addWidget(same_radio)
            mode_row.addWidget(per_radio)
            mode_row.addStretch()
            ofs_layout.addLayout(mode_row)

            # Stacked widget: page 0 = same, page 1 = per-retry tabs
            ofs_stack = QStackedWidget()
            ofs_layout.addWidget(ofs_stack)

            # ── helper: build one list+buttons panel for a given step-list ──
            def _make_ofs_panel(step_list, parent_step, retry_key=None):
                """
                step_list  : the live Python list to mutate
                parent_step: the step dict (to store back if needed)
                retry_key  : if not None, key into 'on_failure_steps_per_retry'
                """
                panel = QWidget()
                pv = QVBoxLayout(panel)
                pv.setContentsMargins(0, 2, 0, 2)
                pv.setSpacing(3)

                lst = QListWidget()
                lst.setFixedHeight(130)
                for ofs in step_list:
                    lst.addItem(ofs.get('name', ofs.get('type', '?')))
                pv.addWidget(lst)

                btn_row = QHBoxLayout()
                btn_row.setSpacing(4)

                key_combo = QComboBox()
                key_combo.setFixedWidth(110)
                key_combo.addItems([
                    "Enter Key", "Clear Key", "End Key",
                    "F1","F2","F3","F4","F5","F6","F7","F8",
                    "F9","F10","F11","F12","F13","F14","F15",
                    "F16","F17","F18","F19","F20","F21","F22","F23","F24"
                ])
                btn_row.addWidget(key_combo)

                add_key = QPushButton("+ Key")
                add_key.setFixedWidth(60)
                add_key.setStyleSheet(get_theme1_only_button_qss())
                def _ak(checked=False, _l=lst, _c=key_combo, _sl=step_list):
                    kv = _c.currentText()
                    e = {'type': 'special_key', 'key_value': kv, 'name': f'Special Key: {kv}'}
                    _sl.append(e); _l.addItem(e['name'])
                add_key.clicked.connect(_ak)
                btn_row.addWidget(add_key)

                wspin = QSpinBox()
                wspin.setMinimum(1); wspin.setMaximum(60)
                wspin.setValue(2); wspin.setSuffix("s")
                wspin.setFixedWidth(60)
                btn_row.addWidget(wspin)

                add_wait = QPushButton("+ Wait")
                add_wait.setFixedWidth(70)
                add_wait.setStyleSheet(get_theme1_only_button_qss())
                def _aw(checked=False, _l=lst, _sp=wspin, _sl=step_list):
                    s = _sp.value()
                    e = {'type': 'wait', 'seconds': s, 'name': f'Wait: {s}s'}
                    _sl.append(e); _l.addItem(e['name'])
                add_wait.clicked.connect(_aw)
                btn_row.addWidget(add_wait)

                rem = QPushButton("Remove")
                rem.setFixedWidth(75)
                rem.setStyleSheet(get_theme1_only_button_qss())
                def _rm(checked=False, _l=lst, _sl=step_list):
                    r = _l.currentRow()
                    if r >= 0:
                        _l.takeItem(r)
                        if r < len(_sl): _sl.pop(r)
                rem.clicked.connect(_rm)
                btn_row.addWidget(rem)

                add_mod = QPushButton("+ Module")
                add_mod.setFixedWidth(90)
                add_mod.setStyleSheet(get_theme1_only_button_qss())
                def _am(checked=False, _l=lst, _sl=step_list):
                    dlg = OfsModuleDialog(self, self.modules)
                    if dlg.exec() == QDialog.DialogCode.Accepted:
                        e = dlg.get_ofs_data()
                        _sl.append(e); _l.addItem(e['name'])
                add_mod.clicked.connect(_am)
                btn_row.addWidget(add_mod)
                btn_row.addStretch()
                pv.addLayout(btn_row)

                def _dbl(item, _l=lst, _sl=step_list):
                    r = _l.row(item)
                    if r < 0 or r >= len(_sl): return
                    if _sl[r].get('type') != 'module_import': return
                    dlg = OfsModuleDialog(self, self.modules, existing_ofs=_sl[r])
                    if dlg.exec() == QDialog.DialogCode.Accepted:
                        _sl[r] = dlg.get_ofs_data()
                        _l.item(r).setText(_sl[r]['name'])
                lst.itemDoubleClicked.connect(_dbl)

                return panel

            # ── PAGE 0: same steps ──
            same_page = _make_ofs_panel(
                utility_step.setdefault('on_failure_steps', []),
                utility_step
            )
            ofs_stack.addWidget(same_page)

            # ── PAGE 1: per-retry tabs ──
            per_page = QWidget()
            per_layout = QVBoxLayout(per_page)
            per_layout.setContentsMargins(0, 0, 0, 0)
            per_layout.setSpacing(2)

            retry_tabs = QTabWidget()
            retry_tabs.setTabPosition(QTabWidget.TabPosition.North)
            per_layout.addWidget(retry_tabs)

            def _rebuild_retry_tabs_u():
                retry_tabs.clear()
                rc = int(utility_step.get('retry_count', 0) or 0)
                per_dict = utility_step.setdefault('on_failure_steps_per_retry', {})
                for i in range(rc):
                    key = str(i)
                    per_dict.setdefault(key, [])
                    tab_panel = _make_ofs_panel(per_dict[key], utility_step, retry_key=key)
                    retry_tabs.addTab(tab_panel, f"Retry {i+1}")
                if rc == 0:
                    empty = QLabel("Set Retry Count > 0 to configure per-retry steps.")
                    empty.setStyleSheet(render_qss("color: $disabled_text; font-style: italic; padding: 8px;", get_active_theme()))
                    retry_tabs.addTab(empty, "—")

            _rebuild_retry_tabs_u()
            ofs_stack.addWidget(per_page)

            # ── mode switch ──
            ofs_stack.setCurrentIndex(0 if current_ofs_mode == 'same' else 1)

            def _mode_changed_u():
                if same_radio.isChecked():
                    utility_step['ofs_mode'] = 'same'
                    ofs_stack.setCurrentIndex(0)
                else:
                    utility_step['ofs_mode'] = 'per_retry'
                    _rebuild_retry_tabs_u()
                    ofs_stack.setCurrentIndex(1)

            same_radio.toggled.connect(_mode_changed_u)

            # keep tabs in sync when retry count changes
            def _on_retry_count_changed_u(val):
                utility_step.update({'retry_count': val})
                if per_radio.isChecked():
                    _rebuild_retry_tabs_u()
            retry_spin.valueChanged.connect(_on_retry_count_changed_u)

            self.details_table.setCellWidget(8, 1, ofs_widget)
            self.details_table.setRowHeight(8, 270)

            # Row 9 — Sub-Searches (chained lookups relative to this
            # step's found row/column, e.g. "1 row after")
            subsearch_prop_u = QTableWidgetItem("Sub-Searches")
            subsearch_prop_u.setFlags(subsearch_prop_u.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(9, 0, subsearch_prop_u)

            subsearch_widget_u = QWidget()
            subsearch_layout_u = QHBoxLayout(subsearch_widget_u)
            subsearch_layout_u.setContentsMargins(4, 2, 4, 2)
            subsearch_layout_u.setSpacing(8)

            utility_step.setdefault('sub_searches', [])

            def _subsearch_btn_label_u(_us=utility_step):
                n = len(_us.get('sub_searches', []))
                return f"Manage Sub-Searches ({n})" if n else "Add Sub-Search..."

            subsearch_btn_u = QPushButton(_subsearch_btn_label_u())
            subsearch_btn_u.setToolTip(
                "Add follow-up searches whose Row/Column are relative offsets from\n"
                "where THIS step's primary search text is found (e.g. 1 row below)."
            )
            def _open_subsearch_mgr_u(checked=False, _us=utility_step):
                dlg = SubSearchManagerDialog(_us.get('sub_searches', []), parent=self)
                if dlg.exec() == QDialog.DialogCode.Accepted:
                    _us['sub_searches'] = dlg.get_sub_searches()
                    subsearch_btn_u.setText(_subsearch_btn_label_u())
                    self.main_window.save_test_cases_to_file()
            subsearch_btn_u.clicked.connect(_open_subsearch_mgr_u)
            subsearch_layout_u.addWidget(subsearch_btn_u)
            subsearch_layout_u.addStretch()
            self.details_table.setCellWidget(9, 1, subsearch_widget_u)
            return

        elif utility_type == 'wait':
            self.details_table.setColumnCount(2)
            self.details_table.setHorizontalHeaderLabels(["Property", "Value"])
            self.details_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.details_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            self.details_table.setRowCount(1)

            sec_prop = QTableWidgetItem("Seconds")
            sec_prop.setFlags(sec_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(0, 0, sec_prop)

            sec_spin = QSpinBox()
            sec_spin.setMinimum(1)
            sec_spin.setMaximum(3600)
            sec_spin.setValue(int(utility_step.get('seconds', 1)))
            sec_spin.setSuffix(" s")
            sec_spin.setToolTip("Number of seconds to wait")

            def _on_util_wait_sec_changed(val, _us=utility_step):
                _us['seconds'] = val
                _us['name'] = f"Wait: {val} second(s)"

            sec_spin.valueChanged.connect(_on_util_wait_sec_changed)
            self.details_table.setCellWidget(0, 1, sec_spin)
            return

        elif utility_type == 'copy_text':
            self.details_table.setColumnCount(2)
            self.details_table.setHorizontalHeaderLabels(["Property", "Value"])
            self.details_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.details_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            self.details_table.setRowCount(6)

            # Start Row
            row_prop = QTableWidgetItem("Start Row")
            row_prop.setFlags(row_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(0, 0, row_prop)
            row_input = QLineEdit()
            row_input.setText(str(utility_step.get('start_row', '')))
            row_input.setValidator(QIntValidator(1, 999))
            row_input.textChanged.connect(lambda val: utility_step.update({'start_row': int(val) if val.isdigit() else 1}))
            self.details_table.setCellWidget(0, 1, row_input)

            # Start Column
            col_prop = QTableWidgetItem("Start Column")
            col_prop.setFlags(col_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(1, 0, col_prop)
            col_input = QLineEdit()
            col_input.setText(str(utility_step.get('start_col', '')))
            col_input.setValidator(QIntValidator(1, 999))
            col_input.textChanged.connect(lambda val: utility_step.update({'start_col': int(val) if val.isdigit() else 1}))
            self.details_table.setCellWidget(1, 1, col_input)

            # Length
            len_prop = QTableWidgetItem("Length")
            len_prop.setFlags(len_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(2, 0, len_prop)
            len_input = QLineEdit()
            len_input.setText(str(utility_step.get('length', '')))
            len_input.setValidator(QIntValidator(1, 999))
            len_input.textChanged.connect(lambda val: utility_step.update({'length': int(val) if val.isdigit() else 1}))
            self.details_table.setCellWidget(2, 1, len_input)

            # Variable Name
            var_prop = QTableWidgetItem("Variable Name")
            var_prop.setFlags(var_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(3, 0, var_prop)
            var_input = QLineEdit()
            var_input.setText(str(utility_step.get('variable_name', '')))
            var_input.setPlaceholderText("e.g. First_Plastic")
            def on_var_changed(val):
                utility_step.update({
                    'variable_name': val,
                    'name': f"Extract Text at Position: '{val}' @ ({utility_step.get('start_row','?')},{utility_step.get('start_col','?')}) len={utility_step.get('length','?')}"
                })
            var_input.textChanged.connect(on_var_changed)
            self.details_table.setCellWidget(3, 1, var_input)

            # Strip Special Characters checkbox
            strip_prop = QTableWidgetItem("Strip Special Chars")
            strip_prop.setFlags(strip_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(4, 0, strip_prop)
            strip_checkbox = QCheckBox("Remove special characters from copied text")
            strip_checkbox.setChecked(utility_step.get('strip_special_chars', False))
            strip_checkbox.toggled.connect(lambda checked: utility_step.update({'strip_special_chars': checked}))
            self.details_table.setCellWidget(4, 1, strip_checkbox)

            # Usage info label
            var_name = utility_step.get('variable_name', '')
            info = QLabel(f"Use {{{var_name}}} in later Input/Validate steps")
            info.setStyleSheet(render_qss("color: $primary_color; font-style: italic; padding: 4px;", get_active_theme()))
            info_prop = QTableWidgetItem("Usage")
            info_prop.setFlags(info_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(5, 0, info_prop)
            self.details_table.setCellWidget(5, 1, info)
            return        
        
        elif utility_type == 'extract_field_text':
            self.details_table.setColumnCount(2)
            self.details_table.setHorizontalHeaderLabels(["Property", "Value"])
            self.details_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
            self.details_table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            self.details_table.setRowCount(5)
            self.details_table.verticalHeader().setDefaultSectionSize(38)
            self.details_table.verticalHeader().setMinimumWidth(30)
            self.details_table.verticalHeader().setDefaultAlignment(Qt.AlignmentFlag.AlignCenter)

            # Make sure the new 'rules' list exists; legacy keys are ignored.

            # Make sure the new 'rules' list exists; legacy keys are ignored.
            if not isinstance(utility_step.get('rules'), list):
                utility_step['rules'] = []

            # ---------- helper: list of field names from a module ----------
            def _field_names_for(module_name):
                names = []
                module_data = self.modules.get(module_name, {})
                for lbl in module_data.get('labels', []):
                    lname = lbl.get('name') or lbl.get('label') or lbl.get('text', '')
                    if lname:
                        names.append(lname)
                return names

            def _label_for_field(module_name, field_name):
                module_data = self.modules.get(module_name, {})
                for lbl in module_data.get('labels', []):
                    lname = lbl.get('name') or lbl.get('label') or lbl.get('text', '')
                    if lname == field_name:
                        return lbl
                return None

            def _update_step_name_u():
                vn = utility_step.get('variable_name', '')
                rules = utility_step.get('rules', []) or []
                no_cond_rules = [r for r in rules if r.get('no_condition', False)]
                cond_rules = [r for r in rules if not r.get('no_condition', False)]
                if not rules:
                    utility_step['name'] = f"Extract Field Text: '{vn}' (no rules)"
                elif no_cond_rules and not cond_rules:
                    utility_step['name'] = f"Extract Field Text: '{vn}' (always → {no_cond_rules[0].get('field_name','?')})"
                else:
                    utility_step['name'] = f"Extract Field Text: '{vn}' ({len(rules)} rule{'s' if len(rules) != 1 else ''})"

            # ---------- Row 0: Module ----------
            mod_prop = QTableWidgetItem("Module")
            mod_prop.setFlags(mod_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(0, 0, mod_prop)

            mod_combo = QComboBox()
            mod_combo.addItem("-- Select Module --")
            for mname in self.modules.keys():
                mod_combo.addItem(mname)
            cur_mod = utility_step.get('module_name', '')
            if cur_mod:
                mi = mod_combo.findText(cur_mod)
                if mi >= 0:
                    mod_combo.setCurrentIndex(mi)
            self.details_table.setCellWidget(0, 1, mod_combo)

            # ---------- Row 1: Variable Name ----------
            var_prop = QTableWidgetItem("Variable Name")
            var_prop.setFlags(var_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(1, 0, var_prop)
            var_input = QLineEdit()
            var_input.setText(str(utility_step.get('variable_name', '')))
            var_input.setPlaceholderText("e.g. AUTH_CD")

            def _on_var_u(val):
                utility_step.update({'variable_name': val})
                _update_step_name_u()
                _lbl = self.details_table.cellWidget(4, 1)
                if _lbl:
                    _lbl.setText(
                        f"Use {{{val}}} in later Input / Validate / Test Remark steps.\n"
                        "At runtime the first matching rule is used; if none match, the variable is set to empty."
                    )
            var_input.textChanged.connect(_on_var_u)
            self.details_table.setCellWidget(1, 1, var_input)

            # ---------- Row 2: Strip Special Chars ----------
            strip_prop = QTableWidgetItem("Strip Special Chars")
            strip_prop.setFlags(strip_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(2, 0, strip_prop)
            strip_cb = QCheckBox("Remove special characters from extracted text")
            strip_cb.setChecked(utility_step.get('strip_special_chars', False))
            strip_cb.toggled.connect(lambda v: utility_step.update({'strip_special_chars': v}))
            self.details_table.setCellWidget(2, 1, strip_cb)

            # ---------- Row 3: Rules ----------
            rules_prop = QTableWidgetItem("Field Rules")
            rules_prop.setFlags(rules_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(3, 0, rules_prop)

            # ── outer container ──────────────────────────────────────────────
            rules_widget = QWidget()
            rules_widget.setStyleSheet(render_qss("""
                QWidget { background: #f8f9fb; }
                QGroupBox {
                    font-weight: bold; font-size: 11px;
                    border: 1px solid #d0d5dd; border-radius: 6px;
                    margin-top: 6px; padding: 6px 8px;
                    background: $panel_background;
                }
                QGroupBox::title { subcontrol-origin: margin; left: 10px; padding: 0 4px; color: #344054; }
                QPushButton#addBtn {
                    background: #0052cc; color: white; border: none;
                    border-radius: 4px; padding: 4px 10px; font-size: 11px;
                }
                QPushButton#addBtn:hover { background: #0065ff; }
                QPushButton#addBtnSimple {
                    background: #27ae60; color: white; border: none;
                    border-radius: 4px; padding: 4px 10px; font-size: 11px;
                }
                QPushButton#addBtnSimple:hover { background: #2ecc71; }
                QPushButton#delBtn {
                    background: #fef3f2; color: #b42318; border: 1px solid #fecdca;
                    border-radius: 4px; padding: 2px 6px; font-size: 11px;
                }
                QPushButton#delBtn:hover { background: #fee4e2; }
                QLabel#ruleTag {
                    background: #e8f4fd; color: #0052cc; border-radius: 3px;
                    padding: 1px 6px; font-size: 10px; font-weight: bold;
                }
                QLabel#noCondTag {
                    background: #e6f4ea; color: #1e7e34; border-radius: 3px;
                    padding: 1px 6px; font-size: 10px; font-weight: bold;
                }
            """, get_active_theme()))
            outer_vbox = QVBoxLayout(rules_widget)
            outer_vbox.setContentsMargins(6, 6, 6, 6)
            outer_vbox.setSpacing(8)

            # ── scroll area that holds the per-rule cards ─────────────────────
            scroll_area = QScrollArea()
            scroll_area.setWidgetResizable(True)
            scroll_area.setFrameShape(QFrame.Shape.NoFrame)
            scroll_area.setMinimumHeight(180)

            cards_container = QWidget()
            cards_layout = QVBoxLayout(cards_container)
            cards_layout.setContentsMargins(0, 0, 0, 0)
            cards_layout.setSpacing(6)
            cards_layout.addStretch()
            scroll_area.setWidget(cards_container)
            outer_vbox.addWidget(scroll_area)

            # ── bottom button row ─────────────────────────────────────────────
            btn_row = QHBoxLayout()
            btn_row.setSpacing(8)

            add_cond_btn = QPushButton("＋ Add Rule with Condition")
            add_cond_btn.setObjectName("addBtn")
            add_cond_btn.setToolTip("Add a rule that only applies when a condition is met")

            add_nocond_btn = QPushButton("＋ Add Rule (No Condition)")
            add_nocond_btn.setObjectName("addBtnSimple")
            add_nocond_btn.setToolTip("Add a rule that always applies (no condition required)")

            btn_row.addWidget(add_cond_btn)
            btn_row.addWidget(add_nocond_btn)
            btn_row.addStretch()
            outer_vbox.addLayout(btn_row)

            # ── per-rule card builder ──────────────────────────────────────────
            def _make_rule_card(rule):
                is_no_cond = rule.get('no_condition', False)

                card = QFrame()
                card.setFrameShape(QFrame.Shape.StyledPanel)
                card.setStyleSheet(render_qss("QFrame { background: $panel_background; border: 1px solid #d0d5dd; border-radius: 6px; }", get_active_theme()))
                card_vbox = QVBoxLayout(card)
                card_vbox.setContentsMargins(10, 8, 10, 8)
                card_vbox.setSpacing(6)

                # ── header row: tag + delete ──────────────────────────────────
                hdr = QHBoxLayout()
                tag = QLabel("NO CONDITION" if is_no_cond else "WITH CONDITION")
                tag.setObjectName("noCondTag" if is_no_cond else "ruleTag")
                hdr.addWidget(tag)
                hdr.addStretch()
                del_btn = QPushButton("✕ Remove")
                del_btn.setObjectName("delBtn")
                del_btn.setFixedWidth(72)
                del_btn.clicked.connect(lambda _checked=False, _r=rule: _delete_rule(_r))
                hdr.addWidget(del_btn)
                card_vbox.addLayout(hdr)

                # ── Field row ────────────────────────────────────────────────
                field_row = QHBoxLayout()
                field_row.addWidget(QLabel("Field:"))
                fld_combo = QComboBox()
                fld_combo.addItem("-- Select Field --")
                for n in _field_names_for(utility_step.get('module_name', '')):
                    fld_combo.addItem(n)
                fi = fld_combo.findText(rule.get('field_name', ''))
                if fi >= 0:
                    fld_combo.setCurrentIndex(fi)
                def _on_field(val, _r=rule):
                    lbl = _label_for_field(utility_step.get('module_name', ''), val)
                    if lbl:
                        _r.update({
                            'field_name':   val,
                            'field_row':    int(lbl.get('row', 1)),
                            'field_col':    int(lbl.get('column', 1)),
                            'field_length': int(lbl.get('length', 1)),
                        })
                    else:
                        _r.update({'field_name': '', 'field_row': None, 'field_col': None, 'field_length': None})
                fld_combo.currentTextChanged.connect(_on_field)
                field_row.addWidget(fld_combo, 1)
                card_vbox.addLayout(field_row)

                # ── Condition row (only when not no_condition) ────────────────
                if not is_no_cond:
                    cond_row = QHBoxLayout()
                    cond_row.setSpacing(6)
                    cond_row.addWidget(QLabel("When:"))

                    lhs_combo = QComboBox()
                    _lhs_options = ["{found_row}", "{found_col}", "{found_length}"]
                    for _s in self.added_steps:
                        for _us in _s.get('utility_steps', []):
                            if _us.get('type') == 'find_text':
                                for _key, _default in [
                                    ('var_row_name', 'found_row'),
                                    ('var_col_name', 'found_col'),
                                    ('var_len_name', 'found_length'),
                                ]:
                                    _custom = str(_us.get(_key, _default)).strip() or _default
                                    _placeholder = '{' + _custom + '}'
                                    if _placeholder not in _lhs_options:
                                        _lhs_options.append(_placeholder)
                    lhs_combo.addItems(_lhs_options)
                    _current_lhs = rule.get('condition_variable', '{found_row}')
                    if lhs_combo.findText(_current_lhs) == -1:
                        lhs_combo.addItem(_current_lhs)
                    lhs_combo.setCurrentText(_current_lhs)
                    lhs_combo.currentTextChanged.connect(lambda v, _r=rule: _r.update({'condition_variable': v}))
                    cond_row.addWidget(lhs_combo)

                    op_combo = QComboBox()
                    op_combo.addItems(["=="])
                    op_combo.setFixedWidth(44)
                    op_combo.setCurrentText(rule.get('condition_operator', '=='))
                    op_combo.currentTextChanged.connect(lambda v, _r=rule: _r.update({'condition_operator': v}))
                    cond_row.addWidget(op_combo)

                    rhs_input = QLineEdit()
                    rhs_input.setText(str(rule.get('condition_value', '')))
                    rhs_input.setPlaceholderText("e.g. 6")
                    rhs_input.textChanged.connect(lambda v, _r=rule: _r.update({'condition_value': v}))
                    cond_row.addWidget(rhs_input, 1)
                    card_vbox.addLayout(cond_row)

                return card

            def _rebuild_rules_rows():
                # Remove all cards (keep the trailing stretch)
                while cards_layout.count() > 1:
                    item = cards_layout.takeAt(0)
                    if item.widget():
                        item.widget().deleteLater()
                rules = utility_step.get('rules', []) or []
                for r in rules:
                    card = _make_rule_card(r)
                    cards_layout.insertWidget(cards_layout.count() - 1, card)
                _update_step_name_u()

            def _delete_rule(rule):
                rules = utility_step.get('rules', []) or []
                try:
                    rules.remove(rule)
                except ValueError:
                    pass
                _rebuild_rules_rows()

            def _add_rule():
                rules = utility_step.setdefault('rules', [])
                rules.append({
                    'field_name': '', 'field_row': None, 'field_col': None, 'field_length': None,
                    'condition_variable': '{found_row}',
                    'condition_operator': '==',
                    'condition_value': '',
                    'no_condition': False,
                })
                _rebuild_rules_rows()

            def _add_rule_no_condition():
                rules = utility_step.setdefault('rules', [])
                rules.append({
                    'field_name': '', 'field_row': None, 'field_col': None, 'field_length': None,
                    'no_condition': True,
                })
                _rebuild_rules_rows()

            add_cond_btn.clicked.connect(_add_rule)
            add_nocond_btn.clicked.connect(_add_rule_no_condition)

            self.details_table.setCellWidget(3, 1, rules_widget)
            self.details_table.setRowHeight(3, 320)

            # When the module changes, repopulate all field combos
            def _on_module_changed_u(module_name):
                utility_step['module_name'] = module_name
                for r in (utility_step.get('rules') or []):
                    r.update({'field_name': '', 'field_row': None, 'field_col': None, 'field_length': None})
                _rebuild_rules_rows()
            mod_combo.currentTextChanged.connect(_on_module_changed_u)

            # ---------- Row 4: Usage hint ----------
            usage_prop = QTableWidgetItem("Usage")
            usage_prop.setFlags(usage_prop.flags() & ~Qt.ItemFlag.ItemIsEditable)
            self.details_table.setItem(4, 0, usage_prop)
            vn = utility_step.get('variable_name', '')
            usage_lbl = QLabel(
                f"Use {{{vn}}} in later Input / Validate / Test Remark steps.\n"
                "The first matching rule is used at runtime. "
                "'No Condition' rules always match immediately."
            )
            usage_lbl.setStyleSheet(render_qss("color: $primary_color; font-style: italic; padding: 4px;", get_active_theme()))
            usage_lbl.setWordWrap(True)
            self.details_table.setCellWidget(4, 1, usage_lbl)
            self.details_table.setRowHeight(4, 70)

            # Initial render
            _rebuild_rules_rows()
            return

        
        elif utility_type == 'module_import':
            module_name = utility_step.get('module_name')
            if module_name:
                self.display_utility_module_details(utility_step, module_name)        

