    def download_test_case_as_docx(self):
        """
        Downloads the current test case as a formatted DOCX document.
        Only includes meaningful steps (excludes Wait, Capture Screenshot, etc.)
        """
        from docx import Document
        from docx.shared import Pt, Inches, RGBColor
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from datetime import datetime
        import os
        
        # Get test case details
        test_case_name = self.test_case_name_input.text().strip()
        test_case_description = self.test_case_description_input.text().strip()
        test_case_assumptions = self.test_case_assumptions_input.toPlainText().strip()
        
        if not test_case_name:
            themed_warning(self, "Missing Name", "Please enter a test case name before downloading.")
            return
        
        # Ask user where to save
        default_filename = f"{test_case_name.replace(' ', '_')}_TestCase.docx"
        file_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Test Case Document",
            default_filename,
            "Word Documents (*.docx)"
        )
        
        if not file_path:
            return  # User cancelled
        
        try:
            # Create document
            doc = Document()
            
            # Add title
            title = doc.add_heading(test_case_name, level=1)
            title.alignment = WD_ALIGN_PARAGRAPH.CENTER
            title_run = title.runs[0]
            title_run.font.color.rgb = RGBColor(107, 44, 145)  # Purple color
            
            # Add metadata section
            # Add metadata section
            doc.add_paragraph()

            # ✅ CHANGED: Calculate row count dynamically based on additional info
            additional_info_count = len(self.additional_info_values) if self.additional_info_values else 0
            total_rows = 3 + additional_info_count  # Base rows (3) + additional info rows

            metadata_table = doc.add_table(rows=total_rows, cols=2)
            metadata_table.style = 'Light Grid Accent 1'

            row_index = 0

            # Test Case ID
            metadata_table.rows[row_index].cells[0].text = "Test Case ID:"
            metadata_table.rows[row_index].cells[1].text = test_case_name
            row_index += 1

            # Description
            metadata_table.rows[row_index].cells[0].text = "Description:"
            metadata_table.rows[row_index].cells[1].text = test_case_description or "N/A"
            row_index += 1

            # ✅ NEW: Add Additional Info fields here (between Description and Date)
            if self.additional_info_values:
                for field_name, field_value in self.additional_info_values.items():
                    if field_value:  # Only show fields with values
                        metadata_table.rows[row_index].cells[0].text = f"{field_name}:"
                        metadata_table.rows[row_index].cells[1].text = str(field_value)
                        row_index += 1

            # Date Generated (now at the end)
            metadata_table.rows[row_index].cells[0].text = "Generated On:"
            metadata_table.rows[row_index].cells[1].text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

            # Make first column bold
            for row in metadata_table.rows:
                for paragraph in row.cells[0].paragraphs:
                    for run in paragraph.runs:
                        run.font.bold = True
            
            # Add assumptions section (always)
            doc.add_paragraph()
            doc.add_heading("Assumptions:", level=2)
            if test_case_assumptions:
                doc.add_paragraph(test_case_assumptions)
            else:
                doc.add_paragraph("NA - Not Applicable")
            
            # Add prerequisites section (always)
            doc.add_paragraph()
            doc.add_heading("Prerequisites:", level=2)
            prerequisites = self.get_prerequisites()
            if prerequisites:
                for prereq in prerequisites:
                    prereq_para = doc.add_paragraph(prereq, style='List Bullet')
            else:
                doc.add_paragraph("NA - Not Applicable")



            # Add test steps section
            doc.add_paragraph()
            doc.add_heading("Test Steps:", level=2)
            
            step_counter = 1  # Counter for meaningful steps only
            
            # Process each main step
            for main_step_idx, step in enumerate(self.added_steps):
                step_type = step.get('type')
                
                # Skip non-meaningful steps
                if step_type in ['wait', 'capture_screenshot', 'capture_screen_text']:
                    continue
                
                # Process meaningful main steps
                if step_type == 'module_import':
                    # Only add if module has fields with values
                    fields = step.get('fields', [])
                    fields_with_values = [f for f in fields if f.get('value', '').strip()]
                    if fields_with_values:
                        self._add_module_step_to_doc(doc, step, step_counter)
                        step_counter += 1
                
                elif step_type == 'special_key':
                    # Skip End Key
                    key_value = step.get('key_value', '')
                    if key_value not in ['End Key', 'END KEY', 'End key', 'end key']:
                        self._add_special_key_to_doc(doc, step, step_counter)
                        step_counter += 1
                
                elif step_type == 'random_input':
                    self._add_random_input_to_doc(doc, step, step_counter)
                    step_counter += 1
                
                elif step_type == 'break':
                    self._add_break_step_to_doc(doc, step, step_counter)
                    step_counter += 1
                    
                elif step_type == 'notes':
                    self._add_notes_step_to_doc(doc, step, step_counter)
                    step_counter += 1

                elif step_type == 'find_text':
                    self._add_find_text_step_to_doc(doc, step, step_counter)
                    step_counter += 1                  
                
                elif step_type == 'copy_text':
                    self._add_copy_text_step_to_doc(doc, step, step_counter)
                    step_counter += 1

                elif step_type == 'extract_field_text':
                    self._add_extract_field_text_step_to_doc(doc, step, step_counter)
                    step_counter += 1

                # Process utility steps
                utility_steps = step.get('utility_steps', [])
                for utility_step in utility_steps:
                    utility_type = utility_step.get('type')
                    
                    # Skip non-meaningful utility steps
                    if utility_type in ['wait', 'capture_screenshot', 'capture_screen_text']:
                        continue
                    
                    if utility_type == 'module_import':
                        # Only add if module has fields with values
                        fields = utility_step.get('fields', [])
                        fields_with_values = [f for f in fields if f.get('value', '').strip()]
                        if fields_with_values:
                            self._add_module_step_to_doc(doc, utility_step, step_counter)
                            step_counter += 1
                    
                    elif utility_type == 'special_key':
                        # Skip End Key
                        key_value = utility_step.get('key_value', '')
                        if key_value not in ['End Key', 'END KEY', 'End key', 'end key']:
                            self._add_special_key_to_doc(doc, utility_step, step_counter)
                            step_counter += 1
                    
                    elif utility_type == 'random_input':
                        self._add_random_input_to_doc(doc, utility_step, step_counter)
                        step_counter += 1

                    elif utility_type == 'find_text':
                        self._add_find_text_step_to_doc(doc, utility_step, step_counter)
                        step_counter += 1

                    elif utility_type == 'copy_text':
                        self._add_copy_text_step_to_doc(doc, utility_step, step_counter)
                        step_counter += 1

                    elif utility_type == 'extract_field_text':
                        self._add_extract_field_text_step_to_doc(doc, utility_step, step_counter)
                        step_counter += 1

            # Save document
            doc.save(file_path)
            
            QMessageBox.information(
                self,
                "Success",
                f"Test case document saved successfully!\n\n{file_path}"
            )
            
            # Ask if user wants to open the file
            reply = QMessageBox.question(
                self,
                "Open Document",
                "Would you like to open the document now?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
            )
            
            if reply == QMessageBox.StandardButton.Yes:
                os.startfile(file_path)
        
        except Exception as e:
            QMessageBox.critical(
                self,
                "Error",
                f"Failed to save test case document:\n\n{str(e)}"
            )

    def _add_module_step_to_doc(self, doc, step, step_number):
        """Helper method to add a module import step to the document."""
        from docx.shared import Pt, RGBColor
        
        module_name = step.get('module_name', 'Unknown Module')
        fields = step.get('fields', [])
        
        # Determine action type
        action_type = 'Input'
        if fields:
            action_type = fields[0].get('action_type', 'Input')
        
        # Filter fields that have values
        fields_with_values = [f for f in fields if f.get('value', '').strip()]
        
        # Skip if no fields with values (this should not happen as we check before calling)
        if not fields_with_values:
            return
        
        # Add step heading
        step_heading = doc.add_paragraph()
        step_heading.add_run(f"Step {step_number}: ").bold = True
        
        if action_type == 'Input':
            step_heading.add_run(f"Input - {module_name}")
        else:
            step_heading.add_run(f"Validate - {module_name}")
        
        step_heading_run = step_heading.runs[0]
        step_heading_run.font.color.rgb = RGBColor(107, 44, 145)
        step_heading_run.font.size = Pt(12)
        
        # Reduce spacing after paragraph
        step_heading.paragraph_format.space_after = Pt(3)
        
        # Create table for fields with values
        table = doc.add_table(rows=len(fields_with_values) + 1, cols=2)
        table.style = 'Light List Accent 1'
        
        # Add headers
        header_cells = table.rows[0].cells
        header_cells[0].text = "Field Name"
        header_cells[1].text = "Value"
        
        # Make headers bold
        for cell in header_cells:
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:
                    run.font.bold = True
        
        # Add field data with different color for Validate steps
        for idx, field in enumerate(fields_with_values, start=1):
            row_cells = table.rows[idx].cells
            row_cells[0].text = field.get('field_name', 'N/A')
            row_cells[1].text = field.get('value', '')
            
            # Apply light orange background for Validate steps
            if action_type == 'Validate':
                from docx.oxml.ns import qn
                from docx.oxml import OxmlElement
                
                for cell in row_cells:
                    # Add light orange/yellow background to validation rows
                    tc = cell._element
                    tcPr = tc.get_or_add_tcPr()
                    shd = OxmlElement('w:shd')
                    shd.set(qn('w:fill'), 'FFF4E6')  # Light orange background
                    tcPr.append(shd)
        
        # Reduce spacing after table
        last_para = doc.paragraphs[-1]
        last_para.paragraph_format.space_after = Pt(6)

    def _add_special_key_to_doc(self, doc, step, step_number):
        """Helper method to add a special key step to the document."""
        from docx.shared import Pt, RGBColor
        
        key_value = step.get('key_value', 'Unknown Key')
        
        # Add step heading
        step_heading = doc.add_paragraph()
        step_heading.add_run(f"Step {step_number}: ").bold = True
        
        # Map special keys to meaningful descriptions
        if key_value == "Enter Key":
            step_heading.add_run("Press Enter")
        elif key_value == "Clear Key":
            step_heading.add_run("Clear the screen")
        else:
            # For function keys and other special keys (excluding End Key)
            step_heading.add_run(f"Press {key_value}")
        
        step_heading_run = step_heading.runs[0]
        step_heading_run.font.color.rgb = RGBColor(107, 44, 145)
        step_heading_run.font.size = Pt(12)
        
        # Reduce spacing after paragraph
        step_heading.paragraph_format.space_after = Pt(3)

    def _add_random_input_to_doc(self, doc, step, step_number):
        """Helper method to add a random input step to the document."""
        from docx.shared import Pt, RGBColor
        
        value = step.get('value', '').strip()
        row = step.get('row', '?')
        col = step.get('column', '?')
        is_special_key = step.get('is_special_key', False)
        remarks = step.get('remarks', '').strip()
        
        step_heading = doc.add_paragraph()
        step_heading.add_run(f"Step {step_number}: ").bold = True
        
        if is_special_key and value.lower() in ['end key', 'eraseeof']:
            # ✅ NEW: End Key handling
            if remarks:
                step_heading.add_run(f"Remove the value from the field '{remarks}'")
            else:
                step_heading.add_run(f"Remove the value from the field at Row {row}, Column {col}")
        elif is_special_key:
            if value.upper() == "ENTER KEY":
                step_heading.add_run("Press Enter")
            elif value.upper() == "CLEAR KEY":
                step_heading.add_run("Clear the screen")
            else:
                step_heading.add_run(f"Press {value}")
        else:
            if value.upper().startswith('D '):
                screen_name = value[2:].strip()
                step_heading.add_run(f"Open {screen_name} screen")
            else:
                step_heading.add_run(f"Input '{value}' at position ({row}, {col})")
        
        step_heading_run = step_heading.runs[0]
        step_heading_run.font.color.rgb = RGBColor(107, 44, 145)
        step_heading_run.font.size = Pt(12)
        step_heading.paragraph_format.space_after = Pt(3)

    def _add_break_step_to_doc(self, doc, step, step_number):
        """Helper method to add a break step to the document."""
        from docx.shared import Pt, RGBColor
        from docx.oxml.ns import qn
        from docx.oxml import OxmlElement
        import re
        
        message_html = step.get('message', '').strip()
        
        # Add step heading
        step_heading = doc.add_paragraph()
        step_heading.add_run(f"Step {step_number}: ").bold = True
        step_heading.add_run("Important Instructions/Message")
        
        step_heading_run = step_heading.runs[0]
        step_heading_run.font.color.rgb = RGBColor(107, 44, 145)
        step_heading_run.font.size = Pt(12)
        
        # Reduce spacing after paragraph
        step_heading.paragraph_format.space_after = Pt(3)
        
        # Add the message content
        if message_html:
            # Better HTML stripping - remove style tags and their content first
            # Remove <style>...</style> blocks
            plain_text = re.sub(r'<style[^>]*>.*?</style>', '', message_html, flags=re.DOTALL | re.IGNORECASE)
            
            # Remove all other HTML tags
            plain_text = re.sub(r'<[^>]+>', '', plain_text)
            
            # Replace HTML entities
            plain_text = plain_text.replace('&nbsp;', ' ')
            plain_text = plain_text.replace('&lt;', '<')
            plain_text = plain_text.replace('&gt;', '>')
            plain_text = plain_text.replace('&amp;', '&')
            plain_text = plain_text.replace('&quot;', '"')
            plain_text = plain_text.replace('&#39;', "'")
            
            # Clean up extra whitespace and newlines
            plain_text = ' '.join(plain_text.split())
            plain_text = plain_text.strip()
            
            if plain_text:
                # Create a bordered box for the message
                message_para = doc.add_paragraph()
                message_para.style = 'Intense Quote'
                message_para.add_run(plain_text)
                
                # Add light yellow background to the paragraph
                pPr = message_para._element.get_or_add_pPr()
                shd = OxmlElement('w:shd')
                shd.set(qn('w:fill'), 'FFF9E6')  # Light yellow background
                pPr.append(shd)
                
                # Reduce spacing after message
                message_para.paragraph_format.space_after = Pt(6)
            else:
                no_msg_para = doc.add_paragraph("(No message content)", style='List Bullet')
                no_msg_para.paragraph_format.space_after = Pt(6)
        else:
            no_msg_para = doc.add_paragraph("(No message content)", style='List Bullet')
            no_msg_para.paragraph_format.space_after = Pt(6)

    def _add_notes_step_to_doc(self, doc, step, step_number):
        """Helper method to add a notes step to the document, preserving full HTML formatting."""
        from docx.shared import Pt, RGBColor
        from docx.oxml.ns import qn
        from docx.oxml import OxmlElement

        message_html = step.get('message', '').strip()

        # Step heading
        step_heading = doc.add_paragraph()
        step_heading.add_run(f"Step {step_number}: ").bold = True
        step_heading.add_run("Test Remark")
        step_heading_run = step_heading.runs[0]
        step_heading_run.font.color.rgb = RGBColor(107, 44, 145)
        step_heading_run.font.size = Pt(12)
        step_heading.paragraph_format.space_after = Pt(3)

        if message_html:
            # ✅ Use the same rich HTML renderer used during test execution
            # This preserves tables, bold, italic, underline, colours etc.
            copy_text_vars = getattr(self, '_copy_text_variables', {})
            _render_remark_html_to_docx(doc, message_html, copy_text_vars)
        else:
            no_content = doc.add_paragraph("(No remark content)")
            no_content.paragraph_format.space_after = Pt(6)

        # Separator line after the remark
        sep = doc.add_paragraph()
        sep.paragraph_format.space_after = Pt(3)
        
    def _add_find_text_step_to_doc(self, doc, step, step_number):
        """Helper method to add a Find Text (Screen Text Lookup) step to the document."""
        from docx.shared import Pt, RGBColor

        search_text        = step.get('search_text', '')
        start_row          = step.get('start_row', 1)
        end_row            = step.get('end_row', 24)
        exact_match        = step.get('exact_match', False)
        lookup_expectation = step.get('lookup_expectation', 'yes')

        # --- Heading ---
        step_heading = doc.add_paragraph()
        run1 = step_heading.add_run(f"Step {step_number}: ")
        run1.bold = True
        run1.font.color.rgb = RGBColor(107, 44, 145)
        run1.font.size = Pt(12)

        run2 = step_heading.add_run("Screen Text Lookup")
        run2.font.color.rgb = RGBColor(107, 44, 145)
        run2.font.size = Pt(12)

        step_heading.paragraph_format.space_after = Pt(3)

        # --- Main description line ---
        desc = doc.add_paragraph()
        if lookup_expectation == 'no':
            desc.add_run("Verify that the text ").font.size = Pt(11)
        else:
            desc.add_run("Look for the text ").font.size = Pt(11)

        search_run = desc.add_run(f"'{search_text}'")
        search_run.bold = True
        search_run.font.size = Pt(11)

        if lookup_expectation == 'no':
            trailing_run = desc.add_run(" is NOT present on the screen")
        else:
            trailing_run = desc.add_run(", and its position will be used for the next step")
        trailing_run.font.size = Pt(11)

        desc.paragraph_format.space_after = Pt(2)

        # --- Detail line: row range, match mode, expectation ---
        detail = doc.add_paragraph()
        detail.paragraph_format.left_indent = Pt(18)
        detail.paragraph_format.space_after = Pt(6)

        detail.add_run("Search rows: ").font.size = Pt(10)
        rows_run = detail.add_run(f"{start_row} – {end_row}")
        rows_run.bold = True
        rows_run.font.size = Pt(10)

        detail.add_run("   |   Match mode: ").font.size = Pt(10)
        match_run = detail.add_run("Exact" if exact_match else "Partial")
        match_run.bold = True
        match_run.font.size = Pt(10)

        detail.add_run("   |   Expectation: ").font.size = Pt(10)
        expect_run = detail.add_run("Text must NOT be found" if lookup_expectation == 'no' else "Text must be found")
        expect_run.bold = True
        expect_run.font.size = Pt(10)
        expect_run.font.color.rgb = RGBColor(180, 0, 0) if lookup_expectation == 'no' else RGBColor(0, 128, 0)

        # --- Output variables line ---
        var_row_name = str(step.get('var_row_name', '') or 'found_row').strip() or 'found_row'
        var_col_name = str(step.get('var_col_name', '') or 'found_col').strip() or 'found_col'

        var_line = doc.add_paragraph()
        var_line.paragraph_format.left_indent = Pt(18)
        var_line.paragraph_format.space_after = Pt(6)
        var_line.add_run("Output variables: ").font.size = Pt(10)

        vr_run = var_line.add_run(f"{{{var_row_name}}}")
        vr_run.bold = True
        vr_run.font.size = Pt(10)
        vr_run.font.color.rgb = RGBColor(107, 44, 145)

        var_line.add_run(" (matched row)   ").font.size = Pt(10)

        vc_run = var_line.add_run(f"{{{var_col_name}}}")
        vc_run.bold = True
        vc_run.font.size = Pt(10)
        vc_run.font.color.rgb = RGBColor(107, 44, 145)

        var_line.add_run(" (matched column)").font.size = Pt(10)

        doc.add_paragraph()        
        
    def _add_copy_text_step_to_doc(self, doc, step, step_number):
        """Helper method to add a Copy Text step to the document."""
        from docx.shared import Pt, RGBColor

        variable_name = step.get('variable_name', '')
        start_row = step.get('start_row', '')
        start_col = step.get('start_col', '')
        length = step.get('length', '')

        step_heading = doc.add_paragraph()
        run1 = step_heading.add_run(f"Step {step_number}: ")
        run1.bold = True
        run1.font.color.rgb = RGBColor(107, 44, 145)
        run1.font.size = Pt(12)

        run2 = step_heading.add_run("Extract Text at Position")
        run2.font.color.rgb = RGBColor(107, 44, 145)
        run2.font.size = Pt(12)

        step_heading.paragraph_format.space_after = Pt(3)

        desc = doc.add_paragraph()
        desc.add_run("Read ").font.size = Pt(11)

        len_run = desc.add_run(f"{length} character(s)")
        len_run.bold = True
        len_run.font.size = Pt(11)

        desc.add_run(f" from row ").font.size = Pt(11)

        pos_run = desc.add_run(f"{start_row}, column {start_col}")
        pos_run.bold = True
        pos_run.font.size = Pt(11)

        desc.add_run(" and store in variable ").font.size = Pt(11)

        var_run = desc.add_run(f"{{{variable_name}}}")
        var_run.bold = True
        var_run.font.size = Pt(11)
        var_run.font.color.rgb = RGBColor(107, 44, 145)

        desc.paragraph_format.space_after = Pt(6)
        doc.add_paragraph()        
  
    def _add_extract_field_text_step_to_doc(self, doc, step, step_number):
        """Helper method to add an Extract Field Text step to the document."""
        from docx.shared import Pt, RGBColor

        variable_name      = step.get('variable_name', '').strip()
        module_name        = step.get('module_name', '').strip()
        rules              = step.get('rules', []) or []
        strip_special      = step.get('strip_special_chars', False)

        # --- Heading ---
        step_heading = doc.add_paragraph()
        run1 = step_heading.add_run(f"Step {step_number}: ")
        run1.bold = True
        run1.font.color.rgb = RGBColor(107, 44, 145)
        run1.font.size = Pt(12)

        run2 = step_heading.add_run("Extract Field Text")
        run2.font.color.rgb = RGBColor(107, 44, 145)
        run2.font.size = Pt(12)

        step_heading.paragraph_format.space_after = Pt(3)

        # --- Main description ---
        desc = doc.add_paragraph()
        desc.add_run("Extract a field value from the screen").font.size = Pt(11)
        if module_name:
            desc.add_run(" using module ").font.size = Pt(11)
            mod_run = desc.add_run(f"'{module_name}'")
            mod_run.bold = True
            mod_run.font.size = Pt(11)
        desc.add_run(" and store the result in variable ").font.size = Pt(11)

        var_run = desc.add_run(f"{{{variable_name}}}" if variable_name else "(not configured)")
        var_run.bold = True
        var_run.font.size = Pt(11)
        var_run.font.color.rgb = RGBColor(107, 44, 145)

        desc.add_run(".").font.size = Pt(11)
        if strip_special:
            note_run = desc.add_run("  Special characters will be stripped from the captured value.")
            note_run.font.size = Pt(10)
            note_run.italic = True
        desc.paragraph_format.space_after = Pt(2)

        # --- Rules table (one row per rule) ---
        if rules:
            rules_label = doc.add_paragraph()
            rules_label.paragraph_format.left_indent = Pt(18)
            rules_label.paragraph_format.space_after = Pt(2)
            rl_run = rules_label.add_run(f"Configured rule(s): {len(rules)}")
            rl_run.bold = True
            rl_run.font.size = Pt(10)

            tbl = doc.add_table(rows=1 + len(rules), cols=4)
            tbl.style = 'Light Grid Accent 1'

            # Header row
            hdr_cells = tbl.rows[0].cells
            for idx, hdr_text in enumerate(["Rule #", "Field Name", "Condition", "Action"]):
                hdr_cells[idx].text = hdr_text
                for para in hdr_cells[idx].paragraphs:
                    for run in para.runs:
                        run.bold = True

            for ri, rule in enumerate(rules):
                cells = tbl.rows[ri + 1].cells
                cells[0].text = str(ri + 1)

                field_name = rule.get('field_name', '—')
                cells[1].text = field_name if field_name else '—'

                if rule.get('no_condition', False):
                    cells[2].text = "Always (no condition)"
                else:
                    cond_var   = rule.get('condition_variable', '')
                    cond_op    = rule.get('condition_operator', '==')
                    cond_value = str(rule.get('condition_value', ''))
                    cells[2].text = f"{cond_var} {cond_op} {cond_value}" if cond_var else "—"

                fr = rule.get('field_row', '?')
                fc = rule.get('field_col', '?')
                fl = rule.get('field_length', '?')
                cells[3].text = f"Row {fr}, Col {fc}, Len {fl}"

        doc.add_paragraph()  
  
    def _set_combo_by_data(self, combo, data):
        """Sets a QComboBox to the item matching the given data value, matched by text."""
        if isinstance(data, tuple):
            target_text = f"Step {data[0]}.{data[1]}"
        else:
            target_text = f"Step {data}"
        
        for i in range(combo.count()):
            if combo.itemText(i) == target_text:
                combo.setCurrentIndex(i)
                return
  
    def _open_module_preview(self, module_name):
        """
        Opens (or brings to front) the ModulePreviewDialog for the given module.
        Stores reference so highlight_field() can be called when user clicks a label.
        """
        module_data = self.modules.get(module_name)
        if not module_data:
            QMessageBox.warning(self, "Module Not Found",
                                f"Module '{module_name}' not found.")
            return

        # Reuse existing popup if already open for the same module
        existing = getattr(self, '_module_preview_dialog', None)
        if existing and not existing.isHidden() and existing.module_name == module_name:
            existing.raise_()
            existing.activateWindow()
            return

        dlg = ModulePreviewDialog(module_name, module_data, parent=self)
        self._module_preview_dialog = dlg
        dlg.show()
        dlg.raise_()  
  
    def _show_step_module_sys_id(self, step):
        """
        Shows the sys_id of the module a test case step (module_import)
        points to. Prefers the sys_id stored directly on the step; falls
        back to resolving it by the step's current module_name if the step
        predates the sys_id feature and hasn't been touched since.
        """
        module_name = step.get('module_name', '') or ''
        sys_id = step.get('module_sys_id')

        if not sys_id:
            module_data = self.modules.get(module_name)
            if isinstance(module_data, dict):
                sys_id = module_data.get('sys_id')

        if not sys_id:
            QMessageBox.warning(
                self, "sysid Not Found",
                f"No sys_id could be found for module '{module_name}'.\n"
                "This step may reference a module that no longer exists."
            )
            return

        self.main_window._show_sys_id_dialog(f"Step module: {module_name}", sys_id)

    def _show_step_module_json(self, step):
        """
        Shows the JSON for the module a test case step (module_import)
        points to. Resolved the same way sys_id lookups are — preferring
        the step's stored module_sys_id (so a rename of the module since
        this step was added still resolves to the right module) and
        falling back to the step's cached module_name otherwise.
        """
        module_name = step.get('module_name', '') or ''
        sys_id = step.get('module_sys_id')

        resolved_name = None
        if sys_id:
            resolved_name, _ = self.main_window.get_module_by_sys_id(sys_id)
        if not resolved_name:
            resolved_name = module_name

        self.main_window._show_module_json(resolved_name)

    def show_main_step_context_menu(self, position):
        item = self.steps_list_widget.itemAt(position)
        if not item:
            return
        row = self.steps_list_widget.row(item)
        step_number = row + 1  # 1-based
        total_steps = len(self.added_steps)

        menu = QMenu(self)

        # Execute action
        execute_action = QAction(f"▶  Execute Step {step_number}", self)
        execute_action.triggered.connect(lambda: self._execute_single_main_step(step_number))
        menu.addAction(execute_action)

        # ── Module Preview ────────────────────────────────────────────
        step_data_for_preview = self.added_steps[row] if 0 <= row < len(self.added_steps) else {}
        if step_data_for_preview.get('type') == 'module_import':
            module_name_for_preview = step_data_for_preview.get('module_name', '')
            if module_name_for_preview and module_name_for_preview in self.modules:
                preview_action = QAction("🔍  Module Preview", self)
                preview_action.setToolTip(f"Show a preview of module '{module_name_for_preview}'")
                preview_action.triggered.connect(
                    lambda _, mn=module_name_for_preview: self._open_module_preview(mn)
                )
                menu.addAction(preview_action)

            show_sysid_action = QAction("🆔  Show sysid", self)
            show_sysid_action.triggered.connect(
                lambda _, s=step_data_for_preview: self._show_step_module_sys_id(s)
            )
            menu.addAction(show_sysid_action)

            show_json_action = QAction("🧾  Show JSON", self)
            show_json_action.triggered.connect(
                lambda _, s=step_data_for_preview: self._show_step_module_json(s)
            )
            menu.addAction(show_json_action)

            # Manual refresh — lets the user re-sync this step against the
            # module's current definition even when no mismatch is flagged.
            refresh_module_action = QAction("🔄  Refresh Module", self)
            refresh_module_action.setToolTip(
                f"Re-sync this step with the current definition of '{module_name_for_preview}'."
            )
            refresh_module_action.triggered.connect(
                lambda _, r=row: self.refresh_step_module(r, show_message=True, skip_dialog=True)
            )
            menu.addAction(refresh_module_action)

        menu.addSeparator()

        # Disable / Enable action — supports multi-selection
        selected_items = self.steps_list_widget.selectedItems()
        selected_rows = [self.steps_list_widget.row(i) for i in selected_items]
        if row not in selected_rows:
            selected_rows = [row]

        # AFTER
        if len(selected_rows) > 1:
            any_enabled  = any(not self.added_steps[r].get('disabled', False) for r in selected_rows)
            any_disabled = any(self.added_steps[r].get('disabled', False) for r in selected_rows)

            if any_enabled:
                disable_action = QAction(f"🚫  Disable {len(selected_rows)} Steps", self)
                disable_action.triggered.connect(lambda: self._set_main_steps_disabled(selected_rows, True))
                menu.addAction(disable_action)

            if any_disabled:
                enable_action = QAction(f"✅  Enable {len(selected_rows)} Steps", self)
                enable_action.triggered.connect(lambda: self._set_main_steps_disabled(selected_rows, False))
                menu.addAction(enable_action)
        else:
            step_data = self.added_steps[row]
            is_disabled = step_data.get('disabled', False)
            if is_disabled:
                toggle_action = QAction(f"✅  Enable Step {step_number}", self)
            else:
                toggle_action = QAction(f"🚫  Disable Step {step_number}", self)
            toggle_action.triggered.connect(lambda: self._toggle_main_step_disabled(row))
            menu.addAction(toggle_action)

        menu.addSeparator()


        # Move To submenu
        if total_steps > 1:
            move_menu = QMenu("↕  Move To Position...", self)
            for target_row in range(total_steps):
                target_num = target_row + 1
                if target_row == row:
                    continue  # skip current position
                # Build a short label from the target step
                target_step = self.added_steps[target_row]
                target_type = target_step.get('type', '')
                if target_type == 'module_import':
                    target_label = target_step.get('module_name', 'Unknown Module')
                elif target_type == 'special_key':
                    target_label = f"Send Keystroke: {target_step.get('key_value', '')}"
                elif target_type == 'capture_screen_text':
                    target_label = "Capture Screenshot (Text)"
                elif target_type == 'capture_screenshot':
                    target_label = "Capture Screenshot (DOCX)"
                elif target_type == 'wait':
                    target_label = f"Wait: {target_step.get('seconds', '?')}s"
                elif target_type == 'break':
                    target_label = "Manual Checkpoint"
                elif target_type == 'notes':
                    target_label = "Test Remark"
                elif target_type == 'find_text':
                    target_label = f"Screen Text Lookup: '{target_step.get('search_text', '')}'"
                elif target_type == 'copy_text':
                    target_label = f"Extract Text: '{target_step.get('variable_name', '')}'"
                elif target_type == 'random_input':
                    target_label = f"Send to Position ({target_step.get('row','?')},{target_step.get('column','?')})"
                else:
                    target_label = "Unknown Step"
                direction = "↑" if target_row < row else "↓"
                action_text = f"{direction}  Step {target_num}: {target_label}"
                action = QAction(action_text, self)
                action.triggered.connect(
                    lambda checked, src=row, dst=target_row: self._move_main_step_to(src, dst)
                )
                move_menu.addAction(action)
            menu.addMenu(move_menu)

        menu.addSeparator()
        save_template_action = QAction("💾  Save as Template...", self)
        save_template_action.triggered.connect(
            lambda: self.save_as_template(selected_rows)
        )
        menu.addAction(save_template_action)

        menu.exec(self.steps_list_widget.viewport().mapToGlobal(position))

    def show_utility_step_context_menu(self, position):
        item = self.utility_steps_list_widget.itemAt(position)
        if not item:
            return

        main_row = self.steps_list_widget.currentRow()
        if main_row < 0:
            return
        main_step_number = main_row + 1
        utility_row = self.utility_steps_list_widget.row(item)
        utility_step_number = utility_row + 1  # 1-based

        utility_steps = self.added_steps[main_row].get('utility_steps', [])
        total_utility = len(utility_steps)

        menu = QMenu(self)

        # Execute action
        execute_action = QAction(f"▶  Execute Step {main_step_number}.{utility_step_number}", self)
        execute_action.triggered.connect(
            lambda: self._execute_single_utility_step(main_step_number, utility_step_number)
        )
        menu.addAction(execute_action)

        # ── Module Preview ────────────────────────────────────────────
        u_step_for_preview = utility_steps[utility_row] if 0 <= utility_row < len(utility_steps) else {}
        if u_step_for_preview.get('type') == 'module_import':
            u_module_name_for_preview = u_step_for_preview.get('module_name', '')
            if u_module_name_for_preview and u_module_name_for_preview in self.modules:
                u_preview_action = QAction("🔍  Module Preview", self)
                u_preview_action.setToolTip(f"Show a preview of module '{u_module_name_for_preview}'")
                u_preview_action.triggered.connect(
                    lambda _, mn=u_module_name_for_preview: self._open_module_preview(mn)
                )
                menu.addAction(u_preview_action)

            u_show_json_action = QAction("🧾  Show JSON", self)
            u_show_json_action.triggered.connect(
                lambda _, s=u_step_for_preview: self._show_step_module_json(s)
            )
            menu.addAction(u_show_json_action)

            # Manual refresh — lets the user re-sync this utility step against
            # the module's current definition even when no mismatch is flagged.
            u_refresh_module_action = QAction("🔄  Refresh Module", self)
            u_refresh_module_action.setToolTip(
                f"Re-sync this step with the current definition of '{u_module_name_for_preview}'."
            )
            u_refresh_module_action.triggered.connect(
                lambda _, mr=main_row, ur=utility_row: self.refresh_utility_step_module(
                    mr, ur, show_message=True, skip_dialog=True
                )
            )
            menu.addAction(u_refresh_module_action)

        menu.addSeparator()

        # Disable / Enable action — supports multi-selection
        selected_utility_items = self.utility_steps_list_widget.selectedItems()
        selected_utility_rows = [self.utility_steps_list_widget.row(i) for i in selected_utility_items]
        if utility_row not in selected_utility_rows:
            selected_utility_rows = [utility_row]

        if len(selected_utility_rows) > 1:
            disable_action = QAction(f"🚫  Disable {len(selected_utility_rows)} Steps", self)
            disable_action.triggered.connect(
                lambda: self._set_utility_steps_disabled(main_row, selected_utility_rows, True)
            )
            menu.addAction(disable_action)

            enable_action = QAction(f"✅  Enable {len(selected_utility_rows)} Steps", self)
            enable_action.triggered.connect(
                lambda: self._set_utility_steps_disabled(main_row, selected_utility_rows, False)
            )
            menu.addAction(enable_action)
        elif utility_row < len(utility_steps):
            u_step = utility_steps[utility_row]
            u_is_disabled = u_step.get('disabled', False)
            if u_is_disabled:
                u_toggle_action = QAction(f"✅  Enable Step {main_step_number}.{utility_step_number}", self)
            else:
                u_toggle_action = QAction(f"🚫  Disable Step {main_step_number}.{utility_step_number}", self)
            u_toggle_action.triggered.connect(
                lambda: self._toggle_utility_step_disabled(main_row, utility_row)
            )
            menu.addAction(u_toggle_action)

        # Make Child / Remove Child — the very first utility step has no
        # step above it, so it can never become a child.
        if utility_row > 0 and utility_row < len(utility_steps):
            u_step_hier = utility_steps[utility_row]
            if u_step_hier.get('is_child', False):
                make_toplevel_action = QAction("⬅  Remove Child (Make Top-Level)", self)
                make_toplevel_action.triggered.connect(
                    lambda: self._make_utility_step_top_level(main_row, utility_row)
                )
                menu.addAction(make_toplevel_action)
            else:
                make_child_action = QAction("↳  Make Child", self)
                make_child_action.setToolTip(
                    "Make this step a child of its nearest parent step above it."
                )
                make_child_action.triggered.connect(
                    lambda: self._make_utility_step_child(main_row, utility_row)
                )
                menu.addAction(make_child_action)

        menu.addSeparator()

        # Move To submenu
        if total_utility > 1:
            move_menu = QMenu("↕  Move To Position...", self)
            for target_row in range(total_utility):
                if target_row == utility_row:
                    continue  # skip current position
                target_step = utility_steps[target_row]
                target_label = target_step.get('name', 'Utility Step')
                direction = "↑" if target_row < utility_row else "↓"
                action_text = f"{direction}  Step {main_step_number}.{target_row + 1}: {target_label}"
                action = QAction(action_text, self)
                action.triggered.connect(
                    lambda checked, src=utility_row, dst=target_row, ms=main_row:
                        self._move_utility_step_to(ms, src, dst)
                )
                move_menu.addAction(action)
            menu.addMenu(move_menu)

        menu.exec(self.utility_steps_list_widget.viewport().mapToGlobal(position))

    def _set_main_steps_disabled(self, rows, disabled):
        """Sets the disabled flag on multiple main steps and all their utility steps."""
        for row in rows:
            if row < 0 or row >= len(self.added_steps):
                continue
            step = self.added_steps[row]
            step['disabled'] = disabled
            for u_step in step.get('utility_steps', []):
                u_step['disabled'] = disabled
        self.update_steps_list()
        current_row = self.steps_list_widget.currentRow()
        if current_row >= 0:
            self.refresh_utility_steps_for_main_step(current_row)
        self.main_window.save_test_cases_to_file()

    def _set_utility_steps_disabled(self, main_row, utility_rows, disabled):
        """Sets the disabled flag on multiple utility steps, with parent-disabled guard on enable."""
        if main_row < 0 or main_row >= len(self.added_steps):
            return
        main_step = self.added_steps[main_row]
        utility_steps = main_step.get('utility_steps', [])

        # Block enabling any utility step when the parent main step is disabled
        if disabled is False and main_step.get('disabled', False):
            QMessageBox.warning(
                self,
                "Cannot Enable Utility Steps",
                f"Step {main_row + 1} is disabled.\n\n"
                f"To enable these utility steps, enable the main step — "
                f"this will automatically enable all its utility steps."
            )
            return

        for utility_row in utility_rows:
            if utility_row < 0 or utility_row >= len(utility_steps):
                continue
            utility_steps[utility_row]['disabled'] = disabled
        self.refresh_utility_steps_for_main_step(main_row)
        self.main_window.save_test_cases_to_file()


    def _toggle_main_step_disabled(self, row):
        """Toggles the disabled flag on a main step and all its utility steps, then refreshes the UI."""
        if row < 0 or row >= len(self.added_steps):
            return
        step = self.added_steps[row]
        new_state = not step.get('disabled', False)
        step['disabled'] = new_state
        # Cascade to all utility steps
        for u_step in step.get('utility_steps', []):
            u_step['disabled'] = new_state
        self.update_steps_list()
        # Re-select the same row so utility panel refreshes
        self.steps_list_widget.setCurrentRow(row)
        self.refresh_utility_steps_for_main_step(row)
        self.main_window.save_test_cases_to_file()

    def _toggle_utility_step_disabled(self, main_row, utility_row):
        """Toggles the disabled flag on a single utility step, then refreshes the UI."""
        if main_row < 0 or main_row >= len(self.added_steps):
            return
        utility_steps = self.added_steps[main_row].get('utility_steps', [])
        if utility_row < 0 or utility_row >= len(utility_steps):
            return

        # ✅ Block enabling a utility step when its parent main step is disabled
        main_step = self.added_steps[main_row]
        u_step = utility_steps[utility_row]
        if main_step.get('disabled', False) and u_step.get('disabled', False):
            QMessageBox.warning(
                self,
                "Cannot Enable Utility Step",
                f"Step {main_row + 1} is disabled.\n\n"
                f"To enable this utility step, enable the main step — "
                f"this will automatically enable all its utility steps."
            )
            return

        u_step['disabled'] = not u_step.get('disabled', False)
        self.refresh_utility_steps_for_main_step(main_row)
        self.main_window.save_test_cases_to_file()

    def _execute_single_main_step(self, step_number):
        """Sets start and end combos to the given main step and executes."""

    def _execute_single_main_step(self, step_number):
        """Sets start and end combos to the given main step and executes."""
        self._set_combo_by_data(self.start_step_combo, step_number)
        self._set_combo_by_data(self.end_step_combo, step_number)
        self.execute_test_case_preview(
            override_start=step_number,
            override_end=step_number
        )

    def _execute_single_utility_step(self, main_step, utility_step):
        """Sets start and end combos to the given utility step and executes."""
        self._set_combo_by_data(self.start_step_combo, (main_step, utility_step))
        self._set_combo_by_data(self.end_step_combo, (main_step, utility_step))
        self.execute_test_case_preview(
            override_start=(main_step, utility_step),
            override_end=(main_step, utility_step)
        ) 
  
