    def changeEvent(self, event):
        """Handle window state changes."""
        from PyQt6.QtCore import QEvent
        
        if event.type() == QEvent.Type.WindowStateChange:
            old_state = event.oldState()
            new_state = self.windowState()
            
            was_minimized = bool(old_state & Qt.WindowState.WindowMinimized)
            is_minimized = bool(new_state & Qt.WindowState.WindowMinimized)
            
            # When minimizing - just print what we have saved
            if not was_minimized and is_minimized:
                print("🔽 Window minimizing")
                # Block dock-visibility tracking for the whole minimize->restore
                # window. Qt/OS can emit spurious visibilityChanged(False) signals
                # for docks (especially with a floating library window open)
                # right as windowState() flips back to "not minimized", which
                # would otherwise overwrite the saved state before we get a
                # chance to restore it.
                self._dock_transition_in_progress = True
                # Capture current dock sizes too - forcing setVisible(True) on
                # a dock during restore makes Qt re-layout it from scratch,
                # which can snap it back to a default/equal-split size. We
                # reapply these exact sizes afterward so Libraries, any
                # detached library panel, and (by leaving them the room they
                # had) the PCOMM Screen Preview all keep their proportions.
                #
                # NOTE: don't gate this on dock.isVisible() here - by the
                # time changeEvent() fires for the minimize, Qt has already
                # marked child docks as "not visible" even though their
                # pixel width/height is still intact, so that check was
                # silently skipping the capture. Whether a given size should
                # actually be reapplied is decided later, in
                # _reapply_saved_dock_sizes(), based on visibility *after*
                # the restore completes.
                self._saved_dock_sizes = {
                    'libraries_width': self.libraries_dock.width(),
                    'bottom_height': self.bottom_dock.height(),
                    'detached_widths': {
                        key: d.width()
                        for key, d in getattr(self, '_detached_library_docks', {}).items()
                        if d is not None
                    },
                }
                print(f"✅ Will restore - Libraries: {self._saved_libraries_state}, Properties: {self._saved_properties_state}")
            # When restoring from minimized
            elif was_minimized and not is_minimized:
                print("🔼 Window restoring - will restore dock states")
                QTimer.singleShot(100, self.restore_dock_states)
        
        super().changeEvent(event)

    def closeEvent(self, event):
        try:
            self.save_test_cases_to_file()
            self.save_modules_to_file()
            self._save_window_state()
            event.accept()
        except Exception as e:
            reply = QMessageBox.question(
                self,
                "Save Failed",
                f"Could not save data before closing:\n\n{str(e)}\n\n"
                "Close anyway and risk losing changes?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No
            )
            if reply == QMessageBox.StandardButton.Yes:
                event.accept()
            else:
                event.ignore()

    def setup_dock_tracking(self):
        """Track dock visibility changes in real-time."""
        if hasattr(self, 'libraries_dock') and self.libraries_dock:
            self.libraries_dock.visibilityChanged.connect(self.on_dock_visibility_changed)
        if hasattr(self, 'bottom_dock') and self.bottom_dock:
            self.bottom_dock.visibilityChanged.connect(self.on_dock_visibility_changed)

    def on_dock_visibility_changed(self, visible):
        """Called whenever a dock's visibility changes."""
        # Only track if window is NOT minimized and we're not in the middle
        # of a minimize->restore transition (see changeEvent / restore_dock_states).
        if getattr(self, '_dock_transition_in_progress', False):
            return
        if not (self.windowState() & Qt.WindowState.WindowMinimized):
            if hasattr(self, 'libraries_dock') and hasattr(self, 'bottom_dock'):
                self._saved_libraries_state = self.libraries_dock.isVisible()
                self._saved_properties_state = self.bottom_dock.isVisible()
            # Also track any library panels popped out via right-click
            # "Open in Separate Window" (self._detached_library_docks).
            if hasattr(self, '_detached_library_docks'):
                if not hasattr(self, '_saved_detached_dock_states'):
                    self._saved_detached_dock_states = {}
                for key, d in self._detached_library_docks.items():
                    if d is not None:
                        self._saved_detached_dock_states[key] = d.isVisible()
                
    def restore_dock_states(self):
        """Restore dock widget visibility states after restore/maximize."""
        libraries_should_show = self._saved_libraries_state
        properties_should_show = self._saved_properties_state
        
        print(f"🔄 Restoring - Libraries: {libraries_should_show}, Properties: {properties_should_show}")
        
        # Restore Libraries dock
        if self.libraries_dock and libraries_should_show:
            self.libraries_dock.setVisible(True)
            self.libraries_dock.raise_()
            if hasattr(self, 'toggle_libraries_action'):
                self.toggle_libraries_action.setChecked(True)
        
        # Restore Module Properties dock
        if self.bottom_dock and properties_should_show:
            self.bottom_dock.setVisible(True)
            self.bottom_dock.raise_()
            if hasattr(self, 'toggle_properties_action'):
                self.toggle_properties_action.setChecked(True)

        # Restore any detached library panels (e.g. "Modules Library"
        # opened in its own panel via right-click) that were open before
        # minimizing.
        if hasattr(self, '_detached_library_docks') and hasattr(self, '_saved_detached_dock_states'):
            for key, should_show in self._saved_detached_dock_states.items():
                d = self._detached_library_docks.get(key)
                if d is not None and should_show:
                    d.setVisible(True)
                    d.raise_()
        
        # Transition is fully complete now - resume normal tracking.
        self._dock_transition_in_progress = False

        # Reapply the exact sizes docks had before minimizing. Must run on
        # the next event-loop tick (QTimer.singleShot(0, ...)) - same reason
        # as _apply_panel_sizing() in open_library_in_separate_window(): Qt
        # hasn't finished computing layout geometry immediately after
        # setVisible(True), so resizeDocks() called synchronously here would
        # be ignored or only partially applied.
        QTimer.singleShot(0, self._reapply_saved_dock_sizes)
        
        print(f"✅ Restored")

    def resizeEvent(self, event):
        """Standard Qt resize hook. Used to detect when a pending
        default-layout restore's window has ACTUALLY finished resizing -
        see _restore_default_layout()/_on_resize_settled(). Polling
        self.width()/height() from an external QTimer was found to return
        stale values while a native cross-monitor maximize was still in
        flight; resizeEvent is the one place Qt guarantees the reported
        size is real."""
        super().resizeEvent(event)
        if getattr(self, '_pending_layout_restore', None) is not None:
            if hasattr(self, '_resize_settle_timer') and self._resize_settle_timer is not None:
                self._resize_settle_timer.stop()
            self._resize_settle_timer = QTimer(self)
            self._resize_settle_timer.setSingleShot(True)
            self._resize_settle_timer.timeout.connect(self._on_resize_settled)
            # No further resizeEvent for 150ms straight = treat as settled.
            self._resize_settle_timer.start(150)

    def _on_resize_settled(self):
        """Fires once resizeEvent has gone quiet for 150ms while a default-
        layout restore is pending - i.e. the cross-monitor maximize/resize
        has actually finished, and self.width()/height() are trustworthy."""
        pending = getattr(self, '_pending_layout_restore', None)
        if pending is None:
            return
        generation, state_data = pending
        if generation != getattr(self, '_layout_restore_generation', None):
            return  # Superseded by a newer restore - drop it.
        self._pending_layout_restore = None
        print(f"✅ Resize settled at {self.width()}x{self.height()} "
              f"on screen {self.screen().name() if self.screen() else '?'}")
        self._reapply_default_layout_ratios(state_data, generation)

    def _reapply_saved_dock_sizes(self):
        """Reapplies the dock sizes captured just before minimizing, so
        Libraries, any detached library panel, and Module & Properties all
        come back at the same size (rather than Qt's default equal split)."""
        sizes = getattr(self, '_saved_dock_sizes', None)
        if not sizes:
            return

        width_docks, widths = [], []
        if sizes.get('libraries_width') and self.libraries_dock.isVisible():
            width_docks.append(self.libraries_dock)
            widths.append(sizes['libraries_width'])
        for key, w in sizes.get('detached_widths', {}).items():
            d = getattr(self, '_detached_library_docks', {}).get(key)
            if d is not None and d.isVisible():
                width_docks.append(d)
                widths.append(w)
        if width_docks:
            self.resizeDocks(width_docks, widths, Qt.Orientation.Horizontal)

        if sizes.get('bottom_height') and self.bottom_dock.isVisible():
            self.resizeDocks([self.bottom_dock], [sizes['bottom_height']], Qt.Orientation.Vertical)
    
    def get_test_case_data(self, test_case_name):
            """Helper method to get test case data from projects or standalone test cases."""
            if hasattr(self, 'projects'):
                for project_data in self.projects.values():
                    if test_case_name in project_data.get('test_cases', {}):
                        return project_data['test_cases'][test_case_name]
            if hasattr(self, 'displayed_test_cases'):
                return self.displayed_test_cases.get(test_case_name)
            return None    
    
    def substitute_execution_variables(self, text, test_case_name):
        from datetime import datetime
        now = datetime.now()
        test_case_data = self.get_test_case_data(test_case_name)
        test_description = test_case_data.get('description', '') if test_case_data else ''

        variables = {
            'date': now.strftime('%Y.%m.%d'),
            'time': now.strftime('%H:%M:%S'),
            'datetime': now.strftime('%Y-%m-%d %H:%M:%S'),
            'test_case_id': test_case_name,
            'test_description': test_description,
            'found_row': str(getattr(self, '_found_row', '')),
            'found_col': str(getattr(self, '_found_col', '')),
            'found_length': str(getattr(self, '_found_length', '')),
        }

        copy_text_vars = getattr(self, '_copy_text_variables', {})
        variables.update(copy_text_vars)

        result = text
        for var_name, var_value in variables.items():
            placeholder = '{' + var_name + '}'
            result = result.replace(placeholder, var_value)
        stripped = result.strip()
        if stripped in copy_text_vars:
            result = copy_text_vars[stripped]
        return result    
    def update_selection_info_status_only(self, start_row, start_col, selected_text, selection_length):
        """Updates only the status bar without triggering any popups."""
        message = (
            f"Selection: '{selected_text.replace('\n', '')}' | "
            f"Start: ({start_row}, {start_col}) | "
            f"Length: {selection_length}"
        )
        self.statusBar().showMessage(message, 0)       
       
    def execute_testcase_on_pcomm(self, testcase_data):
        """
        Send defined test case values to PCOMM Session A screen.
        testcase_data: list of dicts with {label, row, col, value}
        Example:
            [
              {"label": "CARD NUMBER", "row": 5, "col": 12, "value": "4567123412341234"},
              {"label": "EXPIRY", "row": 5, "col": 40, "value": "1226"},
              {"label": "AMOUNT", "row": 7, "col": 15, "value": "5000"},
            ]
        """
        try:
            pythoncom.CoInitialize()

            # Connect to PCOMM Session A
            autECLSession = win32com.client.Dispatch("PCOMM.autECLSession")
            autECLSession.SetConnectionByName("A")
            autECLPS = autECLSession.autECLPS

            # 1️⃣ Create empty screen (24x80 = 1920 spaces)
            screen = [[" " for _ in range(80)] for _ in range(24)]

            # 2️⃣ Fill in each field value at given row/col
            for field in testcase_data:
                val = str(field.get("value", "")).strip()
                if not val:
                    continue  # skip empty
                row = int(field["row"]) - 1
                col = int(field["col"]) - 1
                for i, ch in enumerate(val):
                    if col + i < 80:
                        screen[row][col + i] = ch

            # 3️⃣ Join into one full-screen string
            screen_text = "\n".join("".join(r) for r in screen)

            # 4️⃣ Move to home and send all text
            autECLPS.SetCursorPos(1, 1)
            autECLPS.SendKeys(screen_text)

            QMessageBox.information(self, "Success", "Test case values pushed to PCOMM screen successfully.")
        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to send test data to PCOMM.\n\n{str(e)}")
        finally:
            pythoncom.CoUninitialize()

        
