        self._zoom_level_label.setCursor(Qt.CursorShape.PointingHandCursor)
        self._zoom_level_label.mousePressEvent = lambda _: self.pcomm_canvas_text_edit.zoom_reset()

        zoom_in_btn = QPushButton("+")
