    def update_template_tree(self):
        """
        Redesigned template tree matching the Modules Library style.
        Custom widget rows with hover gradient, save/delete buttons on hover.
        Right-click context menu preserved via existing show_template_context_menu.
        """
        self.template_tree.clear()
        self.template_tree_root = None
        self.template_tree.setRootIsDecorated(False)
        self.template_tree.setIndentation(0)

        if not self.templates:
            placeholder = QTreeWidgetItem(self.template_tree)
            placeholder.setText(0, "No templates yet.  👉 Use 'Link Data Source' to create a template.")
            placeholder.setForeground(0, QColor(theme_color('disabled_text', get_active_theme())))
            placeholder.setFlags(Qt.ItemFlag.NoItemFlags)
            return

        ROW_H = 40

        def make_template_row(tmpl_name, tmpl_item):
            w = QWidget()
            w.setFixedHeight(ROW_H)
            w.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)

            HOVER_STYLE = lambda: render_qss("""background-color: #F8E6B2; border-bottom: 1px solid $hover_background;""", get_active_theme())
            SELECTED_STYLE = lambda: render_qss("""background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                stop:0 $selected_item_gradient_1, stop:0.25 $selected_item_gradient_2,
                stop:0.5 $selected_item_gradient_3, stop:0.75 $selected_item_gradient_2,
                stop:1 $selected_item_gradient_5); border-bottom: 1px solid $hover_background;""", get_active_theme())
            NORMAL_STYLE = lambda: render_qss("background: $panel_background; border-bottom: 1px solid $hover_background;", get_active_theme())

            w.setStyleSheet(NORMAL_STYLE())
            w._selected = False

            row = QHBoxLayout(w)
            row.setContentsMargins(8, 0, 6, 0)
            row.setSpacing(0)

            # Template icon indicator (small colored pill)
            icon_lbl = QLabel("⬡")
            icon_lbl.setStyleSheet("""
                color: #6B2C91; font-size: 10pt;
                background: transparent; padding-right: 4px;
            """)
            icon_lbl.setFixedWidth(20)
            row.addWidget(icon_lbl)

            name_lbl = QLabel(tmpl_name)
            self._apply_themed_style(name_lbl, """
                color: $primary_color; font-size: 9pt;
                background: transparent; padding-left: 2px;
            """)
            name_lbl.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
            row.addWidget(name_lbl, 1)

            # Base test case label (secondary info)
            tmpl_data = self.templates.get(tmpl_name, {})
            base_tc = tmpl_data.get('base_test_case', '')
            if base_tc:
                base_lbl = QLabel(f"← {base_tc}")
                self._apply_themed_style(base_lbl, """
                    color: $secondary_text; font-size: 8pt;
                    background: transparent; padding-right: 6px;
                """)
                base_lbl.setVisible(False)
                base_lbl.setMaximumWidth(0)
                row.addWidget(base_lbl)
            else:
                base_lbl = None

            save_btn = QPushButton()
            save_btn.setIcon(QIcon(resource_path("save.png")))
            save_btn.setIconSize(QSize(14, 14))
            save_btn.setFixedSize(26, 26)
            save_btn.setToolTip(f"Export '{tmpl_name}' Excel template")
            save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            self._apply_themed_style(save_btn, """
                QPushButton {
                    border: none; background: transparent;
                    border-radius: 4px; padding: 0;
                }
                QPushButton:hover { background: $status_info_bg; }
                QPushButton:pressed { background: #bfdbfe; }
            """)
            save_btn.setVisible(False)
            save_btn.setMaximumWidth(0)
            save_btn.clicked.connect(
                lambda checked=False, n=tmpl_name: self._export_template_excel(n))
            row.addWidget(save_btn)

            del_btn = QPushButton()
            del_btn.setIcon(QIcon(resource_path("bin.png")))
            del_btn.setIconSize(QSize(15, 15))
            del_btn.setFixedSize(26, 26)
            del_btn.setToolTip(f"Delete '{tmpl_name}'")
            del_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            self._apply_themed_style(del_btn, """
                QPushButton {
                    border: none; background: transparent;
                    border-radius: 4px; padding: 0;
                }
                QPushButton:hover { background: $close_button_hover; }
                QPushButton:pressed { background: $status_danger_bg; }
            """)
            del_btn.setVisible(False)
            del_btn.setMaximumWidth(0)
            del_btn.clicked.connect(
                lambda checked=False, i=tmpl_item: self.delete_template(i))
            row.addWidget(del_btn)

            def _get_all_template_widgets():
                result = []
                root = self.template_tree.invisibleRootItem()
                for i in range(root.childCount()):
                    child = root.child(i)
                    cw = self.template_tree.itemWidget(child, 0)
                    if cw and hasattr(cw, '_selected'):
                        result.append((cw, child))
                return result

            def _enter(event):
                if not w._selected:
                    w.setStyleSheet(HOVER_STYLE())
                save_btn.setVisible(True)
                save_btn.setMaximumWidth(26)
                del_btn.setVisible(True)
                del_btn.setMaximumWidth(26)
                if base_lbl:
                    base_lbl.setVisible(True)
                    base_lbl.setMaximumWidth(200)

            def _leave(event):
                if not w._selected:
                    w.setStyleSheet(NORMAL_STYLE())
                save_btn.setVisible(False)
                save_btn.setMaximumWidth(0)
                del_btn.setVisible(False)
                del_btn.setMaximumWidth(0)
                if base_lbl:
                    base_lbl.setVisible(False)
                    base_lbl.setMaximumWidth(0)

            def _click(event):
                if event.button() == Qt.MouseButton.RightButton:
                    if not w._selected:
                        for widget, _item in _get_all_template_widgets():
                            if widget is not w:
                                widget._selected = False
                                widget.setStyleSheet(NORMAL_STYLE())
                        w._selected = True
                        w.setStyleSheet(SELECTED_STYLE())
                    self.template_tree.clearSelection()
                    for widget, item in _get_all_template_widgets():
                        if widget._selected:
                            item.setSelected(True)
                    # Show context menu at cursor position
                    global_pos = w.mapToGlobal(event.pos())
                    local_pos = self.template_tree.viewport().mapFromGlobal(global_pos)
                    self.show_template_context_menu(local_pos)
                    return

                if event.type() == event.Type.MouseButtonDblClick:
                    self._show_template_info_dialog(tmpl_name)
                    return

                modifiers = QApplication.keyboardModifiers()
                ctrl = modifiers & Qt.KeyboardModifier.ControlModifier

                if ctrl:
                    w._selected = not w._selected
                    w.setStyleSheet(SELECTED_STYLE() if w._selected else NORMAL_STYLE())
                else:
                    for widget, _item in _get_all_template_widgets():
                        if widget is not w:
                            widget._selected = False
                            widget.setStyleSheet(NORMAL_STYLE())
                    w._selected = True
                    w.setStyleSheet(SELECTED_STYLE())

                self.template_tree.clearSelection()
                for widget, item in _get_all_template_widgets():
                    if widget._selected:
                        item.setSelected(True)

            w.enterEvent = _enter
            w.leaveEvent = _leave
            w.mousePressEvent = _click
            w.mouseDoubleClickEvent = _click

            return w

        # Build the tree — one row per template (flat, no nested root node)
        for tmpl_name in self.templates.keys():
            tmpl_item = QTreeWidgetItem(self.template_tree)
            tmpl_item.setData(0, Qt.ItemDataRole.UserRole, tmpl_name)
            tmpl_item.setSizeHint(0, QSize(0, ROW_H))
            tmpl_item.setFirstColumnSpanned(True)
            self.template_tree.setItemWidget(
                tmpl_item, 0, make_template_row(tmpl_name, tmpl_item))

        # Keep a reference for context menu compatibility
        self.template_tree_root = self.template_tree.invisibleRootItem()

    def _export_template_excel(self, template_name):
        """Exports the linked Excel file path info, or saves the template metadata."""
        template_data = self.templates.get(template_name)
        if not template_data:
            return

        excel_path = template_data.get('excel_path', '')
        if excel_path and os.path.exists(excel_path):
            # Offer to copy or re-export the template
            reply = QMessageBox.question(
                self,
                "Export Template",
                f"Template '{template_name}' is linked to:\n{os.path.basename(excel_path)}\n\n"
                "Open the linked Excel file location?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.Yes
            )
            if reply == QMessageBox.StandardButton.Yes:
                try:
                    import subprocess
                    subprocess.Popen(['explorer', '/select,', os.path.normpath(excel_path)])
                except Exception as e:
                    QMessageBox.warning(self, "Error", f"Could not open file location:\n{e}")
        else:
            self._themed_warning(
                "File Not Found",
                f"The linked Excel file for '{template_name}' could not be found.\n\n"
                f"Expected: {excel_path}"
            )

    def _show_template_info_dialog(self, template_name):
        """Shows a quick info popup for a template on double-click."""
        template_data = self.templates.get(template_name)
        if not template_data:
            return

        excel_path = template_data.get('excel_path', 'Unknown')
        file_exists = os.path.exists(excel_path)

        info = (
            f"<b>{template_name}</b><br><br>"
            f"<b>Excel File:</b> {os.path.basename(excel_path)}<br>"
            f"<b>Sheet:</b> {template_data.get('sheet_name', 'Unknown')}<br>"
            f"<b>Base Test Case:</b> {template_data.get('base_test_case', 'Unknown')}<br>"
            f"<b>Linked:</b> {template_data.get('linked_date', 'Unknown')}<br>"
            f"<b>Status:</b> {'✓ File exists' if file_exists else '✗ File not found'}"
        )

        msg = QMessageBox(self)
        msg.setWindowTitle("Template Info")
        msg.setIcon(QMessageBox.Icon.Information)
        msg.setText(info)
        break_btn = msg.addButton("Break into Test Cases", QMessageBox.ButtonRole.ActionRole)
        msg.addButton("Close", QMessageBox.ButtonRole.RejectRole)
        msg.exec()
        if msg.clickedButton() == break_btn:
            self.break_template_into_test_cases(template_name)
    
    def show_template_context_menu(self, position: QPoint):
        """Shows context menu for template tree — works with the new flat widget-row design."""
        item = self.template_tree.itemAt(position)
        if not item:
            return

        # With the new flat design, every item is a top-level template item
        template_name = item.data(0, Qt.ItemDataRole.UserRole)
        if not isinstance(template_name, str):
            return

        menu = QMenu()

        break_action = QAction("🔓 Break into Test Cases", self)
        break_action.triggered.connect(
            lambda: self.break_template_into_test_cases(template_name))
        menu.addAction(break_action)

        menu.addSeparator()

        info_action = QAction("ℹ️ View Info", self)
        info_action.triggered.connect(
            lambda: self.view_template_info(template_name))
        menu.addAction(info_action)

        open_excel_action = QAction("📂 Open Excel File Location", self)
        open_excel_action.triggered.connect(
            lambda: self._export_template_excel(template_name))
        menu.addAction(open_excel_action)

        menu.addSeparator()

        delete_action = QAction(f"🗑️ Delete Template", self)
        delete_action.triggered.connect(
            lambda: self.delete_template(item))
        menu.addAction(delete_action)

        menu.exec(self.template_tree.viewport().mapToGlobal(position))       
    
    def break_template_into_test_cases(self, template_name):
        """Breaks template into individual test cases and adds them to Test Cases Library."""
        template_data = self.templates.get(template_name)
        if not template_data:
            return
        
        # ✅ NEW: Load data from Excel at break time
        excel_path = template_data.get('excel_path')
        sheet_name = template_data.get('sheet_name')
        
        if not os.path.exists(excel_path):
            self._themed_warning("File Not Found", f"Excel file not found: {excel_path}")
            return
        
        try:
            import openpyxl
            wb = openpyxl.load_workbook(excel_path, data_only=True)
            
            if sheet_name not in wb.sheetnames:
                QMessageBox.warning(self, "Sheet Not Found", 
                                  f"Sheet '{sheet_name}' not found in Excel file.")
                return
            
            ws = wb[sheet_name]
            
            # Read field labels from column A (starting from row 7)
            field_labels = []
            row_idx = 7
            while True:
                cell_value = ws.cell(row=row_idx, column=1).value
                if not cell_value:
                    break
                field_labels.append(str(cell_value))
                row_idx += 1
            
            if not field_labels:
                QMessageBox.warning(self, "No Fields", "No field labels found in the Excel file.")
                return
            
            # ✅ NEW: Templates now include a read-only "Sample Data" reference
            # column (column B) showing the source test case's own values, so
            # actual new-test-case data starts at column C. Detect this by
            # checking column B's header — older templates (created before
            # this column existed) don't have it, so we fall back to reading
            # from column B for those, keeping old templates working.
            sample_header = ws.cell(row=6, column=2).value
            has_sample_column = bool(sample_header) and str(sample_header).startswith("Sample Data")
            first_tc_col = 3 if has_sample_column else 2
            
            # Read test case data from columns (starting after the Sample Data column, if present)
            test_cases_list = []
            col_idx = first_tc_col
            
            while True:
                # Check if column has header
                test_case_id = ws.cell(row=6, column=col_idx).value
                if not test_case_id:
                    break
                
                # Read data for this test case column
                row_data = {}
                for field_row_idx, field_label in enumerate(field_labels, 7):
                    cell_value = ws.cell(row=field_row_idx, column=col_idx).value
                    row_data[field_label] = str(cell_value) if cell_value is not None else ""
                
                test_cases_list.append({
                    'test_case_id': str(test_case_id),
                    'data': row_data
                })
                
                col_idx += 1
            
        except Exception as e:
            QMessageBox.critical(self, "Error Reading Excel", 
                               f"Failed to read Excel file:\n\n{str(e)}")
            return
        
        if not test_cases_list:
            QMessageBox.warning(self, "No Data", "No test cases found in this template.")
            return
        
        # Get the base test case
        base_test_case_name = template_data.get('base_test_case')
        if base_test_case_name not in self.test_cases:
            QMessageBox.warning(self, "Base Test Case Not Found", 
                              f"Base test case '{base_test_case_name}' not found in library.")
            return
        
        base_test_case = self.test_cases[base_test_case_name]
        
        # Create individual test cases
        created_count = 0
        for tc_data in test_cases_list:
            new_test_case_id = tc_data['test_case_id']
            
            # Skip if already exists
            if new_test_case_id in self.test_cases:
                continue
            
            # Deep copy the base test case
            new_test_case = copy.deepcopy(base_test_case)
            
            # Update the description
            new_test_case['description'] = f"Generated from template: {template_name}"
            
            # Fill in the field values from the data — covers BOTH Main Step
            # fields and Utility Step fields via the shared labeling helper,
            # so the two can never fall out of sync with how the template
            # was generated.
            field_data = tc_data['data']
            
            for (field_label, step_idx, module_name, field_name, is_utility,
                 container, key) in self._iter_template_data_targets(new_test_case.get('steps') or []):
                if field_label in field_data:
                    container[key] = field_data[field_label]
            
            # Add to test cases library
            self.test_cases[new_test_case_id] = new_test_case
            created_count += 1
        
        # Save and update
        self.save_test_cases_to_file()
        self.update_test_case_tree()
        
        # Ensure Test Cases tab is visible
        test_cases_tab_index = -1
        for i in range(self.libraries_tabs.count()):
            if self.libraries_tabs.tabText(i) == "Test Cases Library":
                test_cases_tab_index = i
                break
        
        if test_cases_tab_index == -1:
            test_cases_tab_index = self.libraries_tabs.addTab(self.test_cases_widget, "Test Cases Library")
            self.setup_tab_close_button(test_cases_tab_index)
            self.tab_states['test_cases'] = True
        
        # Show the Libraries dock if hidden
        if not self.libraries_dock.isVisible():
            self.libraries_dock.setVisible(True)
            self.toggle_libraries_action.setChecked(True)
        
        # Switch to Test Cases tab
        self.libraries_tabs.setCurrentIndex(test_cases_tab_index)
        
        folder = self.test_cases.get(
            next((tc['test_case_id'] for tc in test_cases_list 
                  if tc['test_case_id'] in self.test_cases), None), {}
        ).get('folder', '')

        location_msg = f"Added to folder: '{folder}'" if folder else "Added to: Ungrouped"

        QMessageBox.information(
            self,
            "Success",
            f"Template '{template_name}' broken into test cases.\n\n"
            f"Created {created_count} test case(s) in Test Cases Library.\n"
            f"{location_msg}"
        )
    
    def setup_tab_close_button(self, tab_index):
        """
        Sets up a custom close button for a specific tab.
        """
        tab_bar = self.libraries_tabs.tabBar()
        
        # Create a custom close button
        close_btn = QPushButton("×")
        close_btn.setFixedSize(16, 16)
        close_btn.setStyleSheet("""
            QPushButton {
                border: none;
                background-color: transparent;
                font-weight: bold;
                font-size: 18px;
                color: white;
                padding: 0px;
            }
            QPushButton:hover {
                background-color: rgba(255,255,255,0.3);
                border-radius: 3px;
                color: white;
            }
        """)
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.setToolTip("Close this tab")

        # Connect to close tab functionality - dynamically resolve index at click time
        def make_close_handler(btn):
            def handler():
                for i in range(self.libraries_tabs.count()):
                    if self.libraries_tabs.tabBar().tabButton(i, QTabBar.ButtonPosition.RightSide) is btn:
                        self.close_library_tab(i)
                        return
            return handler

        close_btn.clicked.connect(make_close_handler(close_btn))
        
        # Set the custom button as the tab button
        tab_bar.setTabButton(tab_index, QTabBar.ButtonPosition.RightSide, close_btn)
        
    # In MainWindow class
    def on_test_case_item_double_clicked(self, item, column):
        item_data = item.data(0, Qt.ItemDataRole.UserRole)

        # Folder or root header — toggle expand/collapse
        if isinstance(item_data, dict):
            item.setExpanded(not item.isExpanded())
            return

        # Test case item — item_data is the test case name string
        if not isinstance(item_data, str):
            return

        test_case_id = item_data

        existing_steps = self.test_cases.get(test_case_id, {}).get('steps', [])
        test_case_description = self.test_cases.get(test_case_id, {}).get('description', '')
        test_case_assumptions = self.test_cases.get(test_case_id, {}).get('assumptions', '')
        prerequisites = self.test_cases.get(test_case_id, {}).get('prerequisites', [])
        additional_info_fields = self.test_cases.get(test_case_id, {}).get('additional_info_fields', [])
        additional_info_values = self.test_cases.get(test_case_id, {}).get('additional_info_values', {})

        dialog = EditTestCaseDialog(
            existing_steps,
            self.modules,
            self,
            test_case_id,
            test_case_description,
            test_case_assumptions,
            prerequisites,
            additional_info_fields,
            additional_info_values
        )
        screen = QApplication.primaryScreen().availableGeometry()
        dialog.resize(int(screen.width() * 0.90), int(screen.height() * 0.90))
        result = dialog.exec()
        if result == QDialog.DialogCode.Accepted:
            if hasattr(self, 'update_test_case_tree'):
                self.update_test_case_tree()

            
    def add_step_to_test_case(self, test_case_id, module_name):
        """
        Adds a new step (module) to the specified test case.
        """
        if test_case_id in self.test_cases:
            module_details = self.modules.get(module_name, {})
            new_step = {
                "name": f"Use Screen Module: {module_name}",
                "type": "module_import",
                "module_name": module_name,
                "imported_version": module_details.get('version', ''),
                "imported_date": module_details.get('date', ''),
            }
            self.test_cases[test_case_id]['steps'].append(new_step)
            
            # Refresh the UI to show the new step
            self.update_test_case_tree()
            self.save_test_cases_to_file()
            QMessageBox.information(self, "Updated", f"Added '{module_name}' to test case '{test_case_id}'.")
        else:
            QMessageBox.warning(self, "Error", f"Test case '{test_case_id}' not found.")

