    def _rename_test_case_dialog(self, old_name, item):
        """Rename a test case using an input dialog (replaces editItem for custom widget rows)."""
        new_name, ok = self._styled_input_text("Rename Test Case", "Enter new name:", text=old_name)
        if not ok:
            return
        new_name = new_name.strip()
        if not new_name or new_name == old_name:
            return
        if new_name in self.test_cases:
            QMessageBox.warning(self, "Duplicate Name",
                f"A test case named '{new_name}' already exists.")
            return
        self.test_cases[new_name] = self.test_cases.pop(old_name)
        self.test_cases[new_name]['name'] = new_name
        self.save_test_cases_to_file()
        self.update_test_case_tree()
        self.statusBar().showMessage(f"Renamed to '{new_name}'.", 5000)

    def _styled_input_text(self, title, label, text=""):
        """Same behavior as QInputDialog.getText(), but styles the OK/Cancel
        buttons to match the app's golden-button look instead of the plain
        native ones."""
        dlg = QInputDialog(self)
        dlg.setWindowTitle(title)
        dlg.setLabelText(label)
        dlg.setTextValue(text)
        dlg.setInputMode(QInputDialog.InputMode.TextInput)
        # NOTE: QInputDialog builds its internal QDialogButtonBox lazily
        # (only once it's about to be shown), so findChildren() here would
        # find nothing yet. Set the stylesheet on the dialog itself instead
        # so it cascades down once those children exist. Also use a
        # QDialogButtonBox-scoped selector so it beats the app-wide, less
        # specific "QDialog QPushButton" rule. Only applied for DXC Theme 1;
        # DXC Theme 2 keeps its own native button look.
        if get_active_theme() == "DXC Theme 1":
            dlg.setStyleSheet(get_button_qss().replace("QPushButton", "QDialogButtonBox QPushButton"))
        ok = dlg.exec() == QDialog.DialogCode.Accepted
        return dlg.textValue(), ok

    def _themed_warning(self, title, text, icon=QMessageBox.Icon.Warning):
        """Same behavior as QMessageBox.warning()/information(), but for DXC
        Theme 1 only, gives the OK button the golden-background/black-text
        look instead of the theme's normal navy button. DXC Theme 2 is left
        untouched."""
        box = QMessageBox(icon, title, text, QMessageBox.StandardButton.Ok, self)
        if get_active_theme() == "DXC Theme 1":
            box.setStyleSheet(get_button_qss().replace("QPushButton", "QMessageBox QPushButton"))
        box.exec()

    def _themed_question(self, title, text, icon=QMessageBox.Icon.Question,
                          buttons=QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                          default_button=None):
        """Same behavior as QMessageBox.question(), but for DXC Theme 1 only,
        gives the buttons the golden-background/black-text look. Returns the
        StandardButton the user clicked."""
        box = QMessageBox(icon, title, text, buttons, self)
        if default_button is not None:
            box.setDefaultButton(default_button)
        if get_active_theme() == "DXC Theme 1":
            box.setStyleSheet(get_button_qss().replace("QPushButton", "QMessageBox QPushButton"))
        return box.exec()

    def create_test_case_folder(self, then_move=None):
        """Creates a new folder. If then_move is a list of tc names, moves them in after creation."""
        name, ok = self._styled_input_text("New Folder", "Enter folder name:")
        if not ok:
            return
        name = name.strip()
        if not name:
            QMessageBox.warning(self, "Invalid Name", "Folder name cannot be empty.")
            return
        if name in self.test_case_folders:
            QMessageBox.warning(self, "Already Exists", f"A folder named '{name}' already exists.")
            return
        self.test_case_folders[name] = {'expanded': True}
        self.save_folders_to_file()
        if then_move:
            self.move_test_cases_to_folder(then_move, name)
        else:
            self.update_test_case_tree()
        self.statusBar().showMessage(f"Folder '{name}' created.", 4000)

    def rename_test_case_folder(self, folder_item):
        """Renames a folder and updates all test cases that reference it."""
        item_data = folder_item.data(0, Qt.ItemDataRole.UserRole)
        old_name = item_data['name']
        new_name, ok = self._styled_input_text("Rename Folder", "New folder name:", text=old_name)
        if not ok:
            return
        new_name = new_name.strip()
        if not new_name or new_name == old_name:
            return
        if new_name in self.test_case_folders:
            QMessageBox.warning(self, "Already Exists", f"A folder named '{new_name}' already exists.")
            return
        # Rename in folders dict
        self.test_case_folders[new_name] = self.test_case_folders.pop(old_name)
        # Update all test cases that belong to old folder
        for tc_data in self.test_cases.values():
            if tc_data.get('folder', '') == old_name:
                tc_data['folder'] = new_name
        self.save_folders_to_file()
        self.save_test_cases_to_file()
        self.update_test_case_tree()
        self.statusBar().showMessage(f"Folder renamed to '{new_name}'.", 4000)

    def delete_test_case_folder(self, folder_name, keep_cases=True):
        """Deletes a folder. Optionally keeps or deletes its test cases."""
        cases_in_folder = [n for n, d in self.test_cases.items()
                           if d.get('folder', '') == folder_name]
        if keep_cases:
            msg = (f"Delete folder '{folder_name}'?\n\n"
                   f"The {len(cases_in_folder)} test case(s) inside will be moved to Ungrouped.")
        else:
            msg = (f"Delete folder '{folder_name}' AND all {len(cases_in_folder)} test case(s) inside?\n\n"
                   "This cannot be undone.")
        reply = QMessageBox.question(self, "Confirm Delete", msg,
                                     QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if reply != QMessageBox.StandardButton.Yes:
            return
        if keep_cases:
            for tc_data in self.test_cases.values():
                if tc_data.get('folder', '') == folder_name:
                    tc_data.pop('folder', None)
        else:
            for tc_name in cases_in_folder:
                self.test_cases.pop(tc_name, None)
            self.save_test_cases_to_file()
        self.test_case_folders.pop(folder_name, None)
        self.save_folders_to_file()
        self.save_test_cases_to_file()
        self.update_test_case_tree()
        self.statusBar().showMessage(f"Folder '{folder_name}' deleted.", 4000)

    def move_test_cases_to_folder(self, tc_names, folder_name):
        """Moves a list of test cases into a folder (pass '' to ungrouped)."""
        for name in tc_names:
            if name in self.test_cases:
                if folder_name:
                    self.test_cases[name]['folder'] = folder_name
                else:
                    self.test_cases[name].pop('folder', None)
        self.save_test_cases_to_file()
        self.update_test_case_tree()
        if folder_name:
            self.statusBar().showMessage(
                f"Moved {len(tc_names)} test case(s) to folder '{folder_name}'.", 4000)
        else:
            self.statusBar().showMessage(
                f"Moved {len(tc_names)} test case(s) to Ungrouped.", 4000)

    def import_test_cases_into_folder(self, folder_name):
        """Opens file dialog to import JSON test case files directly into a folder."""
        options = QFileDialog.Option.ReadOnly
        file_paths, _ = QFileDialog.getOpenFileNames(
            self, f"Import Test Cases into '{folder_name}'", "",
            "JSON Files (*.json);;All Files (*)", options=options)
        if not file_paths:
            return
        imported = 0
        for file_path in file_paths:
            try:
                with open(file_path, 'r') as f:
                    data = json.load(f)
                # Support both single-tc file (has 'name' key) and multi-tc dict
                if 'name' in data:
                    tc_name = data.pop('name')
                    data['folder'] = folder_name
                    self.test_cases[tc_name] = data
                    imported += 1
                elif isinstance(data, dict):
                    for tc_name, tc_data in data.items():
                        tc_data['folder'] = folder_name
                        self.test_cases[tc_name] = tc_data
                        imported += 1
            except Exception as e:
                QMessageBox.warning(self, "Import Error", f"Could not import '{file_path}':\n{e}")
        if imported:
            self.save_test_cases_to_file()
            self.update_test_case_tree()
            self.statusBar().showMessage(
                f"Imported {imported} test case(s) into folder '{folder_name}'.", 5000)
    
    def add_multiple_test_cases_to_execution(self, test_case_names):
        """Adds multiple selected test cases to Test Execution."""
        if not test_case_names:
            return

        execution_data_file = os.path.join(get_appdata_dir(), 'test_execution_data.json')

        try:
            if os.path.exists(execution_data_file):
                with open(execution_data_file, 'r') as f:
                    execution_data = json.load(f)
            else:
                execution_data = {'projects': {}, 'standalone': {}}

            added = []
            skipped = []
            already_in = []
            for name in test_case_names:
                if name not in self.test_cases:
                    skipped.append(name)
                    continue
                # Check if already in execution
                in_standalone = name in execution_data.get('standalone', {})
                in_project = any(
                    name in pd.get('test_cases', {})
                    for pd in execution_data.get('projects', {}).values()
                )
                if in_standalone or in_project:
                    already_in.append(name)
                    continue
                execution_data['standalone'][name] = {
                    'status': 'Not Run',
                    'selected_step': 0,
                    'test_case_data': copy.deepcopy(self.test_cases[name])
                }
                added.append(name)

            # ← INSERT HERE — after loop, before save
            if already_in and not added:
                QMessageBox.warning(self, "Already in Test Execution",
                    f"All selected test case(s) are already in Test Execution:\n\n"
                    + "\n".join(f"  • {n}" for n in already_in))
                return
            if already_in:
                skipped.extend(already_in)

            with open(execution_data_file, 'w') as f:
                json.dump(execution_data, f, indent=4)

            self.statusBar().showMessage(f"{len(added)} test case(s) added to Test Execution.", 5000)

            msg_box = QMessageBox(self)
            msg_box.setWindowTitle("Added to Test Execution")
            msg_box.setIcon(QMessageBox.Icon.Information)
            msg_box.setText(f"<b>{len(added)} test case(s)</b> added to Test Execution.")
            info = "You can open Test Execution now or continue working."
            if skipped:
                info += f"\n\nSkipped (not found): {', '.join(skipped)}"
            msg_box.setInformativeText(info)
            open_btn = msg_box.addButton("Open Test Execution", QMessageBox.ButtonRole.AcceptRole)
            msg_box.addButton("Close", QMessageBox.ButtonRole.RejectRole)
            if get_active_theme() == "DXC Theme 1":
                msg_box.setStyleSheet(get_button_qss().replace("QPushButton", "QMessageBox QPushButton"))
            msg_box.exec()
            if msg_box.clickedButton() == open_btn:
                self.test_execution()

        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to add test cases to execution:\n\n{str(e)}")
   
    
    def add_test_case_to_execution(self, test_case_name):
        """
        Adds the selected test case to Test Execution as a standalone test (without opening the dialog).
        """
        if test_case_name not in self.test_cases:
            QMessageBox.warning(self, "Test Case Not Found", 
                              f"Test case '{test_case_name}' not found in library.")
            return
        
        # Load existing execution data
        execution_data_file = os.path.join(get_appdata_dir(), 'test_execution_data.json')
        
        try:
            if os.path.exists(execution_data_file):
                with open(execution_data_file, 'r') as f:
                    execution_data = json.load(f)
            else:
                execution_data = {
                    'projects': {},
                    'standalone': {}
                }
            
            # Get test case data and add it as standalone
            # Check if already in execution (standalone or any project)
            already_exists = test_case_name in execution_data.get('standalone', {})
            if not already_exists:
                for project_data in execution_data.get('projects', {}).values():
                    if test_case_name in project_data.get('test_cases', {}):
                        already_exists = True
                        break

            if already_exists:
                msg_box = QMessageBox(self)
                msg_box.setWindowTitle("Already in Test Execution")
                msg_box.setIcon(QMessageBox.Icon.Warning)
                msg_box.setText(f"<b>'{test_case_name}'</b> is already in Test Execution.")
                msg_box.setInformativeText("Do you want to re-add it and reset its status to 'Not Run'?")
                yes_btn = msg_box.addButton("Re-add", QMessageBox.ButtonRole.AcceptRole)
                open_btn = msg_box.addButton("Open Test Execution", QMessageBox.ButtonRole.ActionRole)
                msg_box.addButton("Cancel", QMessageBox.ButtonRole.RejectRole)
                msg_box.exec()
                clicked = msg_box.clickedButton()
                if clicked == open_btn:
                    self.test_execution()
                    return
                elif clicked != yes_btn:
                    return

            # Get test case data and add it as standalone
            test_case_data = copy.deepcopy(self.test_cases[test_case_name])

            # Add to standalone section
            execution_data['standalone'][test_case_name] = {
                'status': 'Not Run',
                'selected_step': 0,
                'test_case_data': test_case_data
            }

            # Save back to file
            with open(execution_data_file, 'w') as f:
                json.dump(execution_data, f, indent=4)
            
            # Show success message
            self.statusBar().showMessage(f"Test case '{test_case_name}' added to Test Execution.", 5000)

            msg = QMessageBox(self)
            msg.setWindowTitle("Added to Test Execution")
            msg.setIcon(QMessageBox.Icon.Information)
            msg.setText(f"<b>'{test_case_name}'</b> has been added to Test Execution.")
            msg.setInformativeText("You can open Test Execution now or continue working.")
            open_btn = msg.addButton("Open Test Execution", QMessageBox.ButtonRole.AcceptRole)
            msg.addButton("Close", QMessageBox.ButtonRole.RejectRole)
            if get_active_theme() == "DXC Theme 1":
                msg.setStyleSheet(get_button_qss().replace("QPushButton", "QMessageBox QPushButton"))
            msg.exec()
            if msg.clickedButton() == open_btn:
                self.test_execution()
            
        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to add test case to execution:\n\n{str(e)}")    
    
    def add_new_step(self, test_case_item: QTreeWidgetItem):
        """
        Adds a new step under the selected test case with a dropdown
        of available modules.
        """
        test_case_name = test_case_item.text(0)
        step_item = QTreeWidgetItem(test_case_item, ["New Step"])
        
        # Create a widget to hold the QComboBox and a line edit for the name
        widget = QWidget()
        layout = QHBoxLayout(widget)
        layout.setContentsMargins(0, 0, 0, 0)
        
        # Dropdown to select modules
        module_combo = QComboBox()
        module_combo.addItem("Select Module...")
        for module_name in self.modules.keys():
            module_combo.addItem(module_name)
        
        module_combo.currentIndexChanged.connect(lambda index: self.save_step_module(test_case_item, step_item, index))
        
        layout.addWidget(module_combo)
        
        step_item.setSizeHint(0, QSize(150, 25))
        self.test_case_tree.setItemWidget(step_item, 0, widget)

        # Update the data structure and save
        step_data = {"module_name": None}
        self.test_cases[test_case_name]["steps"].append(step_data)
        self.save_test_cases_to_file()
        self.statusBar().showMessage(f"New step added to test case '{test_case_name}'.", 5000)

    def save_step_module(self, test_case_item: QTreeWidgetItem, step_item: QTreeWidgetItem, index: int):
        """
        Saves the selected module name for a step.
        """
        test_case_name = test_case_item.text(0)
        step_index = test_case_item.indexOfChild(step_item)
        
        if test_case_name in self.test_cases and step_index >= 0 and index > 0:
            module_name = self.test_case_tree.itemWidget(step_item, 0).findChild(QComboBox).currentText()
            self.test_cases[test_case_name]["steps"][step_index]["module_name"] = module_name
            step_item.setText(0, f"Step {step_index + 1}: {module_name}")
            self.save_test_cases_to_file()

    def test_cases_library(self):
        """
        Handles the 'Test cases Library' button click.
        Toggles the visibility of the Test Cases dock and the PCOMM preview.
        This method is simplified as there is no step addition process now.
        """
        is_visible = not self.test_cases_deck.isVisible()
        self.test_cases_deck.setVisible(is_visible)
        self.central_frame.setVisible(not is_visible)
        self.toggle_test_cases_action.setChecked(is_visible)


