        info_layout.addLayout(info_row("Purpose",    "Automated testing for mainframe\nand terminal-based applications"))
        info_layout.addLayout(info_row("Data Store", "%APPDATA%\\InstaRun\\"))

        info_layout.addSpacing(8)

