    def toggle_toolbar_visibility(self):
        """Toggles the visibility of the main toolbar."""
        toolbar = self.findChild(QToolBar, "main_toolbar")
        if toolbar:
            self.toolbar_visible = not self.toolbar_visible
            toolbar.setVisible(self.toolbar_visible)
            self.toggle_toolbar_action.setChecked(self.toolbar_visible)
            
            # Update the status message
            status_msg = "Toolbar shown" if self.toolbar_visible else "Toolbar hidden"
            self.statusBar().showMessage(status_msg, 3000)

    def show_context_menu(self, position: QPoint):
        item = self.module_tree.itemAt(position)
        if not item or not isinstance(item.data(0, Qt.ItemDataRole.UserRole), str):
            return

        menu = QMenu()
        selected_items = self.module_tree.selectedItems()
        selected_module_names = [
            i.data(0, Qt.ItemDataRole.UserRole)
            for i in selected_items
            if isinstance(i.data(0, Qt.ItemDataRole.UserRole), str)
        ]
        if not selected_module_names:
            selected_module_names = [item.data(0, Qt.ItemDataRole.UserRole)]

        single_selection = len(selected_module_names) == 1

        if single_selection:
            rename_action = QAction("✏️ Rename", self)
            rename_action.triggered.connect(
                lambda: self._rename_module_dialog(item.data(0, Qt.ItemDataRole.UserRole), item))
            menu.addAction(rename_action)

            show_sysid_action = QAction("🆔 Show sysid", self)
            show_sysid_action.triggered.connect(
                lambda: self._show_module_sys_id(selected_module_names[0]))
            menu.addAction(show_sysid_action)

            show_json_action = QAction("🧾 Show JSON", self)
            show_json_action.triggered.connect(
                lambda: self._show_module_json(selected_module_names[0]))
            menu.addAction(show_json_action)

            detect_changes_action = QAction("🔍 Detect Changes", self)
            detect_changes_action.triggered.connect(
                lambda: self.detect_module_changes(selected_module_names[0]))
            menu.addAction(detect_changes_action)

            menu.addSeparator()

        delete_action = QAction(
            f"🗑️ Delete Module{'s' if not single_selection else ''}  ({len(selected_module_names)})", self)
        delete_action.triggered.connect(lambda: self.delete_selected_modules())
        menu.addAction(delete_action)

        menu.addSeparator()

        export_selected_action = QAction(
            f"📤 Export Selected Module{'s' if not single_selection else ''}  ({len(selected_module_names)})", self)
        export_selected_action.triggered.connect(
            lambda: self.export_selected_modules(selected_module_names))
        menu.addAction(export_selected_action)

        menu.exec(self.module_tree.viewport().mapToGlobal(position))
    
    
    def scan_pcomm_screen(self):
        """
        Scans the PCOMM screen, extracts text, creates a new module, and
        displays the captured text and screenshot in the preview window.
        """
        # --- NEW: Ask for the screen name (used as the module name) and
        # version first; the capture date is picked automatically from
        # today's calendar date. ---
        default_screen_name = f"Module_{self.module_counter}"
        module_name = None
        module_version = None
        module_date = None
        while True:
            version_dialog = ModuleVersionDialog(self, default_screen_name=default_screen_name)
            if version_dialog.exec() != QDialog.DialogCode.Accepted:
                return
            candidate_name = version_dialog.get_screen_name()
            if candidate_name in self.modules:
                QMessageBox.warning(self, "Duplicate Screen Name",
                    f"A module named '{candidate_name}' already exists.\nPlease enter a different screen name.")
                default_screen_name = candidate_name
                continue
            module_name = candidate_name
            module_version = version_dialog.get_version()
            module_date = version_dialog.get_date()
            break

        try:
            # --- NEW: Hide the test cases dock before scanning ---
          
            pcomm_window = gw.getWindowsWithTitle(self.pcomm_window_title)[0]
            
            # Use Win32 API's PrintWindow for a more reliable capture
            hwnd = pcomm_window._hWnd
            left, top, right, bottom = win32gui.GetWindowRect(hwnd)
            w = right - left
            h = bottom - top

            # Get the device context and create a compatible one
            hwnd_dc = win32gui.GetWindowDC(hwnd)
            mfc_dc = win32ui.CreateDCFromHandle(hwnd_dc)
            save_dc = mfc_dc.CreateCompatibleDC()

            # Create a bitmap to hold the image
            save_bitmap = win32ui.CreateBitmap()
            save_bitmap.CreateCompatibleBitmap(mfc_dc, w, h)
            save_dc.SelectObject(save_bitmap)
            
            # --- The key step: Use PrintWindow to get a reliable screenshot ---
            # Try to use PW_CLIENTONLY, but fall back to 0 if it's not defined
            try:
                flag = win32con.PW_CLIENTONLY
            except AttributeError:
                # Fallback to 0 if PW_CLIENTONLY is not found
                print("win32con.PW_CLIENTONLY not found, falling back to 0.")
                flag = 0
                
            result = windll.user32.PrintWindow(hwnd, save_dc.GetSafeHdc(), flag)

            if result != 1:
                raise Exception("Failed to capture window with PrintWindow.")
                
            # Convert the bitmap to a Pillow Image
            bmpinfo = save_bitmap.GetInfo()
            bmpstr = save_bitmap.GetBitmapBits(True)
            im = Image.frombuffer(
                'RGB',
                (bmpinfo['bmWidth'], bmpinfo['bmHeight']),
                bmpstr, 'raw', 'BGRX', 0, 1
            )
            
            # Clean up the device contexts and bitmap
            win32gui.DeleteObject(save_bitmap.GetHandle())
            save_dc.DeleteDC()
            mfc_dc.DeleteDC()
            win32gui.ReleaseDC(hwnd, hwnd_dc)

            # --- Capture Text for basic overview ---
            pcomm_window.activate()
            time.sleep(0.5)
            
            # Clear clipboard FIRST so stale content from a previous scan cannot sneak in
            try:
                pyperclip.copy("")
            except Exception:
                pass
            
            pyautogui.hotkey('ctrl', 'c')
            time.sleep(0.5)
            
            copied_text = ""
            for _attempt in range(10):
                try:
                    candidate = pyperclip.paste()
                    if candidate and candidate.strip():   # only accept non-empty, fresh content
                        copied_text = candidate
                        break
                except Exception:
                    pass
                time.sleep(0.2)
            
            if not copied_text.strip():
                raise Exception(
                    "Could not capture text from PCOMM screen.\n"
                    "Please make sure the PCOMM window is active and try again."
                )

            # Process the text and screenshot to identify fields and create a new module
            # (module_name was already chosen via the ModuleVersionDialog above)
            
            # Use the new visual processing method
            module_data = self.process_pcomm_screen_from_text(copied_text)
            
            # Add other necessary data
            screenshot_dir = os.path.join(get_appdata_dir(), 'Modules Screenshots')
            module_data["screenshot"] = os.path.join(screenshot_dir, f"{module_name}.png")
            module_data["captured_text"] = copied_text # Store the raw text for later display
            module_data["version"] = module_version
            module_data["date"] = module_date

            # Create the directory if it doesn't exist
            os.makedirs(screenshot_dir, exist_ok=True)

            # Save the image
            im.save(module_data["screenshot"])
            
            self.modules[module_name] = module_data
            self.module_counter += 1
            self.save_modules_to_file()
            self.update_module_tree()
            self.statusBar().showMessage(f"Scanned screen and created new module: {module_name} (v{module_version}, {module_date})", 5000)

            # Update the central PCOMM preview canvas to show the text
            self.display_text_in_preview(copied_text)
            
            # --- NEW: Ensure the PCOMM preview is visible when a scan is performed ---
            self.central_frame.setVisible(True)
            self.toggle_pcomm_preview_action.setChecked(True)

        except IndexError:
            QMessageBox.warning(self, "Error", f"PCOMM window with title '{self.pcomm_window_title}' not found.")
        except Exception as e:
            QMessageBox.critical(self, "Error", str(e))

    def _capture_live_pcomm_text(self):
        """
        Activates the PCOMM window and grabs its current screen text via
        clipboard copy (Ctrl+C) - the same clipboard mechanism used by
        scan_pcomm_screen, but without the screenshot step, since
        'Detect Changes' only needs the text to diff against a module.
        Raises Exception with a user-facing message on failure.
        """
        pcomm_windows = gw.getWindowsWithTitle(self.pcomm_window_title)
        if not pcomm_windows:
            raise Exception(f"PCOMM window with title '{self.pcomm_window_title}' not found.")
        pcomm_window = pcomm_windows[0]

        pcomm_window.activate()
        time.sleep(0.5)

        # Clear clipboard FIRST so stale content from a previous scan cannot sneak in
        try:
            pyperclip.copy("")
        except Exception:
            pass

        pyautogui.hotkey('ctrl', 'c')
        time.sleep(0.5)

        live_text = ""
        for _attempt in range(10):
            try:
                candidate = pyperclip.paste()
                if candidate and candidate.strip():
                    live_text = candidate
                    break
            except Exception:
                pass
            time.sleep(0.2)

        if not live_text.strip():
            raise Exception(
                "Could not capture text from PCOMM screen.\n"
                "Please make sure the PCOMM window is active and try again."
            )

        return live_text

    def _show_screen_diff_dialog(self, module_name, stored_lines, live_lines, changed_row_indices):
        """
        Notepad++-style side-by-side compare view for 'Detect Changes':
        the module's stored screen on the left, the live PCOMM screen on
        the right, scrolled together, with every row that differs
        highlighted on both sides so it's easy to spot at a glance.

        Sized to fit the full PCOMM screen (both rows and columns) by
        default, so no scrolling is needed for a normal-sized screen -
        the scrollbars are still there for the rare case the content
        genuinely doesn't fit on the user's monitor.
        """
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Detect Changes - {module_name}")

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(14, 14, 14, 12)
        layout.setSpacing(8)

        summary_label = QLabel(
            f"{len(changed_row_indices)} row(s) differ between the module and the live PCOMM screen."
            if changed_row_indices else
            "No changes detected - the module still matches the live PCOMM screen."
        )
        layout.addWidget(summary_label)

        header_layout = QHBoxLayout()
        left_header = QLabel(f"📁  Module (stored):  {module_name}")
        right_header = QLabel("🖥️  Live PCOMM Screen")
        left_header.setStyleSheet("font-weight: bold;")
        right_header.setStyleSheet("font-weight: bold;")
        header_layout.addWidget(left_header)
        header_layout.addWidget(right_header)
        layout.addLayout(header_layout)

        splitter = QSplitter(Qt.Orientation.Horizontal, dialog)

        mono_font = QFont("Consolas")
        mono_font.setStyleHint(QFont.StyleHint.Monospace)

        left_edit = QPlainTextEdit()
        right_edit = QPlainTextEdit()
        for edit in (left_edit, right_edit):
            edit.setReadOnly(True)
            edit.setFont(mono_font)
            edit.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)
            edit.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)

        left_edit.setPlainText('\n'.join(stored_lines))
        right_edit.setPlainText('\n'.join(live_lines))

        def _highlight_rows(edit, row_indices):
            extra_selections = []
            for i in row_indices:
                block = edit.document().findBlockByNumber(i)
                if not block.isValid():
                    continue
                selection = QTextEdit.ExtraSelection()
                selection.format.setBackground(QColor("#ffe08a"))
                selection.format.setProperty(QTextFormat.Property.FullWidthSelection, True)
                cursor = QTextCursor(block)
                cursor.clearSelection()
                selection.cursor = cursor
                extra_selections.append(selection)
            edit.setExtraSelections(extra_selections)

        _highlight_rows(left_edit, changed_row_indices)
        _highlight_rows(right_edit, changed_row_indices)

        splitter.addWidget(left_edit)
        splitter.addWidget(right_edit)
        splitter.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        # Give the splitter (the actual text panes) all the extra space -
        # the labels above should stay their natural, compact size.
        layout.addWidget(splitter, 1)

        # Keep both panes scrolling together, like a real compare tool
        left_edit.verticalScrollBar().valueChanged.connect(right_edit.verticalScrollBar().setValue)
        right_edit.verticalScrollBar().valueChanged.connect(left_edit.verticalScrollBar().setValue)
        left_edit.horizontalScrollBar().valueChanged.connect(right_edit.horizontalScrollBar().setValue)
        right_edit.horizontalScrollBar().valueChanged.connect(left_edit.horizontalScrollBar().setValue)

        button_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok, dialog)
        button_box.accepted.connect(dialog.accept)
        button_box.setStyleSheet(get_button_qss())
        layout.addWidget(button_box)

        dialog.setLayout(layout)

        # --- Size the dialog so the whole screen (all rows/columns) is
        # visible without scrolling, where the screen allows for it. ---
        metrics = QFontMetrics(mono_font)
        char_width = metrics.horizontalAdvance('W')
        line_height = metrics.height()
        max_cols = max([len(l) for l in stored_lines] + [len(l) for l in live_lines] + [1])
        num_rows = max(len(stored_lines), len(live_lines))

        pane_width = max_cols * char_width + 40           # + scrollbar/margins
        pane_height = num_rows * line_height + 40
        splitter.setSizes([pane_width, pane_width])

        wanted_width = pane_width * 2 + 60                # two panes + splitter handle/margins
        wanted_height = pane_height + 140                 # labels + button row + margins

        screen = QApplication.primaryScreen()
        available = screen.availableGeometry() if screen else None
        if available is not None:
            max_width = int(available.width() * 0.95)
            max_height = int(available.height() * 0.9)
        else:
            max_width, max_height = 1600, 1000

        dialog_width = max(700, min(wanted_width, max_width))
        dialog_height = max(400, min(wanted_height, max_height))
        dialog.resize(dialog_width, dialog_height)

        dialog.exec()

    def detect_module_changes(self, module_name):
        """
        'Detect Changes' (right-click on a module -> Detect Changes).

        Compares the module's stored ACTUAL SCREEN TEXT against whatever
        is CURRENTLY on the live PCOMM screen, line by line, character
        for character - not the parsed labels/fields. Label names can be
        renamed/edited by a user after capture, so they're not a
        trustworthy signal of what's really on the mainframe screen; the
        raw text captured at scan time is.

        The only thing excluded from the comparison is each field itself
        - the spot where the user typed the red 'aaaaaa' marker at
        capture time. Those exact (row, column, length) spots are already
        recorded in the module's 'labels' (from process_pcomm_screen_from_text),
        so they're blanked out on BOTH the stored text and the live text
        by POSITION, regardless of what characters currently sit there.

        This is deliberately position-based rather than re-matching an
        'a+' pattern on the live screen: by the time you're comparing
        against a live screen, those fields are filled with real data
        (not literal 'a's), so a content-based mask would only ever
        match on the stored side and falsely flag every field as changed.

        Results are shown in a Notepad++-style side-by-side compare
        dialog: the stored module on the left, the live screen on the
        right (both showing the REAL, unmasked text), with every row
        that differs highlighted on both sides.
        """
        module_data = self.modules.get(module_name)
        if not isinstance(module_data, dict):
            QMessageBox.warning(self, "Module Not Found", f"Module '{module_name}' could not be found.")
            return

        stored_text = module_data.get('captured_text', '')
        if not stored_text.strip():
            QMessageBox.warning(
                self, "No Captured Text",
                f"Module '{module_name}' has no stored screen text to compare against."
            )
            return

        try:
            live_text = self._capture_live_pcomm_text()
        except Exception as e:
            QMessageBox.critical(self, "Error", str(e))
            return

        field_positions = module_data.get('labels', [])

        def _mask_known_fields(lines):
            masked = list(lines)
            for lbl in field_positions:
                row = lbl.get('row')
                col = lbl.get('column')
                length = lbl.get('length')
                if not row or not col or not length:
                    continue
                r = row - 1
                c0 = col - 1
                c1 = c0 + length
                if r < 0 or r >= len(masked) or c0 < 0:
                    continue
                line = masked[r]
                if len(line) < c1:
                    line = line + (' ' * (c1 - len(line)))
                masked[r] = line[:c0] + ('#' * (c1 - c0)) + line[c1:]
            return masked

        stored_raw_lines = stored_text.split('\n')
        live_raw_lines = live_text.split('\n')

        # Pad both raw line lists to the same length so left/right rows
        # line up 1-for-1 in the side-by-side view.
        max_len = max(len(stored_raw_lines), len(live_raw_lines))
        stored_raw_lines += [''] * (max_len - len(stored_raw_lines))
        live_raw_lines += [''] * (max_len - len(live_raw_lines))

        masked_stored_lines = _mask_known_fields(stored_raw_lines)
        masked_live_lines = _mask_known_fields(live_raw_lines)

        changed_row_indices = [
            i for i in range(max_len)
            if masked_stored_lines[i].rstrip() != masked_live_lines[i].rstrip()
        ]

        self._show_screen_diff_dialog(module_name, stored_raw_lines, live_raw_lines, changed_row_indices)

