    def export_full_backup(self):
        """Exports a full backup of all data as a zip file."""
        from datetime import datetime
        import zipfile
        import shutil

        timestamp = datetime.now().strftime('%Y-%m-%d_%H-%M-%S')
        default_name = f"InstaRun_Backup_{timestamp}.zip"

        file_path, _ = QFileDialog.getSaveFileName(
            self, "Export Full Backup",
            default_name,
            "ZIP Files (*.zip);;All Files (*)"
        )
        if not file_path:
            return

        data_dir = get_appdata_dir()
        files_to_backup = [
            self.module_file,
            self.test_case_file,
            self.template_file,
            self.document_config_file,
            self.masking_config_file,
            self.default_results_location_file,
            os.path.join(data_dir, 'pcomm_config.json'),
            os.path.join(data_dir, 'execution_run_log.json'),
            os.path.join(data_dir, 'test_execution_data.json'),
        ]

        try:
            included = []
            with zipfile.ZipFile(file_path, 'w', zipfile.ZIP_DEFLATED) as zf:
                # Add JSON config files
                for f in files_to_backup:
                    if os.path.exists(f):
                        zf.write(f, os.path.basename(f))
                        included.append(os.path.basename(f))

                # Add Modules Screenshots folder
                screenshots_dir = os.path.join(get_appdata_dir(), 'Modules Screenshots')
                if os.path.exists(screenshots_dir):
                    screenshot_files = [
                        fname for fname in os.listdir(screenshots_dir)
                        if os.path.isfile(os.path.join(screenshots_dir, fname))
                    ]
                    for fname in screenshot_files:
                        fpath = os.path.join(screenshots_dir, fname)
                        zf.write(fpath, os.path.join('Modules Screenshots', fname))
                    if screenshot_files:
                        included.append(f'Modules Screenshots/ ({len(screenshot_files)} image(s))')

            QMessageBox.information(self, "Backup Successful",
                f"Full backup saved to:\n{file_path}\n\n"
                f"Files included ({len(included)}):\n" + "\n".join(f"  • {f}" for f in included) +
                f"\n\nTo restore: unzip into %APPDATA%\\InstaRun\\")
        except Exception as e:
            QMessageBox.critical(self, "Backup Failed", f"Could not create backup:\n{e}")


    def import_modules(self):
        """
        Prompts the user to select one or more JSON files and imports the modules
        into the current project.
        """
        file_dialog = QFileDialog()
        file_paths, _ = file_dialog.getOpenFileNames(
            self,
            "Import Modules",
            "",
            "JSON Files (*.json);;All Files (*)"
        )
        
        if file_paths:
            skipped_modules = []
            
            for file_path in file_paths:
                try:
                    with open(file_path, 'r') as f:
                        imported_modules = json.load(f)
                    
                    # Merge the imported modules with the existing ones
                    for name, data in imported_modules.items():
                        if name in self.modules:
                            skipped_modules.append(name)
                        else:
                            self.modules[name] = data
                
                except Exception as e:
                    QMessageBox.critical(self, "Import Error", f"An error occurred while importing the file '{file_path}': {e}")
            
            # Update the module counter to be the largest number plus one
            numeric_modules = [int(re.search(r'\d+', key).group()) for key in self.modules.keys() if re.search(r'\d+', key)]
            self.module_counter = max(numeric_modules) + 1 if numeric_modules else 0
                    
            self.save_modules_to_file()
            self.update_module_tree()
            
            if skipped_modules:
                message = (f"Successfully imported modules. The following modules were skipped due to name conflicts: "
                           f"{', '.join(skipped_modules)}")
                QMessageBox.warning(self, "Import Warning", message)
            else:
                self.statusBar().showMessage("Successfully imported modules.", 5000)

    def delete_module(self, item):
        """
        Deletes the selected module from the tree, the internal data, and the screenshot file.
        """
        module_name_to_delete = item.data(0, Qt.ItemDataRole.UserRole)
        
        # Confirm deletion with the user
        reply = self._themed_question(
            'Delete Module',
            f"Are you sure you want to delete the module '{module_name_to_delete}'?",
            QMessageBox.Icon.Question,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        
        if reply == QMessageBox.StandardButton.Yes:
            if module_name_to_delete in self.modules:
                # Delete the associated screenshot file
                screenshot_path = self.modules[module_name_to_delete].get("screenshot")
                if screenshot_path and os.path.exists(screenshot_path):
                    try:
                        os.remove(screenshot_path)
                    except Exception as e:
                        print(f"Error deleting screenshot file: {e}")

                del self.modules[module_name_to_delete]
                self.save_modules_to_file()
                self.update_module_tree()
                self.labels_table.setRowCount(0)
                self.properties_tree.clear()
                self.pcomm_canvas_text_edit.setHtml(self._get_pcomm_placeholder_html())

                self.statusBar().showMessage(f"Module '{module_name_to_delete}' deleted.", 5000)
                
    def delete_selected_modules(self):
        selected_items = self.module_tree.selectedItems()
        module_items = [
            item for item in selected_items
            if isinstance(item.data(0, Qt.ItemDataRole.UserRole), str)
        ]
        if not module_items:
            self._themed_warning("No Selection", "Please select at least one module to delete.")
            return
        module_names = [item.data(0, Qt.ItemDataRole.UserRole) for item in module_items]
        module_word = "module" if len(module_names) == 1 else "modules"
        reply = self._themed_question(
            'Delete Modules',
            f"Are you sure you want to delete {len(module_names)} {module_word}?\n\n{', '.join(module_names)}",
            QMessageBox.Icon.Question,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        if reply == QMessageBox.StandardButton.Yes:
            for module_name in module_names:
                if module_name in self.modules:
                    screenshot_path = self.modules[module_name].get("screenshot")
                    if screenshot_path and os.path.exists(screenshot_path):
                        try:
                            os.remove(screenshot_path)
                        except Exception as e:
                            print(f"Error deleting screenshot file: {e}")
                    del self.modules[module_name]
            self.save_modules_to_file()
            self.update_module_tree()
            self.labels_table.setRowCount(0)
            self.properties_tree.clear()
            self.pcomm_canvas_text_edit.setHtml(self._get_pcomm_placeholder_html())
            self.statusBar().showMessage(f"{len(module_names)} {module_word} deleted.", 5000)
        
        
    def delete_selected_test_cases(self):
        """Deletes all selected test cases from the tree."""
        selected_items = self.test_case_tree.selectedItems()
        
        # Filter out the root item and get only test case items
        test_case_items = [item for item in selected_items if isinstance(item.data(0, Qt.ItemDataRole.UserRole), str)]
        
        if not test_case_items:
            self._themed_warning("No Selection", "Please select at least one test case to delete.")
            return
        
        test_case_names = [item.data(0, Qt.ItemDataRole.UserRole) for item in test_case_items]
        
        # Confirm deletion
        test_word = "test case" if len(test_case_names) == 1 else "test cases"
        reply = self._themed_question(
            'Delete Test Cases',
            f"Are you sure you want to delete {len(test_case_names)} {test_word}?\n\n{', '.join(test_case_names)}",
            QMessageBox.Icon.Question,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        
        if reply == QMessageBox.StandardButton.Yes:
            for test_case_name in test_case_names:
                if test_case_name in self.test_cases:
                    del self.test_cases[test_case_name]
            
            self.save_test_cases_to_file()
            self.update_test_case_tree()
            self.statusBar().showMessage(f"{len(test_case_names)} {test_word} deleted.", 5000)                

    def _bold_selected_tree_item(self, item, column):
        """Makes the selected item bold and resets all siblings to normal."""
        tree = item.treeWidget()
        root = tree.invisibleRootItem()
        for i in range(root.childCount()):
            parent = root.child(i)
            for j in range(parent.childCount()):
                child = parent.child(j)
                f = child.font(0)
                f.setBold(False)
                child.setFont(0, f)
            f = parent.font(0)
            f.setBold(False)
            parent.setFont(0, f)
        f = item.font(0)
        f.setBold(True)
        item.setFont(0, f)

    def display_module_details_and_screenshot(self, item, column):
        self.labels_table.setRowCount(0)
        self.properties_tree.clear()

        module_name = item.data(0, Qt.ItemDataRole.UserRole)

        # If no valid module name, show placeholder and return
        if not isinstance(module_name, str) or module_name not in self.modules:
            self.pcomm_canvas_text_edit.setHtml(self._get_pcomm_placeholder_html())
            self.central_frame.setVisible(True)
            self.toggle_pcomm_preview_action.setChecked(True)
            return

        self._current_module_item = item  # ← THE FIX

        module_data = self.modules.get(module_name)
        if module_data:
            captured_text = module_data.get('captured_text', "No captured text found.")
            if isinstance(self.centralWidget(), QFrame):
                self.display_text_in_preview(captured_text)
                self.central_frame.setVisible(True)
                self.toggle_pcomm_preview_action.setChecked(True)

            if 'labels' in module_data:
                self.labels_table.setRowCount(len(module_data['labels']))
                for i, label in enumerate(module_data['labels']):
                    name_item = QTableWidgetItem(label.get('name', ''))
                    row_item = QTableWidgetItem(str(label.get('row', '')))
                    col_item = QTableWidgetItem(str(label.get('column', '')))
                    length_item = QTableWidgetItem(str(label.get('length', '')))

                    for _item in (name_item, row_item, col_item, length_item):
                        _item.setForeground(QColor(theme_color('primary_color', get_active_theme())))

                    # Tag chip (if this field has been tagged via right-click)
                    # — drawn by FieldNameChipDelegate right after the name,
                    # in the same "Field Name" column, instead of a separate
                    # Tag column.
                    tag_values = get_label_tags(label)
                    if tag_values:
                        name_item.setData(FIELD_TAG_ROLE, tag_values)
                        _tv_label = "Tags" if len(tag_values) > 1 else "Tag"
                        name_item.setToolTip(f"{_tv_label}: {', '.join(tag_values)}")

                    self.labels_table.setItem(i, 0, name_item)
                    self.labels_table.setItem(i, 1, row_item)
                    self.labels_table.setItem(i, 2, col_item)
                    self.labels_table.setItem(i, 3, length_item)

                    delete_label_button = QPushButton()
                    bin_icon = QIcon(resource_path("bin.png"))
                    delete_label_button.setIcon(bin_icon)
                    delete_label_button.setIconSize(QSize(16, 16))
                    delete_label_button.setFixedSize(20, 20)
                    self._apply_themed_style(delete_label_button, """
                        QPushButton {
                            border: none;
                            border-radius: 3px;
                            background-color: transparent;
                            padding: 0px;
                        }
                        QPushButton:hover { background-color: $close_button_hover; }
                        QPushButton:pressed { background-color: $status_danger_bg; }
                    """)
                    delete_label_button.setCursor(Qt.CursorShape.PointingHandCursor)
                    delete_label_button.setToolTip("Delete this label field from the module")
                    delete_label_button.clicked.connect(
                        lambda _, btn=delete_label_button: self.delete_label(btn))
                    self.labels_table.setCellWidget(i, 4, delete_label_button)

    def show_labels_table_context_menu(self, position):
        """
        Right-click menu for field row(s) in the Module & Properties labels
        table. Lets the user tag a field (or several at once, via Ctrl/Shift
        multi-select) so it's easy to spot later — the tag shows as a chip
        here, and alongside the field name in the Module Details table of
        the Edit Test Case window.
        """
        index = self.labels_table.indexAt(position)
        if not index.isValid():
            return
        row = index.row()

        selected_module_item = getattr(self, '_current_module_item', None)
        try:
            if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
                return
        except RuntimeError:
            self._current_module_item = None
            return

        module_name = selected_module_item.data(0, Qt.ItemDataRole.UserRole)
        module_data = self.modules.get(module_name)
        if not module_data or 'labels' not in module_data:
            return

        # Right-clicking a row that's already part of a multi-row selection
        # acts on the whole selection; right-clicking outside the current
        # selection re-targets just that one row instead — the usual
        # multi-select right-click convention.
        selected_rows = sorted({idx.row() for idx in self.labels_table.selectionModel().selectedRows()})
        if row not in selected_rows:
            selected_rows = [row]

        rows = [r for r in selected_rows if 0 <= r < len(module_data['labels'])]
        if not rows:
            return

        labels = [module_data['labels'][r] for r in rows]
        any_existing_tag = any(get_label_tags(lbl) for lbl in labels)

        menu = QMenu(self)
        if len(rows) == 1:
            existing_tags = get_label_tags(labels[0])
            tag_action = QAction("🏷  Edit Tags..." if existing_tags else "🏷  Tag Field...", self)
        else:
            tag_action = QAction(f"🏷  Tag {len(rows)} Fields...", self)
        tag_action.triggered.connect(lambda: self._prompt_field_tag(module_name, rows))
        menu.addAction(tag_action)

        if any_existing_tag:
            remove_tag_action = QAction(
                "✕  Remove Tags" if len(rows) == 1 else "✕  Remove Tags from Selected", self
            )
            remove_tag_action.triggered.connect(lambda: self._set_field_tags(module_name, rows, []))
            menu.addAction(remove_tag_action)

        menu.addSeparator()

        # Configured values -> shows as a dropdown for this field wherever
        # it appears in the Edit Test Case window's Module Details table.
        any_existing_values = any(get_label_values(lbl) for lbl in labels)
        if len(rows) == 1:
            existing_values = get_label_values(labels[0])
            values_action = QAction("☰  Edit Values..." if existing_values else "☰  Configure Values...", self)
        else:
            values_action = QAction(f"☰  Configure Values for {len(rows)} Fields...", self)
        values_action.triggered.connect(lambda: self._prompt_field_values(module_name, rows))
        menu.addAction(values_action)

        if any_existing_values:
            remove_values_action = QAction(
                "✕  Remove Configured Values" if len(rows) == 1 else "✕  Remove Configured Values from Selected", self
            )
            remove_values_action.triggered.connect(lambda: self._set_field_values(module_name, rows, []))
            menu.addAction(remove_values_action)

        menu.exec(self.labels_table.viewport().mapToGlobal(position))

    def _prompt_field_tag(self, module_name, rows):
        """Opens a small dialog to set/edit one or more tags at once for
        one or more fields (rows is always a list, even for a single
        field). Lets the user attach any number of tags to a field, not
        just one."""
        module_data = self.modules.get(module_name)
        if not module_data or 'labels' not in module_data:
            return
        rows = [r for r in rows if 0 <= r < len(module_data['labels'])]
        if not rows:
            return

        if len(rows) == 1:
            label = module_data['labels'][rows[0]]
            field_name = label.get('name', 'this field')
            title = f"Tag Field — {field_name}"
            prefill = get_label_tags(label)
        else:
            # Prefill with the shared tags only if every selected field
            # already has the exact same set; otherwise start blank rather
            # than guessing which ones the user wants to keep.
            tag_sets = [tuple(get_label_tags(module_data['labels'][r])) for r in rows]
            prefill = list(tag_sets[0]) if len(set(tag_sets)) == 1 else []
            title = f"Tag {len(rows)} Fields"

        dialog = TagEditorDialog(self, title=title, initial_tags=prefill)
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        self._set_field_tags(module_name, rows, dialog.get_tags())

    def _set_field_tags(self, module_name, rows, tags):
        """Saves (or clears) the tag list across one or more fields in a
        single pass, then refreshes the labels table chip(s) and the
        Module Details view once (rather than once per field)."""
        module_data = self.modules.get(module_name)
        if not module_data or 'labels' not in module_data:
            return
        rows = [r for r in rows if 0 <= r < len(module_data['labels'])]
        if not rows:
            return

        field_names = []
        clean_tags = []
        for r in rows:
            label = module_data['labels'][r]
            field_names.append(label.get('name', 'this field'))
            clean_tags = set_label_tags(label, tags)

        self.save_modules_to_file()

        selected_module_item = getattr(self, '_current_module_item', None)
        if selected_module_item:
            self.display_module_details_and_screenshot(selected_module_item, 0)

        names_preview = ", ".join(field_names) if len(field_names) <= 4 else f"{len(field_names)} fields"
        if clean_tags:
            tags_preview = ", ".join(f"'{t}'" for t in clean_tags)
            self.statusBar().showMessage(f"Tagged {names_preview} as {tags_preview}.", 5000)
        else:
            self.statusBar().showMessage(f"Removed tags from {names_preview}.", 5000)

    def _prompt_field_values(self, module_name, rows):
        """Opens a dialog to configure the list of allowed values for one
        or more fields at once (rows is always a list, even for a single
        field). Once configured, that field's 'Value' box in the Edit Test
        Case window's Module Details table becomes a dropdown of these
        values instead of a plain text box."""
        module_data = self.modules.get(module_name)
        if not module_data or 'labels' not in module_data:
            return
        rows = [r for r in rows if 0 <= r < len(module_data['labels'])]
        if not rows:
            return

        if len(rows) == 1:
            label = module_data['labels'][rows[0]]
            field_name = label.get('name', 'this field')
            title = f"Configure Values — {field_name}"
            prefill = get_label_values(label)
        else:
            # Prefill with the shared values only if every selected field
            # already has the exact same list; otherwise start blank rather
            # than guessing which ones the user wants to keep.
            value_sets = [tuple(get_label_values(module_data['labels'][r])) for r in rows]
            prefill = list(value_sets[0]) if len(set(value_sets)) == 1 else []
            field_name = ""
            title = f"Configure Values for {len(rows)} Fields"

        dialog = ValuesEditorDialog(self, title=title, initial_values=prefill, field_name=field_name)
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        self._set_field_values(module_name, rows, dialog.get_values())

    def _set_field_values(self, module_name, rows, values):
        """Saves (or clears) the configured-values list across one or more
        fields in a single pass, then refreshes the Module Details view
        once (rather than once per field) so any open Edit Test Case
        window immediately reflects the change."""
        module_data = self.modules.get(module_name)
        if not module_data or 'labels' not in module_data:
            return
        rows = [r for r in rows if 0 <= r < len(module_data['labels'])]
        if not rows:
            return

        field_names = []
        clean_values = []
        for r in rows:
            label = module_data['labels'][r]
            field_names.append(label.get('name', 'this field'))
            clean_values = set_label_values(label, values)

        self.save_modules_to_file()

        selected_module_item = getattr(self, '_current_module_item', None)
        if selected_module_item:
            self.display_module_details_and_screenshot(selected_module_item, 0)

        names_preview = ", ".join(field_names) if len(field_names) <= 4 else f"{len(field_names)} fields"
        if clean_values:
            values_preview = ", ".join(f"'{v}'" for v in clean_values)
            self.statusBar().showMessage(f"Configured values for {names_preview}: {values_preview}.", 5000)
        else:
            self.statusBar().showMessage(f"Removed configured values from {names_preview}.", 5000)

    def delete_label(self, button):
        """
        Deletes a specific label from a module based on the button clicked.
        FIXED: Now correctly identifies the row of the clicked button.
        """
        # Find the row index by iterating through all rows and checking which one contains this button
        row_index = -1
        selected_module_item = getattr(self, '_current_module_item', None)
        try:
            if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
                return
        except RuntimeError:
            self._current_module_item = None
            return        
        for i in range(self.labels_table.rowCount()):
            cell_widget = self.labels_table.cellWidget(i, 4)
            if cell_widget == button:
                row_index = i
                break
        
        # If we couldn't find the button, return
        if row_index == -1:
            return
            
        selected_module_item = getattr(self, '_current_module_item', None)
        if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
            return
            
        module_name = selected_module_item.data(0, Qt.ItemDataRole.UserRole)
        module_data = self.modules.get(module_name)

        if module_data and 'labels' in module_data and 0 <= row_index < len(module_data['labels']):
            # Get the label name for the confirmation message
            label_name = module_data['labels'][row_index].get('name', 'this label')
            
            # Confirm deletion with the user
            reply = QMessageBox.question(
                self, 
                'Delete Label',
                f"Are you sure you want to delete the label '{label_name}'?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, 
                QMessageBox.StandardButton.No
            )
            
            if reply == QMessageBox.StandardButton.Yes:
                del module_data['labels'][row_index]
                self.save_modules_to_file()
                
                # Refresh the labels table to reflect the change
                self.labels_table.removeRow(row_index)
                
                # Clear the properties tree as the selection is now invalid
                self.properties_tree.clear()
                self.statusBar().showMessage(f"Label '{label_name}' deleted from module '{module_name}'.", 5000)

    def display_selected_label_properties(self, row, column):
        """Displays properties of the selected label in the properties tree and selects text in preview."""
        if getattr(self, "_updating_properties", False):
            return
        self._updating_properties = True

        try:
            self.properties_tree.clear()
            selected_module_item = getattr(self, '_current_module_item', None)
            try:
                if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
                    return
            except RuntimeError:
                self._current_module_item = None
                return
            if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
                return

            module_name = selected_module_item.data(0, Qt.ItemDataRole.UserRole)
            module_data = self.modules.get(module_name)

            if module_data and 'labels' in module_data:
                # remove bolding from all rows
                for i in range(self.labels_table.rowCount()):
                    for j in range(self.labels_table.columnCount() - 1):
                        item = self.labels_table.item(i, j)
                        if item:
                            font = item.font()
                            font.setBold(False)
                            item.setFont(font)

                # make selected row bold
                for j in range(self.labels_table.columnCount() - 1):
                    item = self.labels_table.item(row, j)
                    if item:
                        font = item.font()
                        font.setBold(True)
                        item.setFont(font)

                label_data = module_data['labels'][row]
                properties = {
                    "Text": label_data.get('name', ''),
                    "Row": str(label_data.get('row', '')),
                    "Column": str(label_data.get('column', '')),
                    "Length": str(label_data.get('length', 'N/A'))
                }

                for key, value in properties.items():
                    prop_item = QTreeWidgetItem(self.properties_tree, [key, value])  # ← CHANGED
                    prop_item.setForeground(0, QColor(theme_color('primary_color', get_active_theme())))                    # ← ADD
                    prop_item.setForeground(1, QColor(theme_color('primary_color', get_active_theme())))                    # ← ADD
                
                # ✅ NEW: Select the corresponding text in PCOMM preview
                self.select_text_in_preview(
                    label_data.get('row', 1),
                    label_data.get('column', 1),
                    label_data.get('length', 0)
                )

        finally:
            self._updating_properties = False

    def handle_test_case_rename_finish(self, item, column):
        """Handles renaming a test case from the tree."""
        
        item_data = item.data(0, Qt.ItemDataRole.UserRole)
        if isinstance(item_data, dict):
            # This is a folder item; handle folder rename separately
            return        
        
        if self.test_case_tree_root is None:
            return
        parent = item.parent()
        parent_data = parent.data(0, Qt.ItemDataRole.UserRole) if parent else None
        is_in_folder = isinstance(parent_data, dict) and parent_data.get('type') == 'folder'
        if parent is not self.test_case_tree_root and not is_in_folder:
            return
        if not item.data(0, Qt.ItemDataRole.UserRole):
            return

        new_name = item.text(0).strip()
        old_name = item.data(0, Qt.ItemDataRole.UserRole)

        if not new_name:
            item.setText(0, old_name)
            return

        if new_name == old_name:
            return

        if new_name in self.test_cases:
            QMessageBox.warning(self, "Duplicate Name",
                f"A test case named '{new_name}' already exists.")
            item.setText(0, old_name)
            return

        # Rename in data
        self.test_cases[new_name] = self.test_cases.pop(old_name)
        self.test_cases[new_name]['name'] = new_name
        item.setData(0, Qt.ItemDataRole.UserRole, new_name)
        self.save_test_cases_to_file()
        self.statusBar().showMessage(f"Renamed test case to '{new_name}'.", 5000)


    def handle_rename_finish(self, item, column):
        """Handles the completion of a module rename operation."""
        # If no modules exist, module_tree_root is None — ignore all item changes
        if self.module_tree_root is None:
            return
        # Only handle items that are direct children of the module root
        if item.parent() != self.module_tree_root:
            return
        # Ignore placeholder items (they have no UserRole data)
        if not item.data(0, Qt.ItemDataRole.UserRole):
            return

        new_name = item.text(0)
        old_name = item.data(0, Qt.ItemDataRole.UserRole)
        
        if old_name and new_name != old_name and new_name not in self.modules:
            # Rename the associated screenshot file
            old_path = self.modules[old_name].get("screenshot")
            new_path = os.path.join(get_appdata_dir(), 'Modules Screenshots', f'{new_name}.png')
            if old_path and os.path.exists(old_path):
                try:
                    os.rename(old_path, new_path)
                except Exception as e:
                    print(f"Error renaming screenshot file: {e}")
                    new_path = old_path # Revert if renaming fails

            self.modules[new_name] = self.modules.pop(old_name)
            self.modules[new_name]["screenshot"] = new_path # Update the path
            self.modules[new_name].setdefault("sys_id", self._generate_sys_id())
            self._rebuild_modules_sys_id_index()
            item.setData(0, Qt.ItemDataRole.UserRole, new_name)
            self.save_modules_to_file()
            self._propagate_module_rename_to_test_cases(old_name, new_name)
            self.statusBar().showMessage(f"Renamed module from '{old_name}' to '{new_name}'", 5000)
        elif new_name == old_name:
            # Name did not change, do nothing
            pass
        else:
            QMessageBox.warning(self, "Invalid Name", f"The name '{new_name}' is already in use or invalid.")
            self.update_module_tree() # Revert the item back to the old name
            
    def handle_label_edit_finish(self, row, column):
        """
        Handles the completion of a cell edit in the labels table,
        validates input, updates the internal data, and refreshes the UI.
        """
        # Block signals to prevent infinite loops when we programmatically change a cell
        self.labels_table.blockSignals(True)
        
        try:
            selected_module_item = getattr(self, '_current_module_item', None)
            if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
                self.labels_table.blockSignals(False)
                return
        except RuntimeError:
            self._current_module_item = None
            self.labels_table.blockSignals(False)
            return        
        
        selected_module_item = getattr(self, '_current_module_item', None)
        if not selected_module_item or not isinstance(selected_module_item.data(0, Qt.ItemDataRole.UserRole), str):
            self.labels_table.blockSignals(False)
            return

        module_name = selected_module_item.data(0, Qt.ItemDataRole.UserRole)
        module_data = self.modules.get(module_name)
        
        if module_data and 'labels' in module_data and row < len(module_data['labels']):
            label = module_data['labels'][row]
            cell_item = self.labels_table.item(row, column)
            if cell_item is None:
                self.labels_table.blockSignals(False)
                return
            new_value = cell_item.text()

            try:
                if column == 0:  # Field name
                    label['name'] = new_value
                    message = f"Updated Field name to '{new_value}'."
                elif column == 1:  # Row
                    label['row'] = int(new_value)
                    message = f"Updated Row to '{new_value}'."
                elif column == 2:  # Column
                    label['column'] = int(new_value)
                    message = f"Updated Column to '{new_value}'."
                elif column == 3:  # NEW: Handle editing of the Length column
                    label['length'] = int(new_value)
                    message = f"Updated Length to '{new_value}'."
                else:
                    message = "No change."
                    
                # Update the Properties Tree with the latest data
                self.display_selected_label_properties(row, column)
                
                # Save the updated modules data to the file
                self.save_modules_to_file()
                
                self.statusBar().showMessage(message, 5000)

            except ValueError:
                # Handle case where non-numeric input is provided for row/column/length
                QMessageBox.warning(self, "Invalid Input", "Row, Column, and Length values must be numbers.")
                # Revert the cell to its original value from the data
                if column == 1:
                    self.labels_table.setItem(row, column, QTableWidgetItem(str(label.get('row', ''))))
                elif column == 2:
                    self.labels_table.setItem(row, column, QTableWidgetItem(str(label.get('column', ''))))
                elif column == 3:
                    self.labels_table.setItem(row, column, QTableWidgetItem(str(label.get('length', ''))))
        
        self.labels_table.blockSignals(False)

